Object.assign(window.TEM8_DICTIONARY, {"period":{"media":{"uk":"media/uk/period__gb_1.mp3","us":"media/us/period__us_1.mp3"},"oxford":{"phon":"ˈpɪəriəd","pos":"noun","senses":[{"en":"a particular length of time","cn":"一段时间；时期","sc":"length of time","ex":{"en":"a long/an extended period","cn":"很长的／漫长的时期"}},{"en":"a length of time in the life of a particular person or in the history of a particular country","cn":"（人生或国家历史的）阶段，时期，时代","sc":"length of time","ex":{"en":"Which period of history would you most like to have lived in?","cn":"你最喜欢生活在哪一个历史时期？"}},{"en":"a length of time which is a division of an era. A period is divided into epochs.","cn":"纪（地质年代，代下分纪，纪下分世）","lab":"geology","sc":"length of time","ex":{"en":"the Jurassic period","cn":"侏罗纪"}},{"en":"any of the parts that a day is divided into at a school, college, etc. for study","cn":"节；学时；课","sc":"lesson","ex":{"en":"‘What do you have next period?’ ‘French.’","cn":"“你下一节是什么课？”“法语。”"}},{"en":"the flow of blood each month from the body of a woman who is not pregnant","cn":"月经；经期；例假","sc":"woman","ex":{"en":"period pains","cn":"痛经"}},{"en":"the mark ( . ) used at the end of a sentence and in some abbreviations, for example e.g.","cn":"句点；句号","lab":"North American English","sc":"punctuation"},{"en":"used at the end of a sentence to emphasize that there is nothing more to say about a subject","cn":"（用于句末，强调不再多说）到此为止，就是这话","ex":{"en":"The answer is no, period!","cn":"答复是不，不再说了！"},"pos":"adverb"},{"en":"having a style typical of a particular time in history","cn":"具有某个时代特征的","ex":{"en":"period costumes/furniture","cn":"代表某一时期的服装／家具"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一段时间；时期","en":"A period is a length of time.","ex":{"en":"This crisis might last for a long period of time.","cn":"这次危机可能持续很长时间。"}},{"pos":"N-COUNT 可数名词","cn":"（个人、组织或社会的）阶段，时期，时代","en":"A period in the life of a person, organization, or society is a length of time which is remembered for a particular situation or activity.","ex":{"en":"...a period of economic good health and expansion","cn":"经济健康发展并且不断扩张的一段时期"}},{"pos":"N-COUNT 可数名词","cn":"（历史上的）阶段，时期","en":"A particular length of time in history is sometimes called a period. For example, you can talk about the Victorian period or the Elizabethan period in Britain.","ex":{"en":"...the Roman period","cn":"罗马帝国时代"}},{"pos":"ADJ 形容词","cn":"（服装、家具、乐器）过去的，古代的，具有某个时代特征的","en":"Period costumes, furniture, and instruments were made at an earlier time in history, or look as if they were made then.","ex":{"en":"...dressed in full period costume.","cn":"穿着宽松的古装"}},{"pos":"N-COUNT 可数名词","cn":"（练习、训练、学习的）时间，时段","en":"Exercise, training, or study periods are lengths of time that are set aside for exercise, training, or study.","ex":{"en":"They accompanied him during his exercise periods.","cn":"练习的时候他们陪着他。"}},{"pos":"N-COUNT 可数名词","cn":"课；课时；节","en":"At a school or college, a period is one of the parts that the day is divided into during which lessons or other activities take place.","ex":{"en":"...periods of private study.","cn":"自习课"}},{"pos":"N-COUNT 可数名词","cn":"月经","en":"When a woman has a period, she bleeds from her womb. This usually happens once a month, unless she is pregnant."},{"pos":"ADV 副词","cn":"到此为止；不再说了","en":"Some people say period after stating a fact or opinion when they want to emphasize that they are definite about something and do not want to discuss it further.","ex":{"en":"I don't want to do it, period.","cn":"我不想做，这事就到此为止吧。"}},{"pos":"N-COUNT 可数名词","cn":"句号","en":"A period is the punctuation mark (.) which you use at the end of a sentence when it is not a question or an exclamation."}]},"examples":[{"en":"This compares with a 4% increase for the same period last year.","cn":"这个数字与去年同期的 4% 升幅相若。"},{"en":"All these changes happened over a period of time.","cn":"所有这些变化都是在一段时间内发生的。"}]},"penis":{"oxford":{"phon":"ˈpiːnɪs","pos":"noun","senses":[{"en":"the organ on the body of a man or male animal that is used for urinating and sex","cn":"阴茎"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"阴茎","en":"A man's penis is the part of his body that he uses when urinating and when having sex."}]},"media":{"uk":"media/uk/penis__gb_1.mp3","us":"media/us/penis__us_1.mp3"}},"pedagogical":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"教学法的；教育学的","en":"Pedagogical means concerning the methods and theory of teaching.","ex":{"en":"...the pedagogical methods used in the classroom.","cn":"课堂上使用的教学法"}}]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdepedagogical.mp3","us":"media/ldoce/hwd/ame/3/laadpedagogical.mp3"}},"percentage":{"media":{"uk":"media/uk/percentage__gb_1.mp3","us":"media/us/percentage__us_1.mp3"},"oxford":{"phon":"pəˈsentɪdʒ","pos":"noun","senses":[{"en":"the number, amount or rate of something, expressed as if it is part of a total that is 100; a part or share of a whole","cn":"百分率；百分比","g":"[countable + singular or plural verb]","ex":{"en":"What percentage of the population is/are overweight?","cn":"体重超重的人占人口多大的百分比？"}},{"en":"a share of the profits of something","cn":"利润的分成；提成","g":"[countable, usually singular]","ex":{"en":"He gets a percentage for every car sold.","cn":"他每售出一辆车便可得到一份提成。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"百分比；百分率","en":"A percentage is a fraction of an amount expressed as a particular number of hundredths of that amount.","ex":{"en":"Only a few vegetable-origin foods have such a high percentage of protein.","cn":"只有几种蔬菜食品有如此高的蛋白质含量。"}}]},"examples":[{"en":"A high percentage of the female staff are part-time workers.","cn":"女职员中，兼职工作的人占很高的比例。"},{"en":"What percentage of the population is/are overweight?","cn":"身体超重的人占人口多大的百分比？"}]},"pea":{"media":{"img":["media/pic/peas_beans_comp.jpg","media/thumb/pea.jpg"],"uk":"media/uk/pea__gb_1.mp3","us":"media/us/pea__us_1.mp3"},"oxford":{"phon":"piː","pos":"noun","senses":[{"en":"a small round green seed, eaten as a vegetable. Several peas grow together inside a long thin pod on a climbing plant also called a pea.","cn":"豌豆；豌豆粒","ex":{"en":"frozen peas","cn":"冷冻豌豆"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"豌豆","en":"Peas are round green seeds which grow in long thin cases and are eaten as a vegetable."}]},"examples":[{"en":"frozen peas","cn":"冷冻豌豆"},{"en":"pea soup","cn":"豌豆汤"}]},"penetrate":{"media":{"uk":"media/uk/penetrate__gb_1.mp3","us":"media/us/penetrate__us_1.mp3"},"oxford":{"phon":"ˈpenətreɪt","pos":"verb","senses":[{"en":"to go into or through something","cn":"穿过；进入","g":"[transitive, intransitive]","lab":"figurative","ex":{"en":"The knife had penetrated his chest.","cn":"刀子刺入了他的胸膛。"}},{"en":"to succeed in entering or joining an organization, a group, etc. especially when this is difficult to do","cn":"渗透，打入（组织、团体等）","g":"[transitive, intransitive]","ex":{"en":"They had penetrated airport security.","cn":"他们已打入机场保安组织。"}},{"en":"to see or show a way into or through something","cn":"看透；透过…看见","g":"[transitive]","ex":{"en":"Our eyes could not penetrate the darkness.","cn":"我们的眼睛在黑暗中什么也看不见。"}},{"en":"to understand or discover something that is difficult to understand or is hidden","cn":"洞察；发现；揭示","g":"[transitive]","ex":{"en":"Science can penetrate many of nature's mysteries.","cn":"科学能揭示自然界的许多奥秘。"}},{"en":"to be understood or realized by somebody","cn":"被领悟；被理解","g":"[intransitive, transitive]","ex":{"en":"I was at the door before his words penetrated.","cn":"我走到门口才听懂了他说的话。"}},{"en":"to put the penis into the vagina or anus of a sexual partner","cn":"（以阴茎）插入","g":"[transitive]"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"渗入；进入；穿过；穿透","en":"If something or someone penetrates a physical object or an area, they succeed in getting into it or passing through it.","ex":{"en":"X-rays can penetrate many objects","cn":"X射线能够穿透很多物体。"}},{"pos":"VERB 动词","cn":"进入；跻身","en":"If someone penetrates an organization, a group, or a profession, they succeed in entering it although it is difficult to do so.","ex":{"en":"...the continuing failure of women to penetrate the higher levels of engineering","cn":"女性一直未能跻身工程领域的更高层"}},{"pos":"VERB 动词","cn":"打入，渗透（敌人或竞争对手内部）","en":"If someone penetrates an enemy group or a rival organization, they succeed in joining it in order to get information or cause trouble.","ex":{"en":"The CIA had requested our help to penetrate a drugs ring operating out of Munich","cn":"美国中央情报局已请求我们协助其打入在慕尼黑市外活动的贩毒集团。"}},{"pos":"VERB 动词","cn":"进入，打入（市场或地区）","en":"If a company or country penetrates a market or area, they succeed in selling their products there.","ex":{"en":"There have been around 15 attempts from outside France to penetrate the market.","cn":"大约已经有15家外国公司试图进入法国市场。"}},{"pos":"VERB 动词","cn":"了解；洞察；领悟","en":"If you penetrate something that is difficult to understand, you succeed in understanding it.","ex":{"en":"...long answers that were often difficult to penetrate.","cn":"往往难以理解的冗长回答"}}]},"examples":[{"en":"None of my advice seems to have penetrated his thick skull (= he has not listened to any of it).","cn":"他那木脑袋似乎一点也听不进我的忠告。"},{"en":"( figurative ) The war penetrates every area of the nation's life.","cn":"战争波及到全国国民生活的各个领域。"}]},"performers":{"lemma":"performer","media":{"uk":"media/uk/performer__gb_1.mp3","us":"media/us/performer__us_1.mp3"}},"pet":{"media":{"uk":"media/uk/pet__gb_1.mp3","us":"media/us/pet__us_1.mp3"},"oxford":{"phon":"pet","pos":"noun","senses":[{"en":"an animal, a bird, etc. that you have at home for pleasure, rather than one that is kept for work or food","cn":"宠物","ex":{"en":"Do you have any pets?","cn":"你有没有养宠物？"}},{"en":"a person who is given special attention by somebody, especially in a way that seems unfair to other people","cn":"宠儿；宝贝；红人","lab":"usually disapproving","ex":{"en":"She's the teacher's pet.","cn":"她是老师的宠儿。"}},{"en":"used when speaking to somebody to show kind feelings or to be friendly","cn":"（昵称）宝贝儿，乖乖","lab":"British English, informal，，","ex":{"en":"What's wrong, pet?","cn":"怎么啦，宝贝儿？"}},{"en":"to touch or move your hand gently over an animal or a child in a kind and loving way","cn":"抚摸；（爱抚地）摩挲","g":"[transitive]","ex":{"en":"He petted the dog and ruffled its fur.","cn":"他抚摩着那条狗，拨弄着它的软毛。"},"pos":"verb"},{"en":"to kiss and touch each other in a sexual way","cn":"亲吻爱抚","g":"[intransitive]","lab":"informal","pos":"verb"},{"en":"that you are very interested in","cn":"很喜欢的；钟爱的；很感兴趣的","ex":{"en":"his pet subject/theory/project, etc.","cn":"他所喜爱的学科、理论、项目等"},"pos":"adjective"},{"en":"an artificial substance used to make materials for packaging food, including plastic drinks bottles (the abbreviation for ‘polyethylene terephthalate’)","cn":"聚对苯二甲酸乙二醇酯（用于制造食品饮料包装材料，全写为 polyethylene terephthalate）"},{"en":"a process that produces an image of your brain or of another part inside your body (the abbreviation for ‘positron emission tomography’)","cn":"正电子发射断层显像（大脑或其他体内部位的成像，全写为 positron emission tomography）","lab":"medical","ex":{"en":"a PET scan","cn":"正电子发射断层扫描"}},{"en":"a British test, now called ‘B1 Preliminary’, that measures a person’s ability to speak and write English as a foreign language at an intermediate level (the abbreviation for ‘Preliminary English Test’)","cn":"初级英语考试，剑桥通用英语第二级（现称 B1 Preliminary，英国考试，考查英语作为外语者的中级口语和写作能力，全写为 Preliminary English Test）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"宠物","en":"A pet is an animal that you keep in your home to give you company and pleasure.","ex":{"en":"It is plainly cruel to keep turtles as pets.","cn":"显然，养海龟作宠物十分残忍。"}},{"pos":"ADJ 形容词","cn":"很喜欢的；钟爱的","en":"Someone's pet theory, project, or subject is one that they particularly support or like.","ex":{"en":"He would not stand by and let his pet project be killed off","cn":"他不会袖手旁观任由他最看好的项目被扼杀。"}},{"pos":"N-VOC 称呼名词","cn":"（表示喜欢、友好的称呼）宝贝，乖乖","en":"Some people call the person they are talking to 'pet' to show affection or friendliness.","ex":{"en":"It's all right, pet, let me do it.","cn":"没事儿，宝贝儿，让我来吧。"}},{"pos":"VERB 动词","cn":"抚摸；（爱抚地）摩挲","en":"If you pet a person or animal, you touch them in an affectionate way.","ex":{"en":"The policeman reached down and petted the wolfhound","cn":"警察伸手抚摸那只猎狼犬。"}}]},"examples":[{"en":"a PET scan","cn":"正电子发射扫描"},{"en":"They have two pets - a cat and a dog.","cn":"他们有两只宠物﹐一只猫和一只狗。"}]},"personality":{"media":{"uk":"media/uk/personality__gb_1.mp3","us":"media/us/personality__us_1.mp3"},"oxford":{"phon":"ˌpɜːsəˈnæləti","pos":"noun","senses":[{"en":"the various aspects of a person’s character that combine to make them different from other people","cn":"性格；个性；人格","g":"[countable, uncountable]","ex":{"en":"His wife has a strong personality.","cn":"他妻子的个性很强。"}},{"en":"the qualities of a person’s character that make them interesting and attractive","cn":"魅力；气质；气度","g":"[uncountable]","ex":{"en":"We need someone with lots of personality to head the project.","cn":"我们需要一位富有魅力的人来主持这个项目。"}},{"en":"a famous person, especially one who works in entertainment or sport","cn":"名人，风云人物（尤指娱乐界或体育界的）","g":"[countable]","ex":{"en":"a well-known TV/radio/sports personality","cn":"电视／广播／体育明星"}},{"en":"a person whose strong character attracts attention","cn":"性格鲜明的人；个性突出的人","g":"[countable]","ex":{"en":"Their son is a real personality.","cn":"他们的儿子真是有个性。"}},{"en":"the qualities of a place or thing that make it interesting and different","cn":"特色；特征","g":"[uncountable]","ex":{"en":"The problem with many modern buildings is that they lack personality.","cn":"许多现代建筑物的问题在于缺乏特色。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"个性；性格","en":"Your personality is your whole character and nature.","ex":{"en":"She has such a kind, friendly personality","cn":"她个性善良友好。"}},{"pos":"N-VAR 可变名词","cn":"强烈的（或鲜明的)个性;个性鲜明的人","en":"If someone has personality or is a personality, they have a strong and lively character.","ex":{"en":"...a woman of great personality","cn":"极有个性的女人"}},{"pos":"N-COUNT 可数名词","cn":"（娱乐界或体育界的）名流，名人，风云人物","en":"You can refer to a famous person, especially in entertainment, broadcasting, or sport, as a personality.","ex":{"en":"...the radio and television personality, Jimmy Saville.","cn":"广播电视界风云人物，吉米·萨维尔"}}]},"examples":[{"en":"There are likely to be tensions and personality clashes in any social group.","cn":"任何社会团体都容易出现关系紧张和性格冲突。"},{"en":"We need someone with lots of personality to head the project.","cn":"我们需要一位富有魅力的人来主持这个项目。"}]},"personalized":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to put your name or initial s on something, or to decorate it in your own way, to show that it belongs to you","cn":""},{"en":"to design or change something so that it is suitable for a particular person","cn":""}]},"examples":[{"en":"Why not do something to personalize your office?","cn":"","src":"ld"},{"en":"All the products can be personalized to the client’s exact requirements.","cn":"","src":"ld"}],"media":{"uk":"media/uk/personalized__gb_1.mp3","us":"media/us/personalized__us_1.mp3"},"oxford":{"phon":"ˈpɜːsənəlaɪzd","pos":"adjective","senses":[{"en":"marked in some way to show that it belongs to a particular person","cn":"在…上标明主人姓名","lab":"British English","ex":{"en":"a personalized number plate (= on a car)","cn":"个性化的车牌"}},{"en":"designed or changed so that it is suitable for the needs of a particular person","cn":"为个人特制（或专设）","ex":{"en":"a highly personalized service","cn":"高度个性化的服务"}},{"en":"referring to particular people when discussing a general subject","cn":"针对个人；个人化","ex":{"en":"She faced personalized attacks on her record as Health Minister.","cn":"她作为卫生部长的记录面临着个人化的攻击。"}}]}},"pessimist":{"oxford":{"phon":"ˈpesɪmɪst","pos":"noun","senses":[{"en":"a person who always expects bad things to happen","cn":"悲观主义者；悲观论者","ex":{"en":"You don't have to be a pessimist to realize that we're in trouble.","cn":"不是悲观论者也能意识到我们有了麻烦。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"悲观主义者；悲观论者","en":"A pessimist is someone who thinks that bad things are going to happen.","ex":{"en":"I'm a natural pessimist; I usually expect the worst","cn":"我是天生的悲观主义者。我总是做最坏的打算。"}}]},"media":{"uk":"media/uk/pessimist__gb_1.mp3","us":"media/us/pessimist__us_1.mp3"},"examples":[{"en":"You don't have to be a pessimist to realize that we're in trouble.","cn":"不是悲观论者也能意识到我们有了麻烦。"},{"en":"Don’t be such a pessimist!","cn":"别这么悲观！"}]},"petrol":{"oxford":{"phon":"ˈpetrəl","pos":"noun","senses":[{"en":"a liquid obtained from petroleum, used as fuel in car engines, etc.","cn":"汽油","ex":{"en":"to fill a car up with petrol","cn":"给汽车油箱装满汽油"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"汽油","en":"Petrol is a liquid which is used as a fuel for motor vehicles."}]},"media":{"uk":"media/uk/petrol__gb_1.mp3","us":"media/us/petrol__us_1.mp3"},"examples":[{"en":"to fill a car up with petrol","cn":"给汽车油箱装满汽油"},{"en":"the petrol tank of a car","cn":"汽车的油箱"}]},"perspective":{"media":{"uk":"media/uk/perspective__gb_1.mp3","us":"media/us/perspective__us_1.mp3"},"oxford":{"phon":"pəˈspektɪv","pos":"noun","senses":[{"en":"a particular attitude towards something; a way of thinking about something","cn":"态度；观点；思考方法","g":"[countable]","ex":{"en":"a global perspective","cn":"全球的视角"}},{"en":"the ability to think about problems and decisions in a reasonable way without making them seem worse or more important than they really are","cn":"客观判断力；权衡轻重的能力","g":"[uncountable]","ex":{"en":"She was aware that she was losing all sense of perspective.","cn":"她意识到自己正在失掉一切正确判断的能力。"}},{"en":"the art of creating an effect of depth and distance in a picture by representing people and things that are far away as being smaller than those that are nearer the front","cn":"透视法","g":"[uncountable]","ex":{"en":"The artist plays with perspective to confuse the eye.","cn":"艺术家利用透视来迷惑眼睛。"}},{"en":"a view, especially one in which you can see far into the distance","cn":"景观；远景","g":"[countable]","lab":"formal","ex":{"en":"a perspective of the whole valley","cn":"山谷全景"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指受到某种思想、经验影响的）思考方法，态度，观点，角度","en":"A particular perspective is a particular way of thinking about something, especially one that is influenced by your beliefs or experiences.","ex":{"en":"He says the death of his father 18 months ago has given him a new perspective on life","cn":"他说18个月前父亲的去世让他对人生有了新的认识。"}},{"pos":"PHRASE 短语","cn":"正确/不正确地看待（或判断）","en":"If you get something in perspective or into perspective, you judge its real importance by considering it in relation to everything else. If you get something out of perspective, you fail to judge its real importance in relation to everything else.","ex":{"en":"Remember to keep things in perspective","cn":"记住要客观看待事物。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"透视画法","en":"Perspective is the art of making some objects or people in a picture look further away than others."}]},"examples":[{"en":"His experience abroad provides a wider perspective on the problem.","cn":"他在国外的经历使他以更广阔的视角看待这个问题。"},{"en":"She was aware that she was losing all sense of perspective.","cn":"她意识到自己正在失掉一切正确判断的能力。"}]},"pens":{"lemma":"pen","media":{"uk":"media/uk/pen__gb_1.mp3","us":"media/us/pen__us_1.mp3"}},"persist":{"oxford":{"phon":"pəˈsɪst","pos":"verb","senses":[{"en":"to continue to do something despite difficulties or opposition, in a way that can seem unreasonable","cn":"顽强地坚持；执着地做","g":"[intransitive, transitive]","ex":{"en":"Why do you persist in blaming yourself for what happened?","cn":"你何必为已发生的事没完没了地自责？"}},{"en":"to continue to exist","cn":"维持；保持；持续存在","g":"[intransitive]","ex":{"en":"The belief that the earth was flat persisted for many centuries.","cn":"地球是平的这一信念持续了许多个世纪。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（不喜欢的事物）继续存在","en":"If something undesirable persists, it continues to exist.","ex":{"en":"Contact your doctor if the cough persists","cn":"如果还是咳嗽就去看医生。"}},{"pos":"VERB 动词","cn":"顽强坚持；执著","en":"If you persist in doing something, you continue to do it, even though it is difficult or other people are against it.","ex":{"en":"Why does Britain persist in running down its defence forces?","cn":"为什么英国要坚持消减其军事防御力量？"}}]},"media":{"uk":"media/uk/persist__gb_1.mp3","us":"media/us/persist__us_1.mp3"},"examples":[{"en":"Why do you persist in blaming yourself for what happened?","cn":"你何必为已发生的事没完没了地自责？"},{"en":"If the symptoms persist, consult your doctor.","cn":"如果症状持续不退，就得去看医生。"}]},"peasantry":{"media":{"uk":"media/uk/peasantry__gb_1.mp3","us":"media/us/peasantry__us_1.mp3"},"oxford":{"phon":"ˈpezntri","pos":"noun","senses":[{"en":"all the peasants in a region or country","cn":"（统称）（一个地区或国家的）农民","ex":{"en":"the local peasantry","cn":"当地的农民"}}]},"collins":{"senses":[{"pos":"N-SING-COLL 单数集合名词","cn":"（泛指一国的）农民","en":"You can refer to all the peasants in a particular country as the peasantry.","ex":{"en":"The Russian peasantry stood on the brink of disappearance.","cn":"俄罗斯农民濒临消亡。"}}]},"examples":[{"en":"the local peasantry","cn":"当地的农民"}]},"permanently":{"oxford":{"phon":"ˈpɜːmənəntli","pos":"adverb","senses":[{"en":"in a way that lasts for a long time or for all time in the future; in a way that exists all the time","cn":"永久地；永恒地；长久地","ex":{"en":"The stroke left his right side permanently damaged.","cn":"中风使他的右半身永久受损。"}}]},"media":{"uk":"media/uk/permanently__gb_1.mp3","us":"media/us/permanently__us_1.mp3"},"examples":[{"en":"The stroke left his right side permanently damaged.","cn":"中风使他的右半身永久受损。"},{"en":"She had decided to settle permanently in France.","cn":"她已经决定永久定居法国。"}]},"personification":{"media":{"uk":"media/uk/personification__gb_1.mp3","us":"media/us/personification__us_1.mp3"},"oxford":{"phon":"pəˌsɒnɪfɪˈkeɪʃn","pos":"noun","senses":[{"en":"a person who has a lot of a particular quality or characteristic","cn":"体现某品质或特点的人；化身；典型","g":"[countable, usually singular]","ex":{"en":"She was the personification of elegance.","cn":"她是典雅的化身。"}},{"en":"the practice of representing objects, qualities, etc. as humans, in art and literature; an object, quality, etc. that is represented in this way","cn":"拟人；人格化；拟人化的东西（或品质等）","g":"[uncountable, countable]","ex":{"en":"the personification of autumn in Keats’s poem","cn":"济慈诗歌中对秋天的拟人化处理"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"体现某种品质（或特点）的人；典型；化身","en":"If you say that someone is the personification of a particular thing or quality, you mean that they are a perfect example of that thing or that they have a lot of that quality.","ex":{"en":"Janis Joplin was the personification of the '60s female rock singer","cn":"贾尼斯·乔普林是20世纪60年代摇滚女歌手的代表。"}},{"pos":"N-VAR 可变名词","cn":"拟人化；象征","en":"A personification of something abstract is its representation in the form of a person.","ex":{"en":"...personifications of the attributes of Justice, Prudence and Truth.","cn":"正义、审慎和真理的化身"}}]},"examples":[{"en":"the personification of autumn in Keats's poem","cn":"济慈诗歌中对秋天的拟人化"},{"en":"She was the personification of elegance.","cn":"她是典雅的化身。"}]},"permanent":{"media":{"uk":"media/uk/permanent__gb_1.mp3","us":"media/us/permanent__us_1.mp3"},"oxford":{"phon":"ˈpɜːmənənt","pos":"adjective","senses":[{"en":"lasting for a long time or for all time in the future; existing all the time","cn":"永久的；永恒的；长久的","ex":{"en":"She was unable to find a permanent job.","cn":"她找不到固定工作。"}},{"en":"a perm (= a way of changing the style of your hair by using chemicals to create curls that last for several months)","cn":"卷发；烫发","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"永久的；永恒的","en":"Something that is permanent lasts for ever.","ex":{"en":"Heavy drinking can cause permanent damage to the brain","cn":"酗酒能造成永久性大脑损伤。"}},{"pos":"ADJ 形容词","cn":"（尤指问题或困难）不断出现的，一直存在的","en":"You use permanent to describe situations or states that keep occurring or which seem to exist all the time; used especially to describe problems or difficulties.","ex":{"en":"...a permanent state of tension","cn":"长久以来的紧张局势"}},{"pos":"ADJ 形容词","cn":"（员工）终生的,长期的","en":"A permanent employee is one who is employed for an unlimited length of time.","ex":{"en":"At the end of the probationary period you will become a permanent employee.","cn":"试用期结束后,你将成为长期雇员。"}},{"pos":"ADJ 形容词","cn":"（家庭住址）固定的","en":"Your permanent home or your permanent address is the one at which you spend most of your time or the one that you return to after having stayed in other places.","ex":{"en":"York Cottage was as near to a permanent home as the children knew","cn":"在孩子们眼中,约克小屋最像一个安定的家。"}},{"pos":"N-COUNT 可数名词","cn":"卷发；烫发","en":"A permanent is a treatment where a hair stylist curls your hair and treats it with a chemical so that it stays curly for several months."}]},"examples":[{"en":"The accident has not done any permanent damage.","cn":"那场事故没有造成什么永久性损伤。"},{"en":"The stroke left his right side permanently damaged.","cn":"中风使他的右半身永久受损。"}]},"performs":{"lemma":"perform","media":{"uk":"media/uk/perform__gb_1.mp3","us":"media/us/perform__us_1.mp3"}},"peaceful":{"media":{"uk":"media/uk/peaceful__gb_1.mp3","us":"media/us/peaceful__us_1.mp3"},"oxford":{"phon":"ˈpiːsfl","pos":"adjective","senses":[{"en":"not involving a war, violence or argument","cn":"不诉诸战争（或暴力、争论）的；和平的","ex":{"en":"a peaceful protest/demonstration","cn":"和平抗议／示威"}},{"en":"quiet and calm; not worried or upset in any way","cn":"安静的；平静的","ex":{"en":"a peaceful atmosphere","cn":"宁静的气氛"}},{"en":"trying to create peace or to live in peace; not liking violence or argument","cn":"爱好和平的；和睦的；寻求和平的","ex":{"en":"a peaceful religion/society","cn":"爱好和平的宗教／社会"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"和平的；不诉诸战争的","en":"Peaceful activities and situations do not involve war.","ex":{"en":"He has attempted to find a peaceful solution to the Ossetian conflict","cn":"他试图寻求和平解决奥赛梯冲突的方案。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"和平的；非暴力的；未引起骚乱的","en":"Peaceful occasions happen without violence or serious disorder.","ex":{"en":"The farmers staged a noisy but peaceful protest outside the headquarters of the organization","cn":"农场主在该组织总部外进行了喧闹而和平的抗议。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"平和的；爱好和平的","en":"Peaceful people are not violent and try to avoid quarrelling or fighting with other people.","ex":{"en":"...warriors who killed or enslaved the peaceful farmers.","cn":"杀害或奴役本分农民的武士"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"宁静的；平静的；无人打扰的","en":"A peaceful place or time is quiet, calm, and free from disturbance.","ex":{"en":"...a peaceful Georgian house in the heart of Dorset","cn":"多塞特腹地一幢宁静的乔治王朝风格的房子"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"安详的；平和的；平静的","en":"Someone who feels or looks peaceful feels or looks calm and free from worry.","ex":{"en":"I feel relaxed and peaceful","cn":"我感到放松而平和。"}}]},"examples":[{"en":"The aims of the organization are wholly peaceful.","cn":"这个组织的宗旨完全是追求和平。"},{"en":"It's so peaceful out here in the country.","cn":"这里的郊外一切都是那么宁静。"}]},"pervasive":{"media":{"uk":"media/uk/pervasive__gb_1.mp3","us":"media/us/pervasive__us_1.mp3"},"oxford":{"phon":"pəˈveɪsɪv","pos":"adjective","senses":[{"en":"existing in all parts of a place or thing; spreading gradually to affect all parts of a place or thing","cn":"遍布的；充斥各处的；弥漫的","ex":{"en":"a pervasive smell of damp","cn":"四处弥漫的潮湿味儿"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"遍布的；贯穿始终的；四处弥漫的","en":"Something, especially something bad, that is pervasive is present or felt throughout a place or thing.","ex":{"en":"...the pervasive influence of the army in national life","cn":"在国民生活中军队的影响无处不在"}}]},"examples":[{"en":"A sense of social change is pervasive in her novels.","cn":"她的小说里充斥着社会变化的意识。"},{"en":"a pervasive smell of damp","cn":"四处弥漫的潮湿味儿"}]},"persuade":{"media":{"uk":"media/uk/persuade__gb_1.mp3","us":"media/us/persuade__us_1.mp3"},"oxford":{"phon":"pəˈsweɪd","pos":"verb","senses":[{"en":"to make somebody do something by giving them good reasons for doing it","cn":"劝说；说服","ex":{"en":"Try to persuade him to come.","cn":"尽量劝他来。"}},{"en":"to make somebody believe that something is true","cn":"使信服；使相信","lab":"formal","ex":{"en":"It will be difficult to persuade them that there's no other choice.","cn":"很难让他们相信别无选择。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"劝说；说服","en":"If you persuade someone to do something, you cause them to do it by giving them good reasons for doing it.","ex":{"en":"My husband persuaded me to come","cn":"我丈夫说服我前来。"}},{"pos":"VERB 动词","cn":"使采取行动","en":"If something persuades someone to take a particular course of action, it causes them to take that course of action because it is a good reason for doing so.","ex":{"en":"The Conservative Party's victory in April's general election persuaded him to run for President again","cn":"4月保守党在大选中获胜促使他再次竞选总统。"}},{"pos":"VERB 动词","cn":"使信服；使相信","en":"If you persuade someone that something is true, you say things that eventually make them believe that it is true.","ex":{"en":"I've persuaded Mrs Tennant that it's time she retired","cn":"我已经说服坦南特夫人她该退休了。"}}]},"examples":[{"en":"I allowed myself to be persuaded into entering the competition.","cn":"我搁不住人家的劝说，就参加了比赛。"},{"en":"( formal ) I am still not fully persuaded of the plan's merits.","cn":"我还不能完全信服这个计划的优点。"}]},"peak":{"media":{"uk":"media/uk/peak__gb_1.mp3","us":"media/us/peak__us_1.mp3"},"oxford":{"phon":"piːk","pos":"noun","senses":[{"en":"the point when somebody/something is best, most successful, strongest, etc.","cn":"顶峰；高峰","g":"[usually singular]","ex":{"en":"Traffic reaches its peak between 8 and 9 in the morning.","cn":"上午 8、9 点钟之间是交通高峰期。"}},{"en":"the pointed top of a mountain; a mountain with a pointed top","cn":"山峰；峰峦","ex":{"en":"a mountain peak","cn":"山峰"}},{"en":"any narrow and pointed shape, edge, etc.","cn":"尖形；尖端；尖头","ex":{"en":"Whisk the egg whites into stiff peaks.","cn":"把蛋清搅成硬尖状。"}},{"en":"the stiff front part of a cap that sticks out above your eyes","cn":"帽舌；帽檐","lab":"British English"},{"en":"to reach the highest point or value","cn":"达到高峰；达到最高值","ex":{"en":"Oil production peaked in the early 1980s.","cn":"20 世纪 80 年代初期，石油产量达到了最高峰。"},"pos":"verb"},{"en":"used to describe the highest level of something, or a time when the greatest number of people are doing something or using something","cn":"最高度的；高峰时期的；巅峰状态的","ex":{"en":"It was a time of peak demand for the product.","cn":"那是对该产品需求最旺的时期。"},"pos":"adjective"},{"en":"relating to the moment when something is at its most popular or fashionable","cn":"与某事物最流行或最时尚的时刻有关","lab":"informal, often humorous，，","ex":{"en":"Everyone thought we'd reached peak beard (= the time when beards are most popular), but the trend shows no sign of slowing down.","cn":"每个人都认为我们已经达到了胡须的顶峰（即胡须最流行的时期），但这种趋势并没有放缓的迹象。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"顶点；顶峰","en":"The peak of a process or an activity is the point at which it is at its strongest, most successful, or most fully developed.","ex":{"en":"The party's membership has fallen from a peak of fifty-thousand after the Second World War","cn":"二战后该党党员人数已从5万人的峰值下降了。"}},{"pos":"VERB 动词","cn":"达到顶点；达到顶峰；达到最高值","en":"When something peaks, it reaches its highest value or its highest level.","ex":{"en":"Temperatures have peaked at over thirty degrees Celsius","cn":"温度最高达30摄氏度以上。"}},{"pos":"ADJ 形容词","cn":"（水平、价值）最高的，最大的","en":"The peak level or value of something is its highest level or value.","ex":{"en":"Calls cost 36p (cheap rate) and 48p (peak rate) per minute","cn":"电话每分钟36便士（优惠费率）和48便士（高峰费率）。"}},{"pos":"ADJ 形容词","cn":"高峰的；高峰期的","en":"Peak times are the times when there is most demand for something or most use of something.","ex":{"en":"It's always crowded at peak times","cn":"高峰期总是非常拥挤。"}},{"pos":"N-COUNT 可数名词","cn":"山峰；山顶；山巅","en":"A peak is a mountain or the top of a mountain.","ex":{"en":"...the snow-covered peaks.","cn":"积雪覆盖的山顶"}},{"pos":"N-COUNT 可数名词","cn":"帽舌；帽檐","en":"The peak of a cap is the part at the front that sticks out above your eyes.","ex":{"en":"The man touched the peak of his cap.","cn":"那名男子摸了摸他的帽舌。"}}]},"examples":[{"en":"Oil production peaked in the early 1980s. * 20","cn":"世纪 80 年代初期，石油产量达到了最高峰。"},{"en":"an athlete who peaks (= produces his or her best performance) at just the right time","cn":"一位恰在最佳时刻缔造出最佳成绩的运动员"}]},"pensions":{"lemma":"pension"},"performances":{"lemma":"performance","media":{"uk":"media/uk/performance__gb_1.mp3","us":"media/us/performance__us_1.mp3"}},"person":{"media":{"uk":"media/uk/person__gb_1.mp3","us":"media/us/person__us_1.mp3"},"oxford":{"phon":"ˈpɜːsn","pos":"noun","senses":[{"en":"a human as an individual","cn":"人；个人","ex":{"en":"What sort of person would do a thing like that?","cn":"什么人会干那样的事呢？"}},{"en":"a human, especially one who is not identified","cn":"人；某人","lab":"formal or disapproving","ex":{"en":"A certain person (= somebody that I do not wish to name) told me about it.","cn":"有人告诉了我这件事。"}},{"en":"a person working in the area of business mentioned; a person connected with the thing mentioned","cn":"从事…工作（或担任…职务）的人；人员","ex":{"en":"a salesperson","cn":"推销员"}},{"en":"any of the three classes of personal pronouns. The first person (I/we) refers to the person(s) speaking; the second person (you) refers to the person(s) spoken to; the third person (he/she/it/they) refers to the person(s) or thing(s) spoken about.","cn":"人称（第一人称 I／we 指说话人，第二人称 you 指听话的人，第三人称 he／she／it／they 指谈到的人或事物）","lab":"grammar"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"人；个人","en":"A person is a man, woman, or child.","ex":{"en":"At least one person died and several others were injured","cn":"至少一人死亡，还有几个人受伤。"}},{"pos":"N-PLURAL 复数名词","cn":"（person的复数形式，用于正式、法律、技术文体中）","en":"Persons is used as the plural of person in formal, legal, and technical writing.","ex":{"en":"...removal of the right of accused persons to remain silent","cn":"剥夺被告人保持沉默的权利"}},{"pos":"N-COUNT 可数名词","cn":"为人；人品","en":"If you talk about someone as a person, you are considering them from the point of view of their real nature.","ex":{"en":"I've a lot of time for him as a person now","cn":"现在我有充分的时间去了解他的人品。"}},{"pos":"N-COUNT 可数名词","cn":"喜欢（不喜欢）…的人","en":"If someone says, for example, 'I'm an outdoor person ' or 'I'm not a coffee person', they are saying whether or not they like that particular activity or thing.","ex":{"en":"I am not a country person at all. I prefer the cities.","cn":"我根本不喜欢乡村生活，我喜欢城市。"}},{"pos":"PHRASE 短语","cn":"亲自；本人","en":"If you do something in person, you do it yourself rather than letting someone else do it for you.","ex":{"en":"You must collect the mail in person and take along some form of identification","cn":"你必须携带本人身份证明亲自来取邮件。"}},{"pos":"PHRASE 短语","cn":"本人；直接；当面","en":"If you meet, hear, or see someone in person, you are in the same place as them, rather than, for example, speaking to them on the telephone, writing to them, or seeing them on television.","ex":{"en":"It was the first time she had seen him in person.","cn":"这是她第一次见到他本人。"}},{"pos":"N-COUNT 可数名词","cn":"身体","en":"Your person is your body.","ex":{"en":"The suspect had refused to give any details of his identity and had carried no documents on his person.","cn":"嫌疑犯拒绝说出他的具体身份，而且身上没有携带任何身份证明。"}},{"pos":"PHRASE 短语","cn":"名叫；人称","en":"You can use in the person of when mentioning the name of someone you have just referred to in a more general or indirect way.","ex":{"en":"We had a knowledgeable guide in the person of George Adams.","cn":"我们有一位见识广博的导游乔治·亚当斯。"}},{"pos":"N-COUNT 可数名词","cn":"（语法中的）人称","en":"In grammar, we use the term first person when referring to 'I' and 'we', second person when referring to 'you', and third person when referring to 'he', 'she', 'it', 'they', and all other noun groups. Person is also used like this when referring to the verb forms that go with these pronouns and noun groups."}]},"examples":[{"en":"He's just the person we need for the job.","cn":"他正是我们需要的适合这项工作的人。"},{"en":"I had a letter from the people who used to live next door.","cn":"我接到了过去的邻居写来的一封信。"}]},"persistence":{"media":{"uk":"media/uk/persistence__gb_1.mp3","us":"media/us/persistence__us_1.mp3"},"oxford":{"phon":"pəˈsɪstəns","pos":"noun","senses":[{"en":"the fact of continuing to try to do something despite difficulties, especially when other people are against you and think that you are being annoying or unreasonable","cn":"坚持；锲而不舍","ex":{"en":"His persistence was finally rewarded when the insurance company agreed to pay for the damage.","cn":"保险公司同意赔偿损失，他的坚持不懈终于得到了回报。"}},{"en":"the state of continuing to exist for a long period of time","cn":"持续存在；维持","ex":{"en":"the persistence of unemployment in the 1970s and 1980s","cn":"20 世纪 70 年代和 80 年代的持续失业状况"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"毅力；锲而不舍","en":"If you have persistence, you continue to do something even though it is difficult or other people are against it.","ex":{"en":"Skill comes only with practice, patience and persistence","cn":"只有不断练习，有耐心有毅力，才能学会一门技艺。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指不好事物的）持续存在，延续","en":"The persistence of something, especially something bad, is the fact of its continuing to exist for a long time.","ex":{"en":"...an expression of concern at the persistence of inflation and high interest rates.","cn":"对持续通货膨胀和高利率表现出的关注"}}]},"examples":[{"en":"His persistence was finally rewarded when the insurance company agreed to pay for the damage.","cn":"保险公司同意赔偿损失，他的坚持不懈终于得到了回报。"},{"en":"the persistence of unemployment in the 1970s and 1980s * 20","cn":"世纪 70 年代和 80 年代的持续失业状况"}]},"perish":{"media":{"uk":"media/uk/perish__gb_1.mp3","us":"media/us/perish__us_1.mp3"},"oxford":{"phon":"ˈperɪʃ","pos":"verb","senses":[{"en":"to die, especially in a sudden violent way","cn":"死亡；暴死","g":"[intransitive]","lab":"formal or literary","ex":{"en":"A family of four perished in the fire.","cn":"一家四口死于此次火灾之中。"}},{"en":"to be lost or destroyed","cn":"丧失；湮灭；毁灭","g":"[intransitive]","lab":"formal","ex":{"en":"Early buildings were made of wood and have perished.","cn":"早期建筑物为木质结构，已经消失殆尽。"}},{"en":"if a material such as rubber perishes or is perished, it becomes damaged, weaker or full of holes","cn":"（使橡胶等）老化，脆裂","g":"[intransitive, transitive]","lab":"British English"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（人或动物）惨死，猝死","en":"If people or animals perish, they die as a result of very harsh conditions or as the result of an accident.","ex":{"en":"Most of the butterflies perish in the first frosts of autumn.","cn":"大多数蝴蝶会在秋天的第一场霜冻来临时纷纷死去。"}},{"pos":"VERB 动词","cn":"湮灭；毁灭；丧失","en":"If something perishes, it comes to an end or is destroyed for ever.","ex":{"en":"Buddhism had to adapt to the new world or perish","cn":"佛教必须适应新时代，否则将会消亡。"}},{"pos":"VERB 动词","cn":"（物质或材料）老化，腐烂，脆裂","en":"If a substance or material perishes, it starts to fall to pieces and becomes useless.","ex":{"en":"Obviously the plaster's just perished and all fallen off","cn":"很明显灰泥已脆裂老化,全剥落下来了。"}},{"pos":"CONVENTION 惯用语","cn":"（表示认为建议不可能、荒谬）想都别想，死了心吧，没门儿","en":"If someone says perish the thought, they mean that they think that a suggestion or possibility is unpleasant or ridiculous.","ex":{"en":"Me a policeman! Perish the thought!","cn":"我当警察！想都别想了，不可能！"}}]},"examples":[{"en":"Early buildings were made of wood and have perished.","cn":"早期建筑物为木质结构，已经消失殆尽。"},{"en":"A family of four perished in the fire.","cn":"一家四口死于此次火灾之中。"}]},"perform":{"media":{"uk":"media/uk/perform__gb_1.mp3","us":"media/us/perform__us_1.mp3"},"oxford":{"phon":"pəˈfɔːm","pos":"verb","senses":[{"en":"to entertain an audience by playing a piece of music, acting in a play, etc.","cn":"演出；表演","g":"[transitive, intransitive]","ex":{"en":"to perform a song/dance/play","cn":"表演歌曲／舞蹈／戏剧"}},{"en":"to do something, such as a piece of work, task or duty","cn":"做；履行；执行","g":"[transitive]","lab":"medical","ex":{"en":"She performs an important role in our organization.","cn":"她在我们的组织中发挥着重要的作用。"}},{"en":"to work or function well or badly","cn":"工作，运转（好／不好）","g":"[intransitive]","ex":{"en":"The engine seems to be performing well.","cn":"发动机看起来运转良好。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"做，执行，履行（尤指复杂的任务或行动）","en":"When you perform a task or action, especially a complicated one, you do it.","ex":{"en":"We're looking for people of all ages who have performed outstanding acts of bravery, kindness or courage","cn":"我们正在寻找那些见义勇为、乐于助人、勇气可嘉的人，年龄不限。"}},{"pos":"VERB 动词","cn":"起…作用；有…功能","en":"If something performs a particular function, it has that function.","ex":{"en":"A complex engine has many separate components, each performing a different function.","cn":"一个复杂发动机有很多独立零部件，每个零部件具有不同作用。"}},{"pos":"VERB 动词","cn":"演出；表演；演奏","en":"If you perform a play, a piece of music, or a dance, you do it in front of an audience.","ex":{"en":"Gardiner has pursued relentlessly high standards in performing classical music","cn":"加德纳一直不懈地追求古典音乐演奏的高水准。"}},{"pos":"VERB 动词","cn":"（人）表现良好/很差；（事物）运转良好/糟糕","en":"If someone or something performs well, they work well or achieve a good result. If they perform badly, they work badly or achieve a poor result.","ex":{"en":"He had not performed well in his exams","cn":"他考试没考好。"}}]},"examples":[{"en":"She performs an important role in our organization.","cn":"她在我们的组织中发挥着重要的作用。"},{"en":"The play was first performed in 2007.","cn":"这部剧于 2007 年首次上演。"}]},"peter":{"media":{"uk":"media/uk/peter__gb_1.mp3","us":"media/us/peter__us_1.mp3"},"oxford":{"phon":"ˈpiːtə(r)","pos":"","senses":[{"en":"a first name for boys","cn":"彼得（男子名）"}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"借新债还旧债；拆东墙补西墙","en":"If you say that someone is robbing Peter to pay Paul, you mean that they are transferring money from one group of people or place to another, rather than providing extra money.","ex":{"en":"Sometimes he was moving money from one account to another, robbing Peter to pay Paul.","cn":"有的时候他把钱从一个账户转到另一个账户，拆东墙补西墙。"}}]},"examples":[{"en":"The campaign petered out for lack of support.","cn":"那场运动因缺乏支持者而最终烟消云散。"},{"en":"The road petered out into a dirt track.","cn":"大道延伸到一条泥路小径。"}]},"perfunctory":{"media":{"uk":"media/uk/perfunctory__gb_1.mp3","us":"media/us/perfunctory__us_1.mp3"},"oxford":{"phon":"pəˈfʌŋktəri","pos":"adjective","senses":[{"en":"done as a duty or habit, without real interest, attention or feeling","cn":"敷衍的；例行公事般的；潦草的","ex":{"en":"a perfunctory nod/smile","cn":"敷衍的点头／微笑"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"敷衍的；潦草的；马马虎虎的","en":"A perfunctory action is done quickly and carelessly, and shows a lack of interest in what you are doing.","ex":{"en":"She gave the list only a perfunctory glance","cn":"她马马虎虎地扫了一眼清单。"}}]},"examples":[{"en":"They only made a perfunctory effort.","cn":"他们只是敷衍了事。"},{"en":"to nod/smile perfunctorily","cn":"漫不经心地点头/微笑"}]},"pending":{"oxford":{"phon":"ˈpendɪŋ","pos":"preposition","senses":[{"en":"while waiting for something to happen; until something happens","cn":"在等待…时期；直到…为止","ex":{"en":"He was released on bail pending further inquiries.","cn":"他获得保释，等候进一步调查。"}},{"en":"waiting to be decided or settled","cn":"待定的；待决的","ex":{"en":"Nine cases are still pending.","cn":"尚有九宗案件待决。"},"pos":"adjective"},{"en":"going to happen soon","cn":"即将发生的","ex":{"en":"An election is pending in Italy.","cn":"意大利即将举行选举。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"待决的；待定的；待处理的","en":"If something such as a legal procedure is pending, it is waiting to be dealt with or settled.","ex":{"en":"The cause of death was listed as pending","cn":"死亡原因被列为待定。"}},{"pos":"PREP 介词","cn":"在等到…发生之际；直到…为止","en":"If something is done pending a future event, it is done until that event happens.","ex":{"en":"Mendoza is here pending his request for political asylum","cn":"门多萨在要求获得政治庇护之前一直呆在这里。"}},{"pos":"ADJ 形容词","cn":"即将发生的；迫近的","en":"Something that is pending is going to happen soon.","ex":{"en":"A growing number of customers have been inquiring about the pending price rises.","cn":"越来越多的顾客在询问即将出现的涨价问题。"}}]},"media":{"uk":"media/uk/pending__gb_1.mp3","us":"media/us/pending__us_1.mp3"},"examples":[{"en":"He was released on bail pending further inquiries.","cn":"他获得保释，等候进一步调查。"},{"en":"An election is pending in Italy.","cn":"意大利即将举行选举。"}]},"perched":{"media":{"uk":"media/uk/perched__gb_1.mp3","us":"media/us/perched__us_1.mp3"},"oxford":{"phon":"pɜːtʃt","pos":"adjective","senses":[{"en":"sitting or resting on something","cn":"栖息；停留","ex":{"en":"There was a bird perched on the roof.","cn":"有一只鸟落在屋顶上。"}},{"en":"placed in a high and/or dangerous position","cn":"被置于高处（或危险处）","ex":{"en":"a hotel perched high on the cliffs","cn":"高高矗立在悬崖上的旅馆"}}]},"examples":[{"en":"a hotel perched high on the cliffs","cn":"高高矗立在悬崖上的旅馆"},{"en":"There was a bird perched on the roof.","cn":"有一只鸟落在屋顶上。"}],"base":"perch"},"peasant":{"media":{"uk":"media/uk/peasant__gb_1.mp3","us":"media/us/peasant__us_1.mp3"},"oxford":{"phon":"ˈpeznt","pos":"noun","senses":[{"en":"(especially in the past, or in poorer countries) a farmer who owns or rents a small piece of land","cn":"（尤指旧时或贫穷国家的）农民，小农，佃农","ex":{"en":"peasant farmers","cn":"自耕农"}},{"en":"a person who is rude, behaves badly or has little education","cn":"老粗；没教养的人","lab":"informal, disapproving，，"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"农民","en":"A peasant is a poor person of low social status who works on the land; used of people who live in countries where farming is still a common way of life.","ex":{"en":"...the peasants in the Peruvian highlands","cn":"秘鲁高地的农民"}}]},"examples":[{"en":"peasant farmers","cn":"自耕农"},{"en":"Most villagers are peasant farmers.","cn":"大多数村民是农民。"}]},"pessimistic":{"oxford":{"phon":"ˌpesɪˈmɪstɪk","pos":"adjective","senses":[{"en":"expecting bad things to happen or something not to be successful; showing this","cn":"悲观的；悲观主义的","ex":{"en":"They appeared surprisingly pessimistic about their chances of winning.","cn":"他们对胜利的可能性显得出奇地悲观。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"悲观的","en":"Someone who is pessimistic thinks that bad things are going to happen.","ex":{"en":"Not everyone is so pessimistic about the future","cn":"不是每个人都对未来如此悲观。"}}]},"media":{"uk":"media/uk/pessimistic__gb_1.mp3","us":"media/us/pessimistic__us_1.mp3"},"examples":[{"en":"They appeared surprisingly pessimistic about their chances of winning.","cn":"他们对胜利的可能性显得出奇地悲观。"},{"en":"I think you're being far too pessimistic.","cn":"我觉得你过于悲观了。"}]},"peace-loving":{"oxford":{"phon":"ˈpiːs lʌvɪŋ","pos":"adjective","senses":[{"en":"preferring to live in peace and to avoid arguments and fighting","cn":"爱好和平的","ex":{"en":"peace-loving citizens","cn":"爱好和平的公民"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"热爱和平的；不爱惹事的","en":"If you describe someone as peace-loving, you mean that they try to avoid quarrelling or fighting with other people.","ex":{"en":"By and large, these people are peace-loving, law-abiding citizens.","cn":"大体上，这些人都是热爱和平、遵纪守法的公民。"}}]},"media":{"uk":"media/uk/peace_loving_1_gb_1.mp3","us":"media/us/peace_loving_1_us_1.mp3"},"examples":[{"en":"a peace-loving nation","cn":"热爱和平的国家"}]},"peninsula":{"oxford":{"phon":"pəˈnɪnsjələ","pos":"noun","senses":[{"en":"an area of land that is almost surrounded by water but is joined to a larger piece of land","cn":"半岛","ex":{"en":"the Iberian peninsula (= containing Spain and Portugal)","cn":"伊比利亚半岛"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"半岛","en":"A peninsula is a long narrow piece of land which sticks out from a larger piece of land and is almost completely surrounded by water.","ex":{"en":"...the political situation in the Korean peninsula","cn":"朝鲜半岛的政治局势"}}]},"media":{"uk":"media/uk/peninsula__gb_1.mp3","us":"media/us/peninsula__us_1.mp3"},"examples":[{"en":"the Iberian peninsula (= Spain and Portugal)","cn":"伊比利亚半岛"},{"en":"the Korean peninsula","cn":"朝鲜半岛"}]},"persistent":{"media":{"uk":"media/uk/persistent__gb_1.mp3","us":"media/us/persistent__us_1.mp3"},"oxford":{"phon":"pəˈsɪstənt","pos":"adjective","senses":[{"en":"determined to do something despite difficulties, especially when other people are against you and think that you are being annoying or unreasonable","cn":"坚持的；顽固的；执意的","ex":{"en":"How do you deal with persistent salesmen who won't take no for an answer?","cn":"你怎么对付那些志在必得、一直纠缠下去的推销员？"}},{"en":"continuing for a long period of time, or repeated frequently, especially in a way that is annoying and cannot be stopped","cn":"连绵的；持续的；反复出现的","ex":{"en":"Persistent heavy rain held up work on the bridge for more than a week.","cn":"持续的大雨耽搁了桥梁作业超过一周。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（尤指不好或不受欢迎的状态或情况）持续存在的，继续发生的","en":"Something that is persistent continues to exist or happen for a long time; used especially about bad or undesirable states or situations.","ex":{"en":"Her position as national leader has been weakened by persistent fears of another coup attempt","cn":"由于人们一直担心会再次发生政变,她的国家领导人地位被削弱了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"执著的；不屈不挠的；锲而不舍的","en":"Someone who is persistent continues trying to do something, even though it is difficult or other people are against it.","ex":{"en":"...a persistent critic of the government's transport policies","cn":"对政府交通政策一直持批评态度的人"}}]},"examples":[{"en":"How do you deal with persistent salesmen who won't take no for an answer?","cn":"你怎么对付那些不轻言放弃、一直纠缠下去的推销员？"},{"en":"They have persistently denied claims of illegal dealing.","cn":"他们一再否认进行非法交易的说法。"}]},"permission":{"oxford":{"phon":"pəˈmɪʃn","pos":"noun","senses":[{"en":"the act of allowing somebody to do something, especially when this is done by somebody in a position of authority","cn":"准许；许可；批准","g":"[uncountable]","lab":"formal","ex":{"en":"You must ask permission for all major expenditure.","cn":"一切重大开支均须报请批准。"}},{"en":"an official written statement allowing somebody to do something","cn":"许可证；书面许可","g":"[countable, usually plural]","ex":{"en":"The publisher is responsible for obtaining the necessary permissions to reproduce illustrations.","cn":"出版者负责取得准许复制插图的必要许可文件。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"准许；许可；批准","en":"If someone who has authority over you gives you permission to do something, they say that they will allow you to do it.","ex":{"en":"He asked permission to leave the room","cn":"他请求准许离开房间。"}},{"pos":"N-COUNT 可数名词","cn":"许可证；书面许可","en":"A permission is a formal, written statement from an official group or place allowing you to do something.","ex":{"en":"...oil exploration permissions.","cn":"石油勘探许可证"}}]},"media":{"uk":"media/uk/permission__gb_1.mp3","us":"media/us/permission__us_1.mp3"},"examples":[{"en":"The publisher is responsible for obtaining the necessary permissions to reproduce illustrations.","cn":"出版者负责申办准予使用他人插图的必要许可文件。"},{"en":"No official permission has been given for the event to take place.","cn":"这项活动未得到正式批准，不能举行。"}]},"peculiar":{"media":{"uk":"media/uk/peculiar__gb_1.mp3","us":"media/us/peculiar__us_1.mp3"},"oxford":{"phon":"pɪˈkjuːliə(r)","pos":"adjective","senses":[{"en":"strange or unusual, especially in a way that is unpleasant or makes you worried","cn":"怪异的；奇怪的；不寻常的","ex":{"en":"a peculiar smell/taste","cn":"奇怪的气味／味道"}},{"en":"belonging or relating to one particular place, situation, person, etc., and not to others","cn":"（某地、某种情况、某人等）特有的，特殊的","ex":{"en":"a humour that is peculiar to American sitcoms","cn":"美国情景喜剧特有的幽默"}},{"en":"slightly ill","cn":"不适；不舒服","lab":"British English, informal，，","ex":{"en":"I don’t think I’ll eat anything—I’m feeling a bit peculiar.","cn":"我想我不会吃任何东西——我感觉有点奇怪。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"奇怪的；古怪的；不寻常的","en":"If you describe someone or something as peculiar, you think that they are strange or unusual, sometimes in an unpleasant way.","ex":{"en":"Mr Kennet has a rather peculiar sense of humour","cn":"肯尼特先生有种很奇怪的幽默感。"}},{"pos":"ADJ 形容词","cn":"特有的；特别的；独特的","en":"If something is peculiar to a particular thing, person, or situation, it belongs or relates only to that thing, person, or situation.","ex":{"en":"The problem is by no means peculiar to America.","cn":"这个问题绝对不只限于美国。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有点不舒服的；稍感眩晕的","en":"If you say that you feel peculiar, you mean that you feel slightly ill or unsteady.","ex":{"en":"All this has made me feel quite peculiar.","cn":"这一切令我觉得有点儿不舒服。"}}]},"examples":[{"en":"I had a peculiar feeling we'd met before.","cn":"我有一种奇怪的感觉，觉得我们以前见过面。"},{"en":"For some peculiar reason, she refused to come inside.","cn":"出于某种奇怪的原因，她拒绝到里面来。"}]},"permeates":{"lemma":"permeate","media":{"uk":"media/uk/permeate__gb_1.mp3","us":"media/us/permeate__us_1.mp3"}},"pertinent":{"oxford":{"phon":"ˈpɜːtɪnənt","pos":"adjective","senses":[{"en":"appropriate to a particular situation","cn":"有关的；恰当的；相宜的","ex":{"en":"a pertinent question/fact","cn":"有关的问题／事实"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有关的；相关的","en":"Something that is pertinent is relevant to a particular subject.","ex":{"en":"She had asked some pertinent questions","cn":"她问了一些相关的问题。"}}]},"media":{"uk":"media/uk/pertinent__gb_1.mp3","us":"media/us/pertinent__us_1.mp3"},"examples":[{"en":"Please keep your comments pertinent to the topic under discussion.","cn":"请勿发表与讨论主题无关的言论。"},{"en":"a pertinent question/fact","cn":"有关的问题/事实"}]},"persists":{"lemma":"persist"},"peace":{"media":{"uk":"media/uk/peace__gb_1.mp3","us":"media/us/peace__us_1.mp3"},"oxford":{"phon":"piːs","pos":"noun","senses":[{"en":"a situation or a period of time in which there is no war or violence in a country or an area","cn":"和平；太平","g":"[uncountable, singular]","ex":{"en":"world peace","cn":"世界和平"}},{"en":"the state of being calm or quiet","cn":"平静；安静；宁静","g":"[uncountable]","lab":"law","ex":{"en":"She lay back and enjoyed the peace of the summer evening.","cn":"她轻松地躺着享受夏日傍晚的宁静。"}},{"en":"the state of living in friendship with somebody without arguing","cn":"和睦；融洽；和谐","g":"[uncountable]","ex":{"en":"They simply can't seem to live in peace with each other.","cn":"他们好像就是不能和睦相处。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（交战或冲突后的） 和平","en":"If countries or groups involved in a war or violent conflict are discussing peace, they are talking to each other in order to try to end the conflict.","ex":{"en":"Peace talks involving other rebel leaders and government representatives broke up without agreement last week, but are due to resume shortly","cn":"上个星期，其他叛军领导人和政府代表之间的和谈没能达成协议，宣告破裂，但是和谈不久会重开。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"和平；太平","en":"If there is peace in a country or in the world, there are no wars or violent conflicts going on.","ex":{"en":"The President spoke of a shared commitment to world peace and economic development.","cn":"总统提到了共同致力于世界和平和经济发展。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"和平运动；裁军运动（尤指核裁军运动）","en":"If you disapprove of weapons, especially nuclear weapons, you can use peace to refer to campaigns and other activities intended to reduce their numbers or stop their use.","ex":{"en":"...two peace campaigners accused of causing damage to an F1-11 nuclear bomber","cn":"被控破坏一架F1-11核轰炸机的两名和平运动者"}},{"pos":"N-UNCOUNT 不可数名词","cn":"安静；宁静；安宁","en":"If you have peace, you are not being disturbed, and you are in calm, quiet surroundings.","ex":{"en":"All I want is to have some peace and quiet and spend a couple of nice days with my grandchildren","cn":"我就想清静一下，和孙子孙女们一起好好呆几天。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（心情）平静，平和","en":"If you have a feeling of peace, you feel contented and calm and not at all worried. You can also say that you are at peace.","ex":{"en":"I had a wonderful feeling of peace and serenity when I saw my husband","cn":"看到我丈夫时，我有一种异常平静安详的奇妙感觉。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"和睦；和谐","en":"If there is peace among a group of people, they live or work together in a friendly way and do not quarrel. You can also say that people live or work in peace with each other.","ex":{"en":"...a period of relative peace in the country's industrial relations","cn":"该国劳资关系相对和睦的一段时期"}},{"pos":"N-IN-NAMES 名称名词","cn":"和约","en":"The Peace of a particular place is a treaty or an agreement that was signed there, bringing an end to a war.","ex":{"en":"The Peace of Ryswick was signed in September 1697.","cn":"《里斯维克和约》签订于1697年9月。"}},{"pos":"PHRASE 短语","cn":"保持缄默","en":"If you hold or keep your peace, you do not speak, even though there is something you want or ought to say.","ex":{"en":"...people who knew about this evil man but held their peace","cn":"了解这个恶棍却默不作声的人们"}},{"pos":"PHRASE 短语","cn":"维持治安；维护和平","en":"If someone in authority, such as the army or the police, keeps the peace, they make sure that people behave and do not fight or quarrel with each other.","ex":{"en":"...the first UN contingent assigned to help keep the peace in Cambodia","cn":"派往柬埔寨协助维持治安的第一批联合国分遣队"}},{"pos":"PHRASE 短语","cn":"遵纪守法；不滋生事端","en":"If the law requires you to keep the peace, you must behave well and not cause any trouble in public.","ex":{"en":"The demonstrators were bound over to keep the peace.","cn":"示威者一定要遵纪守法。"}},{"pos":"PHR-RECIP 相互短语","cn":"（与…）言归于好；（与…）讲和","en":"If you make peace with someone or make your peace with them, you put an end to your quarrel with them, often by apologizing.","ex":{"en":"The President ought to seize this opportunity to make his peace with political parties and negotiate a speedy return to democracy","cn":"总统应该抓住这个机会与各政党握手言好，协商尽快恢复民主。"}},{"pos":"PHRASE 短语","cn":"安心；心境的安宁","en":"If something gives you peace of mind, it stops you from worrying about a particular problem or difficulty.","ex":{"en":"The main appeal these bonds hold for individual investors is the safety and peace of mind they offer","cn":"这些债券对个人投资者的主要吸引力在于其安全性，令人放心。"}},{"pos":"PHRASE 短语","cn":"安息（有时刻于墓碑上）","en":"If you express the wish that a dead person may rest in peace, you are showing respect and sympathy for him or her. 'Rest in peace' is also sometimes written on gravestones."},{"pos":"PHRASE 短语","cn":"心平气和；与世无争","en":"If you are at peace with yourself or at peace with the world, you feel calm and contented, and you have no emotional conflicts within yourself or with other people.","ex":{"en":"Once I knew I was forgiven I could be at peace with myself at last","cn":"一旦我知道自己得到了宽恕，便可以心平气和了。"}},{"pos":"","cn":"","en":"to disturb the peace→see: ;"}]},"examples":[{"en":"After years of war, the people long for a lasting peace.","cn":"历经多年战乱之后，人民渴望永久和平。"},{"en":"A UN force has been sent to keep the peace (= to prevent people from fighting).","cn":"一支联合国部队已受遣前去维护和平。"}]},"personal":{"media":{"uk":"media/uk/personal__gb_1.mp3","us":"media/us/personal__us_1.mp3"},"oxford":{"phon":"ˈpɜːsənl","pos":"adjective","senses":[{"en":"your own; not belonging to or connected with anyone else","cn":"个人的；私人的","g":"[usually before noun]","sc":"your own","ex":{"en":"The novel is written from personal experience.","cn":"这部小说是根据个人亲身经历写成的。"}},{"en":"between individual people who know each other","cn":"人际的；个人之间的","g":"[only before noun]","sc":"between individuals","ex":{"en":"Having good personal relationships is the most important thing for me.","cn":"拥有良好的人际关系对我最为重要。"}},{"en":"connected with a person’s private life, rather than their job or official position","cn":"私人的；私事的；非公务的","sc":"private","ex":{"en":"I try not to let work interfere with my personal life.","cn":"我尽量不让工作干扰我的私生活。"}},{"en":"done by a particular person rather than by somebody who is acting for them","cn":"亲自做的","g":"[only before noun]","sc":"done by person","ex":{"en":"The President made a personal appearance at the event.","cn":"总统亲临现场。"}},{"en":"made or done for a particular person rather than for a large group of people or people in general","cn":"为某人做的；个别的","g":"[only before noun]","sc":"done for person","ex":{"en":"We offer a personal service to all our customers.","cn":"我们为所有顾客提供个人服务。"}},{"en":"referring to a particular person’s character, appearance, opinions, etc. in a way that is offensive","cn":"针对个人的；人身攻击的","sc":"offensive","ex":{"en":"Try to avoid making personal remarks.","cn":"要尽量避免针对个人的言论。"}},{"en":"connected with a person’s body","cn":"人身的；身体的","g":"[only before noun]","sc":"connected with body","ex":{"en":"personal cleanliness/hygiene","cn":"个人卫生"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"个人的；私人的","en":"A personal opinion, quality, or thing belongs or relates to one particular person rather than to other people.","ex":{"en":"He learned this lesson the hard way — from his own personal experience","cn":"吃一堑长一智，他这个教训来之不易——是从他自己的亲身经历中得来的。"}},{"pos":"ADJ 形容词","cn":"亲自的；本人的","en":"If you give something your personal care or attention, you deal with it yourself rather than letting someone else deal with it.","ex":{"en":"...a business that requires a great deal of personal contact.","cn":"经常需要本人亲自联系、打理的生意"}},{"pos":"ADJ 形容词","cn":"（感情、关系、健康方面）个人的，人际的，自己的","en":"Personal matters relate to your feelings, relationships, and health.","ex":{"en":"...teaching young people about marriage and personal relationships","cn":"教导年轻人有关婚姻和人际关系方面的事情"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"针对个人的；人身攻击的","en":"Personal comments refer to someone's appearance or character in an offensive way.","ex":{"en":"Newspapers resorted to personal abuse","cn":"报纸采取了人身攻击的手段。"}},{"pos":"ADJ 形容词","cn":"外貌的；身体的","en":"Personal care involves looking after your body and appearance.","ex":{"en":"...men who take as much trouble over personal hygiene as women.","cn":"像女人一样不嫌麻烦打理个人卫生的男人"}},{"pos":"ADJ 形容词","cn":"私人的；非业务关系的","en":"A personal relationship is one that is not connected with your job or public life.","ex":{"en":"He was a personal friend whom I've known for many many years","cn":"他是一位我认识多年的私人朋友。"}}]},"examples":[{"en":"He was popular as much for his personal qualities as for his management skills.","cn":"他的人品和他的管理技巧同样受到人们的喜爱。"},{"en":"Coogan has run a personal best of just under four minutes.","cn":"库根跑出了刚好低于四分钟的个人最好成绩。"}]},"personnel":{"oxford":{"phon":"ˌpɜːsəˈnel","pos":"noun","senses":[{"en":"the people who work for an organization or one of the armed forces","cn":"（组织或军队中的）全体人员，职员","g":"[plural]","ex":{"en":"There is a severe shortage of skilled personnel.","cn":"熟练员工严重短缺。"}},{"en":"the department in a company that deals with employing and training people","cn":"人事部门","g":"[uncountable + singular or plural verb]","ex":{"en":"the personnel department/manager","cn":"人事部门／经理"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"（组织中的）人员，职员","en":"The personnel of an organization are the people who work for it.","ex":{"en":"Five other US military personnel were killed in various incidents","cn":"另有5名美军士兵死于各种意外。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"人事部门","en":"Personnel is the department in a large company or organization that deals with employees, keeps their records, and helps with any problems they might have.","ex":{"en":"Her first job was in personnel.","cn":"她的第一份工作是人事方面的。"}}]},"media":{"uk":"media/uk/personnel__gb_1.mp3","us":"media/us/personnel__us_1.mp3"},"examples":[{"en":"Personnel is/are currently reviewing pay scales.","cn":"人事部现在正审核工资级别。"},{"en":"She works in personnel.","cn":"她在人事部工作。"}]},"performer":{"media":{"uk":"media/uk/performer__gb_1.mp3","us":"media/us/performer__us_1.mp3"},"oxford":{"phon":"pəˈfɔːmə(r)","pos":"noun","senses":[{"en":"a person who performs for an audience in a show, concert, etc.","cn":"表演者；演出者；演员","ex":{"en":"a brilliant/polished/seasoned performer","cn":"卓越的／优雅的／娴熟的表演者"}},{"en":"a person or thing that behaves or works in the way mentioned","cn":"表现得…者；表现了…者","ex":{"en":"He was a poor performer at school and left with no qualifications.","cn":"他在校学习成绩不好，没有毕业就离开学校。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"表演者；演出者；演员","en":"A performer is a person who acts, sings, or does other entertainment in front of audiences.","ex":{"en":"A performer in evening dress plays classical selections on the violin.","cn":"一名身穿晚礼服的表演者用小提琴演奏了几段古典音乐。"}},{"pos":"N-COUNT 可数名词","cn":"表现…的人（或事物）；性能…的事物","en":"You can use performer when describing someone or something in a way that indicates how well they do a particular thing.","ex":{"en":"Until 1987, Canada's industry had been the star performer","cn":"直到1987年，加拿大的工业一直成就斐然。"}}]},"examples":[{"en":"He was a poor performer at school and left with no qualifications.","cn":"他在校学习成绩不好，没有毕业就离开学校。"},{"en":"VW is the star performer of the motor industry this year.","cn":"大众汽车在本年度汽车行业中出类拔萃。"}]},"persuasion":{"media":{"uk":"media/uk/persuasion__gb_1.mp3","us":"media/us/persuasion__us_1.mp3"},"oxford":{"phon":"pəˈsweɪʒn","pos":"noun","senses":[{"en":"the act of persuading somebody to do something or to believe something","cn":"说服；劝说","g":"[uncountable]","ex":{"en":"It didn't take much persuasion to get her to tell us where he was.","cn":"我们没费什么口舌就让她说出了他的下落。"}},{"en":"a particular set of beliefs, especially about religion or politics","cn":"（宗教或政治）信仰","g":"[countable, uncountable]","ex":{"en":"Politicians of all persuasions condemned the attacks.","cn":"各种派系的政治家都谴责了这次袭击。"}},{"en":"a romantic novel (1818) by Jane Austen, the last book she wrote. The main character is Anne Elliot, who refuses Frederick Wentworth's offer of marriage but regrets doing so and accepts when he asks her again several years later.","cn":"说服力：简·奥斯丁的浪漫小说（1818年），是她最后写的书。主角是安妮·艾略特（Anne Elliot），她拒绝弗雷德里克·温特沃斯（Frederick Wentworth）的求婚，但对此感到后悔，并在几年后再次问她时接受了。","pos":""}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"说服；劝说","en":"Persuasion is the act of persuading someone to do something or to believe that something is true.","ex":{"en":"Only after much persuasion from Ellis had she agreed to hold a show at all","cn":"埃利斯劝了她半天后她才同意办一场展览。"}},{"pos":"N-COUNT 可数名词","cn":"信仰；信念","en":"If you are of a particular persuasion, you have a particular belief or set of beliefs.","ex":{"en":"It is a national movement and has within it people of all political persuasions","cn":"这是一场全国性运动，参加者的政治信仰各不相同。"}}]},"examples":[{"en":"It didn't take much persuasion to get her to tell us where he was.","cn":"我们没费什么口舌就让她说出了他的下落。"},{"en":"After a little gentle persuasion, he agreed to come.","cn":"耐心劝说一下，他就同意来了。"}]},"permit":{"media":{"uk":"media/uk/permit__gb_1.mp3","us":"media/us/permit__us_1.mp3"},"oxford":{"phon":"pəˈmɪt","pos":"verb","senses":[{"en":"to allow somebody to do something or to allow something to happen","cn":"允许；准许","g":"[transitive, often passive]","lab":"formal","ex":{"en":"Mobile phones are not permitted in the examination room.","cn":"手机不允许带入考场。"}},{"en":"to make something possible","cn":"允许；使有可能","g":"[intransitive, transitive]","ex":{"en":"We hope to visit the cathedral, if time permits.","cn":"如果时间允许，我们希望能参观一下主教座堂。"}},{"en":"an official document that gives somebody the right to do something, especially for a limited period of time","cn":"许可证，特许证（尤指限期的）","ex":{"en":"a parking/building permit","cn":"停车／建筑许可证"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"允许；准许","en":"If someone permits something, they allow it to happen. If they permit you to do something, they allow you to do it.","ex":{"en":"He can let the court's decision stand and permit the execution","cn":"他有权维持法庭判决，批准死刑生效。"}},{"pos":"N-COUNT 可数名词","cn":"许可证；特许证","en":"A permit is an official document which says that you may do something. For example you usually need a permit to work in a foreign country.","ex":{"en":"The majority of foreign nationals working here have work permits","cn":"大多数在这里工作的外国人都有工作许可证。"}},{"pos":"VERB 动词","cn":"允许；使有可能","en":"If a situation permits something, it makes it possible for that thing to exist, happen, or be done or it provides the opportunity for it.","ex":{"en":"He sets about creating an environment that just doesn't permit experiment, it encourages it","cn":"他着手营造一种不仅可以进行试验而且鼓励进行试验的环境。"}},{"pos":"VERB 动词","cn":"破例做；放纵","en":"If you permit yourself something, you allow yourself to do something that you do not normally do or that you think you probably should not do.","ex":{"en":"Captain Bowen permitted himself one cigar a day","cn":"鲍恩上尉破例允许自己每天抽一支雪茄。"}},{"pos":"PHRASE 短语","cn":"（用于提出建议）请允许我","en":"You can use permit me when you are about to say something or to make a suggestion.","ex":{"en":"Permit me to give you some advice","cn":"请允许我给你提点建议。"}}]},"examples":[{"en":"We hope to visit the cathedral, if time permits.","cn":"如果时间允许，我们希望能参观一下主教座堂。"},{"en":"The password permits access to all files on the hard disk.","cn":"这个密码可调出硬盘上的所有文档。"}]},"pencil":{"oxford":{"phon":"ˈpensl","pos":"noun","senses":[{"en":"a narrow piece of wood, or a metal or plastic case, containing a black or coloured substance, used for drawing or writing","cn":"铅笔","ex":{"en":"I'll get a pencil and paper.","cn":"我去拿铅笔和纸。"}},{"en":"to write, draw or mark something with a pencil","cn":"用铅笔写（或画、做记号）","ex":{"en":"a pencilled portrait","cn":"铅笔画像"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"铅笔","en":"A pencil is an object that you write or draw with. It consists of a thin piece of wood with a rod of a black or coloured substance through the middle. If you write or draw something in pencil, you do it using a pencil.","ex":{"en":"I found a pencil and some blank paper in her desk","cn":"我在她的桌子里找到一支铅笔和几张白纸。"}},{"pos":"VERB 动词","cn":"用铅笔写","en":"If you pencil a letter or a note, you write it using a pencil.","ex":{"en":"He pencilled a note to Joseph Daniels.","cn":"他用铅笔给约瑟夫·丹尼尔斯写了个便条。"}},{"pos":"","cn":"","en":"相关词组：pencil in"}]},"media":{"img":["media/ldoce/img/pencil.jpg","media/pic/stationery_supplies_comp.jpg"],"uk":"media/uk/pencil__gb_1.mp3","us":"media/us/pencil__us_1.mp3"},"examples":[{"en":"A previous owner had pencilled ‘First Edition’ inside the book's cover.","cn":"这本书过去的主人在书的封面内页上用铅笔写了“第一版”。"},{"en":"Shall I pencil you in for Friday? (= for a meeting)","cn":"我要不要先记下你星期五开会？"}]},"periodic":{"media":{"uk":"media/uk/periodic__gb_1.mp3","us":"media/us/periodic__us_1.mp3"},"oxford":{"phon":"ˌpɪəriˈɒdɪk","pos":"adjective","senses":[{"en":"happening fairly often and regularly","cn":"间发性的；定期的；周期的","ex":{"en":"Periodic checks are carried out on the equipment.","cn":"设备定期进行检查。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"间发性的；定期的；周期的","en":"Periodic events or situations happen occasionally, at fairly regular intervals.","ex":{"en":"Periodic checks are taken to ensure that high standards are maintained.","cn":"定期检查以确保维持高水准。"}}]},"examples":[{"en":"Periodic checks are carried out on the equipment.","cn":"设备定期进行检查。"},{"en":"Mailing lists are updated periodically.","cn":"邮寄名单定期更新。"}]},"perpetual":{"oxford":{"phon":"pəˈpetʃuəl","pos":"adjective","senses":[{"en":"continuing for a long period of time without stopping or being interrupted","cn":"不间断的；持续的；长久的","g":"[usually before noun]","lab":"literary","ex":{"en":"the perpetual noise of traffic","cn":"持续不断的交通噪声"}},{"en":"frequently repeated, in a way that is annoying","cn":"一再反复的；无尽无休的；没完没了的","g":"[usually before noun]","ex":{"en":"How can I work with these perpetual interruptions?","cn":"打扰不断，让我怎么工作？"}},{"en":"lasting for the whole of somebody’s life","cn":"终身的；永久的","g":"[only before noun]","lab":"humorous","ex":{"en":"He was elected perpetual president.","cn":"他被选为终身会长。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不间断的；不变的；持续的；长久的","en":"A perpetual feeling, state, or quality is one that never ends or changes.","ex":{"en":"...the creation of a perpetual union.","cn":"永久联盟的创立"}},{"pos":"ADJ 形容词","cn":"连续不断的；无尽无休的；没完没了的","en":"A perpetual act, situation, or state is one that happens again and again and so seems never to end.","ex":{"en":"I thought her perpetual complaints were going to prove too much for me.","cn":"我想我再也受不了她无休无止的抱怨了。 per|pet|ual|ly"}}]},"media":{"uk":"media/uk/perpetual__gb_1.mp3","us":"media/us/perpetual__us_1.mp3"},"examples":[{"en":"We lived for years in a perpetual state of fear.","cn":"多年来我们一直生活在恐惧中。"},{"en":"How can I work with these perpetual interruptions?","cn":"打扰不断，让我怎么工作？"}]},"penny":{"media":{"uk":"media/uk/penny__gb_1.mp3","us":"media/us/penny__us_1.mp3"},"oxford":{"phon":"ˈpeni","pos":"noun","senses":[{"en":"a small British coin and unit of money. There are 100 pence in one pound (£1).","cn":"便士（英国的小硬币和货币单位，1 英镑为 100 便士）","ex":{"en":"He had a few pennies in his pocket.","cn":"他口袋里有几个便士的硬币。"}},{"en":"a British coin in use until 1971. There were twelve pennies in one shilling and twenty shillings in a pound.","cn":"便士（英国 1971 年前使用的硬币，十二便士为一先令，二十先令为一镑）"},{"en":"a cent","cn":"分（辅币单位）","lab":"North American English","ex":{"en":"The fee ranges from a few pennies to $30 or more.","cn":"费用低者几美分，高者达 30 美元或更多。"}},{"en":"a first name for girls, short for Penelope","cn":"佩妮（女子名，Penelope 缩写）","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（英国）便士（指币值或硬币）","en":"In Britain, a penny is one hundredth of a pound, or a coin worth this amount of money.","ex":{"en":"Cider also goes up by a penny a pint while sparkling wine will cost another eight pence a bottle.","cn":"苹果酒每品脱也涨了1便士，而汽酒则每瓶涨了8便士。"}},{"pos":"N-COUNT 可数名词","cn":"便士（英国1971年前使用的硬币，价值1/12先令）","en":"A penny is a British coin used before 1971 that was worth one twelfth of a shilling."},{"pos":"N-COUNT 可数名词","cn":"分（指币值或硬币）","en":"A penny is one cent, or a coin worth one cent.","ex":{"en":"Unleaded gasoline rose more than a penny a gallon.","cn":"无铅汽油每加仑涨了1分多。"}},{"pos":"N-SING 单数名词","cn":"一个子儿；分文","en":"If you say, for example, that you do not have a penny, or that something does not cost a penny, you are emphasizing that you do not have any money at all, or that something did not cost you any money at all.","ex":{"en":"From the day you arrive at my house, you need not spend a single penny","cn":"从你到我家那天起，你就一个子儿也不用花。"}},{"pos":"PHRASE 短语","cn":"恍然大悟；茅塞顿开；突然回过神来","en":"If you say the penny dropped, you mean that someone suddenly understood or realized something.","ex":{"en":"'Did he know who you are?' — 'I think so. I think the penny dropped.'","cn":"“他知道你是谁吗？”——“我想是的。我觉得他是突然想到的。”"}},{"pos":"PHRASE 短语","cn":"上厕所；方便","en":"If someone says that they are going to spend a penny, they mean that they are going to go to the toilet."},{"pos":"PHRASE 短语","cn":"不值钱；不稀奇","en":"Things that are said to be two a penny or ten a penny are not valuable or interesting because they are very common and easy to find.","ex":{"en":"Leggy blondes are two a penny in Hollywood.","cn":"在好莱坞，长腿金发美女遍地都是。"}},{"pos":"PHRASE 短语","cn":"物有所值；一分钱不白花","en":"If you say that something or someone is worth every penny, you mean that they are worth all the money that is spent on them.","ex":{"en":"The operation cost £100,000 and it was worth every penny","cn":"那次手术花了10万英镑，但是花得非常值。"}}]},"examples":[{"en":"We collected £700 and every penny went to charity.","cn":"我们募集了 700 英镑，悉数捐给了慈善机构。"},{"en":"They cost 20p each.","cn":"这些东西每个要 20 便士。"}]},"permeate":{"media":{"uk":"media/uk/permeate__gb_1.mp3","us":"media/us/permeate__us_1.mp3"},"oxford":{"phon":"ˈpɜːmieɪt","pos":"verb","senses":[{"en":"to spread to every part of an object or a place","cn":"渗透；弥漫；扩散","g":"[transitive, intransitive]","ex":{"en":"The smell of leather permeated the room.","cn":"屋子里弥漫着皮革的气味。"}},{"en":"to affect every part of something","cn":"感染；传播；扩散","g":"[transitive, intransitive]","ex":{"en":"a belief that permeates all levels of society","cn":"深入社会各阶层的看法"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（思想、感情、态度）感染，传播，扩散，影响","en":"If an idea, feeling, or attitude permeates a system or permeates society, it affects every part of it or is present throughout it.","ex":{"en":"Bias against women permeates every level of the judicial system","cn":"司法体制中各个层面都有歧视女性的现象。"}},{"pos":"VERB 动词","cn":"渗透；弥漫；扩散","en":"If something permeates a place, it spreads throughout it.","ex":{"en":"The smell of roast beef permeated the air","cn":"空气中弥漫着烤牛肉的香味。"}}]},"examples":[{"en":"Dissatisfaction among the managers soon permeated down to members of the workforce.","cn":"管理人员的不满情绪很快传染给了全体职工。"},{"en":"The smell of leather permeated the room.","cn":"屋子里弥漫着皮革的气味。"}]},"pe":{"oxford":{"phon":"ˌpiː ˈiː","pos":"noun","senses":[{"en":"sport and exercise that is taught in schools (the abbreviation for ‘physical education’)","cn":"体育（课）（全写为 physical education）","ex":{"en":"a PE class","cn":"一堂体育课"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"体育（课）","en":"In schools, PE is a lesson in which pupils do physical exercises or sport. PE is an abbreviation for (缩略=) 'physical education'."}]},"media":{"uk":"media/uk/pe__gb_1.mp3","us":"media/us/pe__us_1.mp3"},"examples":[{"en":"a PE class","cn":"一堂体育课"},{"en":"a PE teacher","cn":"体育老师"}]},"pennies":{"lemma":"penny","media":{"uk":"media/ldoce/hwd/bre/d/pennies0205.mp3","us":"media/ldoce/hwd/ame/8/ld41pennies.mp3"}},"percussion":{"oxford":{"phon":"pəˈkʌʃn","pos":"noun","senses":[{"en":"musical instruments that you play by hitting them with your hand or with a stick, for example drums","cn":"打击乐器；敲击乐器","g":"[uncountable]","ex":{"en":"percussion instruments","cn":"打击乐器"}},{"en":"the players of percussion instruments in an orchestra","cn":"（管弦乐团的）打击乐器组","g":"[singular]"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"打击乐器","en":"Percussion instruments are musical instruments that you hit, such as drums."}]},"media":{"img":["media/pic/percussion_musicalinstruments_comp.jpg","media/thumb/glockenspiel.jpg"],"uk":"media/uk/percussion__gb_1.mp3","us":"media/us/percussion__us_1.mp3"},"examples":[{"en":"The track features Joey Langton on percussion.","cn":"唱片的这段乐曲是乔伊 · 兰顿演奏的打击乐。"},{"en":"percussion instruments","cn":"打击乐器"}]},"perfectly":{"media":{"uk":"media/uk/perfectly__gb_1.mp3","us":"media/us/perfectly__us_1.mp3"},"oxford":{"phon":"ˈpɜːfɪktli","pos":"adverb","senses":[{"en":"completely","cn":"完全地；非常；十分","lab":"old-fashioned","ex":{"en":"It's perfectly normal to feel like this.","cn":"有这样的感觉是完全正常的。"}},{"en":"in a perfect way","cn":"完美地；完好地；圆满地","ex":{"en":"The TV works perfectly now.","cn":"这台电视机现在状况好极了。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"完全地，十足地（尤用于所说的话可能会受质疑时）","en":"You can use perfectly to emphasize an adjective or adverb, especially when you think the person you are talking to might doubt what you are saying.","ex":{"en":"There's no reason why you can't have a perfectly normal child","cn":"你没有理由不能拥有一个完全正常的孩子。"}},{"pos":"ADV-GRADED 副词","cn":"完美地；十全十美地","en":"If something is done perfectly, it is done so well that it could not possibly be done better.","ex":{"en":"This adaptation perfectly captures the spirit of Kurt Vonnegut's novel","cn":"这次改编非常好地抓住了库尔特·冯内古特小说的精髓。"}},{"pos":"ADV 副词","cn":"绝对地；完全地","en":"If you describe something as perfectly good or acceptable, you are emphasizing that there is no reason to use or get something else, although other people may disagree.","ex":{"en":"You can buy perfectly good instruments for a lot less.","cn":"你可以少花一大笔钱买到顶好的仪器。"}}]},"examples":[{"en":"He stood perfectly still until the danger had passed.","cn":"他一动不动地站在那里，直到危险解除。"},{"en":"To be perfectly honest , I didn't want to go anyway.","cn":"说真心话，无论如何我是真的不想去。"}]},"penetration":{"media":{"uk":"media/uk/penetration__gb_1.mp3","us":"media/us/penetration__us_1.mp3"},"oxford":{"phon":"ˌpenəˈtreɪʃn","pos":"noun","senses":[{"en":"the act or process of making a way into or through something","cn":"穿透；渗透；进入","ex":{"en":"The floor is sealed to prevent water penetration.","cn":"地板加了密封涂料防止渗水。"}},{"en":"the act of putting the penis into a partner’s vagina or anus","cn":"（以阴茎）插入"}]},"examples":[{"en":"The floor is sealed to prevent water penetration.","cn":"地板加了密封涂料防止渗水。"},{"en":"the company's successful penetration of overseas markets","cn":"公司对海外市场的顺利开拓"}]},"perhaps":{"media":{"uk":"media/uk/perhaps__gb_1.mp3","us":"media/us/perhaps__us_1.mp3"},"oxford":{"phon":"pəˈhæps","pos":"adverb","senses":[{"en":"possibly","cn":"可能；大概；也许","ex":{"en":"‘Are you going to come?’ ‘Perhaps. I'll see how I feel.’","cn":"“你来不来？”“也许来。要看我身体情况了。”"}},{"en":"used when you want to make a statement or opinion less definite","cn":"（表示不确定）也许，可能","ex":{"en":"This is perhaps his best novel to date.","cn":"这也许是他迄今最好的小说。"}},{"en":"used when making a rough estimate","cn":"（用于粗略的估计）或许，可能","ex":{"en":"a change which could affect perhaps 20 per cent of the population","cn":"一项可能影响 20% 的人口的改革"}},{"en":"used when you agree or accept something unwillingly, or do not want to say that you think something is bad","cn":"（表示勉强同意或其实不赞成）也许，大概","ex":{"en":"‘You could do it yourself.’ ‘Yeah, perhaps.’","cn":"“你可以自己做。”“嗯，也许吧。”"}},{"en":"used when making a polite request, offer or suggestion","cn":"（用于委婉的请求、主动承诺或提出建议）也许，如果","ex":{"en":"Perhaps it would be better if you came back tomorrow.","cn":"如果你明天回来，也许更好。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"可能；大概；也许","en":"You use perhaps to express uncertainty, for example, when you do not know that something is definitely true, or when you are mentioning something that may possibly happen in the future in the way you describe.","ex":{"en":"Millson regarded her thoughtfully. Perhaps she was right","cn":"米尔森若有所思地注视着她。或许她是对的。"}},{"pos":"ADV 副词","cn":"（用以缓和语气或表示礼貌）也许，可能","en":"You use perhaps in opinions and remarks to make them appear less definite or more polite.","ex":{"en":"Perhaps the most important lesson to be learned is that you simply cannot please everyone","cn":"也许最应吸取的教训就是懂得众口难调。"}},{"pos":"ADV 副词","cn":"（用于给出建议或在正式语体中提出请求）也许，或者","en":"You use perhaps when you are making suggestions or giving advice. Perhaps is also used in formal English to introduce requests.","ex":{"en":"Perhaps I may be permitted a few suggestions","cn":"也许我可以提几条建议。"}},{"pos":"ADV 副词","cn":"（委婉地表示不赞同或不接受）也许，大概","en":"You can say perhaps as a response to a question or remark, when you do not want to agree or accept, but think that it would be rude to disagree or refuse.","ex":{"en":"'You know it doesn't make sense for you.' — 'Perhaps. I don't know. Maybe it does maybe it doesn't.'","cn":"“你知道它对你来说没有意义。”——“也许吧，我不知道。可能有意义，也可能没意义。”"}}]},"examples":[{"en":"‘Are you going to come?’ ‘Perhaps. I'll see how I feel.’ “","cn":"你来不来？” “也许来。要看我身体情况了。”"},{"en":"‘You could do it yourself.’ ‘Yeah, perhaps.’ “","cn":"你可以自己做。” “嗯，也许吧。”"}]},"personally":{"media":{"uk":"media/uk/personally__gb_1.mp3","us":"media/us/personally__us_1.mp3"},"oxford":{"phon":"ˈpɜːsənəli","pos":"adverb","senses":[{"en":"used to show that you are giving your own opinion about something","cn":"就本人而言；就个人意见","ex":{"en":"Personally, I prefer the second option.","cn":"就我个人而言，我倾向第二种选择。"}},{"en":"by a particular person rather than by somebody acting for them","cn":"本人；亲自","ex":{"en":"All emails will be answered personally.","cn":"所有电邮都将由本人亲自回复。"}},{"en":"in a way that is connected with one particular person rather than a group of people","cn":"个别地；单个地","ex":{"en":"He was personally criticized by inspectors for his incompetence.","cn":"他因不称职而受到检查员的个别批评。"}},{"en":"in a way that is intended to be offensive","cn":"无礼地；冒犯地","ex":{"en":"I'm sure she didn't mean it personally.","cn":"我相信她绝无冒犯之意。"}},{"en":"in a way that is connected with somebody’s personal life rather than with their job or official position","cn":"私人地（与工作相对）","ex":{"en":"Have you had any dealings with any of the suspects, either personally or professionally?","cn":"你是否与任何嫌疑人有过私人或业务来往？"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"在个人看来","en":"You use personally to emphasize that you are giving your own opinion.","ex":{"en":"Personally I think it's a waste of time","cn":"在我看来，这是浪费时间。"}},{"pos":"ADV 副词","cn":"亲自；亲自地；亲身地","en":"If you do something personally, you do it yourself rather than letting someone else do it.","ex":{"en":"The minister is returning to Paris to answer the allegations personally","cn":"部长将返回巴黎亲自回应那些指控。"}},{"pos":"ADV 副词","cn":"当面地；直接地；本人地","en":"If you meet or know someone personally, you meet or know them in real life, rather than knowing about them or knowing their work.","ex":{"en":"He did not know them personally, but he was familiar with their reputation","cn":"他并不认识他们，但已久仰他们的大名。"}},{"pos":"ADV 副词","cn":"个别地；单个地","en":"You can use personally to say that something refers to an individual person rather than to other people.","ex":{"en":"He was personally responsible for all that the people had suffered under his rule","cn":"他个人要为他统治时人民所受的所有苦难负责。"}},{"pos":"ADV 副词","cn":"私人地；私下里","en":"You can use personally to show that you are talking about someone's private life rather than their professional or public life.","ex":{"en":"This has taken a great toll on me personally and professionally","cn":"这给我的个人生活和我的工作都造成了严重的不良影响。"}},{"pos":"PHRASE 短语","cn":"把…看作是针对个人的","en":"If you take someone's remarks personally, you are upset because you think that they are criticizing you in particular.","ex":{"en":"I take everything too personally","cn":"我太主观了，认为一切都是针对我的。"}}]},"examples":[{"en":"‘Is it worth the effort?’ ‘Speaking personally, yes.’ “","cn":"值得为它费工夫吗？” “就本人而言，值得。”"},{"en":"Have you had any dealings with any of the suspects, either personally or professionally?","cn":"你是否与任何嫌疑人有过私人或业务来往？"}]},"pepper":{"oxford":{"phon":"ˈpepə(r)","pos":"noun","senses":[{"en":"a powder made from dried berries (called peppercorns), used to give a hot, spicy taste to food","cn":"胡椒粉","g":"[uncountable]","ex":{"en":"Season with salt and pepper","cn":"用盐和胡椒粉调味"}},{"en":"a hollow fruit, usually red, green or yellow, eaten as a vegetable either raw or cooked","cn":"甜椒；柿子椒；灯笼椒","g":"[countable, uncountable]","lab":"British English","ex":{"en":"He gave me a great recipe for stuffed peppers.","cn":"他给了我一份极佳的做填馅辣椒的食谱。"}},{"en":"to put pepper on food","cn":"（在食物上）撒胡椒粉","ex":{"en":"peppered steak","cn":"撒了胡椒粉的牛排"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"胡椒粉","en":"Pepper is a hot-tasting spice which is used to flavour food.","ex":{"en":"Season with salt and pepper.","cn":"用盐和胡椒调味。"}},{"pos":"N-COUNT 可数名词","cn":"甜椒；柿子椒；灯笼椒","en":"A pepper, or in American English a bell pepper, is a hollow green, red, or yellow vegetable with seeds inside it."},{"pos":"VERB 动词","cn":"（小物体）密集地击打，连续击打","en":"If something is peppered with small objects, a lot of those objects hit it.","ex":{"en":"He was wounded in both legs and severely peppered with shrapnel","cn":"他两条腿都挂彩了，人也被如雨的弹片炸成重伤。"}},{"pos":"VERB 动词","cn":"布满；充满","en":"If something is peppered with things, it has a lot of those things in it or on it.","ex":{"en":"While her English was correct, it was peppered with French phrases","cn":"她的英语语法上没错，但是里面夹杂着很多法语短语。"}}]},"media":{"img":["media/ldoce/img/pepper.jpg","media/pic/salad_vegetables_comp.jpg"],"uk":"media/uk/pepper__gb_1.mp3","us":"media/us/pepper__us_1.mp3"},"examples":[{"en":"He peppered his speech with jokes.","cn":"他在讲演中插入了许多笑话。"},{"en":"Salt and pepper the potatoes.","cn":"给土豆放上盐和胡椒粉。"}]},"pentagon":{"media":{"img":["media/pic/polygons_comp.jpg","media/thumb/pentagon.jpg"],"uk":"media/uk/pentagon__gb_1.mp3","us":"media/us/pentagon__us_1.mp3"},"oxford":{"phon":"ˈpentəɡən","pos":"noun","senses":[{"en":"a flat shape with five straight sides and five angles","cn":"五边形；五角形","g":"[countable]","lab":"geometry"},{"en":"the building near Washington DC that is the headquarters of the US Department of Defense and the military leaders","cn":"五角大楼（指美国国防部）","g":"[singular]","ex":{"en":"a spokesman for the Pentagon","cn":"美国国防部发言人"}}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"五角大楼（美国国防部办公大楼）；美国国防部","en":"The Pentagon is the main building of the US Defense Department, in Washington. The US Defense Department is often referred to as the Pentagon .","ex":{"en":"...a news conference at the Pentagon","cn":"在五角大楼召开的记者招待会"}}]},"examples":[{"en":"a spokesman for the Pentagon","cn":"美国国防部发言人"}]},"pen":{"media":{"uk":"media/uk/pen__gb_1.mp3","us":"media/us/pen__us_1.mp3"},"oxford":{"phon":"pen","pos":"noun","senses":[{"en":"an instrument made of plastic or metal used for writing with ink (= coloured liquid for writing, etc.)","cn":"笔；钢笔","lab":"figurative","ex":{"en":"an ink pen","cn":"钢笔"}},{"en":"a small piece of land surrounded by a fence in which farm animals are kept","cn":"圈；围栏；畜栏","ex":{"en":"a sheep pen","cn":"羊圈"}},{"en":"a penitentiary (= a prison)","cn":"监狱","lab":"North American English, informal，，"},{"en":"to write something","cn":"写","lab":"formal","ex":{"en":"He penned a letter to the local paper.","cn":"他给当地报纸写了一封信。"},"pos":"verb"},{"en":"to shut an animal or a person in a small space","cn":"（把…）关起来，圈起来","ex":{"en":"At clipping time sheep need to be penned.","cn":"在剪羊毛时，需要把羊圈起来。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"钢笔","en":"A pen is a long thin object which you use to write in ink. ballpoint pen→see: ; felt-tip pen→see: ;"},{"pos":"VERB 动词","cn":"写；书写","en":"If someone pens a letter, article, or book, they write it.","ex":{"en":"I really intended to pen this letter to you early this morning","cn":"我真的打算今天一大早给你写这封信的。"}},{"pos":"N-COUNT 可数名词","cn":"栏；圈；棚","en":"A pen is also a small area with a fence round it in which farm animals are kept for a short time.","ex":{"en":"...a holding pen for sheep","cn":"暂时搭建的羊圈"}},{"pos":"VERB 动词","cn":"把…关起来；把…圈起来","en":"If people or animals are penned somewhere or are penned up, they are forced to remain in a very small area.","ex":{"en":"...to drive the cattle back to the house so they could be milked and penned for the night","cn":"将牛群赶回家，这样就能挤奶并将其关进牛棚过夜"}},{"pos":"N-COUNT 可数名词","cn":"监狱","en":"People sometimes say the pen to refer to a prison."},{"pos":"PHRASE 短语","cn":"动笔；下笔","en":"If you put pen to paper, you write something.","ex":{"en":"Whenever he put pen to paper he was at a loss for the right words to break the news.","cn":"他每次一提笔就不知道如何措辞透露这个消息。"}}]},"examples":[{"en":"The whole family were penned up in one room for a month.","cn":"全家人被关在一间屋子里达一个月之久。"},{"en":"At clipping time sheep need to be penned.","cn":"在剪羊毛时，需要把羊圈起来。"}]},"penal":{"oxford":{"phon":"ˈpiːnl","pos":"adjective","senses":[{"en":"connected with or used for punishment, especially by law","cn":"惩罚的；刑罚的","ex":{"en":"penal reforms","cn":"刑罚改革"}},{"en":"that can be punished by law","cn":"应受刑罚的","ex":{"en":"a penal offence","cn":"刑事犯罪"}},{"en":"very severe","cn":"严重的；严厉的","ex":{"en":"penal rates of interest","cn":"惩罚性高利率"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"处罚的；刑罚的","en":"Penal means relating to the punishment of criminals.","ex":{"en":"...director-general of penal affairs at the justice ministry.","cn":"司法部刑事处处长"}},{"pos":"ADJ 形容词","cn":"（机构或地区）关押服刑人员的","en":"A penal institution or colony is one where criminals are kept as punishment.","ex":{"en":"...imprisoned on an island that has served as a penal colony since Roman times.","cn":"被关押在自罗马时代以来就一直作为罪犯流放地的小岛上"}}]},"media":{"uk":"media/uk/penal__gb_1.mp3","us":"media/us/penal__us_1.mp3"},"examples":[{"en":"Criminals could at one time be sentenced to penal servitude (= prison with hard physical work).","cn":"曾经有个时期，罪犯可以被判服劳役刑。"},{"en":"a penal colony (= a place where criminals were sent as a punishment in the past)","cn":"罪犯流放地"}]},"persian":{"media":{"uk":"media/uk/persian__gb_1.mp3","us":"media/us/persian__us_1.mp3"},"oxford":{"phon":"ˈpɜːʃn","pos":"noun","senses":[{"en":"a person from ancient Persia, or modern Persia, now called Iran","cn":"波斯人","g":"[countable]"},{"en":"the official language of Iran","cn":"波斯语","g":"[uncountable]"},{"en":"a type of cat with long hair, short legs and a round flat face","cn":"波斯猫","g":"[countable]"},{"en":"from or connected with ancient Persia, or modern Persia, now called Iran","cn":"波斯人","pos":"adjective"},{"en":"using or connected with the official language of Iran (= Persian, also called Farsi)","cn":"波斯语","pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"波斯的；伊朗的","en":"Something that is Persian belongs or relates to the ancient kingdom of Persia, or sometimes to the modern state of Iran.","ex":{"en":"...the Persian Empire.","cn":"波斯帝国"}},{"pos":"N-COUNT 可数名词","cn":"波斯人","en":"Persians were the people who came from the ancient kingdom of Persia."},{"pos":"ADJ 形容词","cn":"（地毯）波斯产的","en":"Persian carpets and rugs traditionally come from Iran. They are made by hand from silk or wool and usually have patterns in deep colours."},{"pos":"N-UNCOUNT 不可数名词","cn":"波斯语","en":"Persian is the language that is spoken in Iran, and was spoken in the ancient Persian empire."}]},"examples":[{"en":"the Persian Empire","cn":"波斯帝国"},{"en":"a Persian carpet","cn":"波斯地毯"}]},"per":{"media":{"uk":"media/uk/per__gb_1.mp3","us":"media/us/per__us_1.mp3"},"oxford":{"phon":"pə(r)","pos":"preposition","senses":[{"en":"used to express the cost or amount of something for each person, number used, distance travelled, etc.","cn":"每；每一","ex":{"en":"Rooms cost £50 per person, per night.","cn":"房价每人每晚 50 英镑。"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"（用来表示比率、比例等）每，每一","en":"You use per to express rates and ratios. For example, if something costs £50 per year, you must pay £50 each year for it. If a vehicle is travelling at 40 miles per hour, it travels 40 miles each hour. per head→see: ;","ex":{"en":"Social Security refused to pay her more than £17 per week","cn":"社会保障部门拒绝每周向她支付17英镑以上的钱。"}},{"pos":"PREP-PHRASE 短语介词","cn":"依照；依据","en":"If something happens as per a particular plan or suggestion, it happens in the way planned or suggested.","ex":{"en":"When they reach here they complain that they are not being paid as per the agreement","cn":"来到这里后，他们抱怨工资没有依照协议发放。"}}]},"examples":[{"en":"Rooms cost £50 per person, per night.","cn":"房价每人每晚 50 英镑。"},{"en":"The work was carried out as per instructions.","cn":"工作是按指示进行的。"}]},"pedantic":{"media":{"uk":"media/uk/pedantic__gb_1.mp3","us":"media/us/pedantic__us_1.mp3"},"oxford":{"phon":"pɪˈdæntɪk","pos":"adjective","senses":[{"en":"too worried about small details or rules","cn":"迂腐的；学究气的","ex":{"en":"a pedantic insistence on the correct way of doing things","cn":"迂腐地坚持正确的做事方式"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"过分拘泥于细节（或传统）的；学究气的；迂腐的","en":"If you think someone is pedantic, you mean that they are too concerned with unimportant details or traditional rules, especially in connection with academic subjects.","ex":{"en":"His lecture was so pedantic and uninteresting.","cn":"他的讲座学究气太浓，没意思。"}}]},"examples":[{"en":"Some people can be very pedantic about punctuation.","cn":"有些人会对标点符号过于讲究。"}]},"pessimism":{"oxford":{"phon":"ˈpesɪmɪzəm","pos":"noun","senses":[{"en":"a feeling that bad things will happen and that something will not be successful","cn":"悲观；悲观情绪；悲观主义","ex":{"en":"There is a mood of pessimism in the company about future job prospects.","cn":"公司中有一种对工作前景悲观的情绪。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"悲观；悲观主义","en":"Pessimism is the belief that bad things are going to happen.","ex":{"en":"...universal pessimism about the economy","cn":"对经济所持的普遍悲观态度"}}]},"media":{"uk":"media/uk/pessimism__gb_1.mp3","us":"media/us/pessimism__us_1.mp3"},"examples":[{"en":"There is a mood of pessimism in the company about future job prospects.","cn":"公司中有一种对未来职场前景悲观的情绪。"},{"en":"There is deep pessimism about the future.","cn":"对未来存在着极度悲观的情绪。"}]},"perceive":{"media":{"uk":"media/uk/perceive__gb_1.mp3","us":"media/us/perceive__us_1.mp3"},"oxford":{"phon":"pəˈsiːv","pos":"verb","senses":[{"en":"to understand or think of somebody/something in a particular way","cn":"将…理解为；将…视为；认为","ex":{"en":"This discovery was perceived as a major breakthrough.","cn":"这一发现被视为一项重大突破。"}},{"en":"to notice or become aware of something","cn":"注意到；意识到；察觉到","ex":{"en":"I perceived a change in his behaviour.","cn":"我注意到他举止有些改变。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"注意到，察觉，意识到（尤指不明显之物）","en":"If you perceive something, you see, notice, or realize it, especially when it is not obvious.","ex":{"en":"A key task is to get pupils to perceive for themselves the relationship between success and effort","cn":"关键任务是让学生们自己认识到成功和努力之间的关系。"}},{"pos":"VERB 动词","cn":"看作；视为；认为","en":"If you perceive someone or something as doing or being a particular thing, it is your opinion that they do this thing or that they are that thing.","ex":{"en":"Stress is widely perceived as contributing to coronary heart disease","cn":"压力被广泛认为是导致冠心病的一个因素。"}}]},"examples":[{"en":"This discovery was perceived as a major breakthrough.","cn":"这一发现被视为一项重大突破。"},{"en":"They were widely perceived to have been unlucky.","cn":"人们普遍认为他们的运气不佳。"}]},"people":{"media":{"uk":"media/uk/people__gb_1.mp3","us":"media/us/people__us_1.mp3"},"oxford":{"phon":"ˈpiːpl","pos":"noun","senses":[{"en":"human beings; men, women and children","cn":"人","g":"[plural]","ex":{"en":"At least ten people were killed in the crash.","cn":"至少有十人在撞车事故中丧生。"}},{"en":"humans in general; everyone","cn":"人们；大家","g":"[plural]","ex":{"en":"We want to change the way people think.","cn":"我们想改变人们的思维方式。"}},{"en":"all the people who live in a particular place or belong to a particular country, ethnic group, etc.","cn":"（统称）人民，国民；民族；种族","g":"[countable]","ex":{"en":"the American/French people","cn":"美国人；法国人"}},{"en":"men and women who work in a particular type of job or are involved in a particular area of activity","cn":"（统称某行业或领域的）人","g":"[plural]","ex":{"en":"a meeting with business people and bankers","cn":"与商界和银行界人士的会晤"}},{"en":"the ordinary citizens of a country rather than those who govern or have a special position in society","cn":"平民；百姓；大众","g":"[plural]","ex":{"en":"the life of the common people","cn":"普通人的生活"}},{"en":"the men, women and children that a person leads","cn":"国民；人民；臣民；群众","g":"[plural]","lab":"literary","ex":{"en":"The king urged his people to prepare for war.","cn":"国王呼吁臣民准备作战。"}},{"en":"the men and women who work for you or support you","cn":"雇员；支持者；下属人员","g":"[plural]","ex":{"en":"I've had my people watching the house for a few days.","cn":"我已让我的人监视那房子好几天了。"}},{"en":"guests or friends","cn":"客人；朋友","g":"[plural]","lab":"informal","ex":{"en":"I'm having people to dinner this evening.","cn":"今晚我在家里宴请客人。"}},{"en":"the men, women and children that you are closely related to, especially your parents, grandparents, etc.","cn":"家人；亲人；（尤指）父母，（外）祖父母","g":"[plural]","lab":"old-fashioned","ex":{"en":"She's spending the holidays with her people.","cn":"她正与家人一起度假。"}},{"en":"to live in a place or fill it with people","cn":"居住在；把…挤满人；住满居民","ex":{"en":"The town was peopled largely by workers from the car factory and their families.","cn":"这个镇上的居民大部分都是汽车厂的工人及其家属。"},"pos":"verb"},{"en":"a popular US magazine published each week. It contains photographs of and articles about film and television stars, as well as news stories. It was begun in 1974.","cn":"人：每周出版的美国流行杂志。它包含电影和电视明星以及新闻故事的照片和文章。它始于1974年。","pos":""},{"en":"The Sunday People","cn":"平民；百姓；大众","pos":""}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"人，人们（通常用作person的复数）","en":"People are men, women, and children. People is normally used as the plural of person, instead of 'persons'.","ex":{"en":"Millions of people have lost their homes.","cn":"数百万人流离失所。"}},{"pos":"N-PLURAL 复数名词","cn":"（与政府或上流社会相对的）人民，民众，大众","en":"The people is sometimes used to refer to ordinary men and women, in contrast to the government or the upper classes.","ex":{"en":"...the will of the people.","cn":"人民的意愿"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"一国人民；民族；种族","en":"A people is all the men, women, and children of a particular country or race.","ex":{"en":"...the native peoples of Central and South America","cn":"中南美洲的土著民族"}},{"pos":"VERB 动词","cn":"居住在；定居于","en":"If a place or country is peopled by a particular group of people, that group of people live there.","ex":{"en":"It was peopled by a fiercely independent race of peace-loving Buddhists.","cn":"那里住着一个与世隔绝的种族，人们都是爱好和平的佛教徒。"}},{"pos":"VERB 动词","cn":"（某种类型的人）出现，存在，充斥于（故事或历史时期）","en":"If something such as a story or a time in history is peopled with people of a particular kind, those people occur or exist in it.","ex":{"en":"Grass's novels are peopled with outlandish characters","cn":"格拉斯的小说里都是些稀奇古怪的人物。"}}]},"examples":[{"en":"The town was peopled largely by workers from the car factory and their families.","cn":"这个镇上的居民大部分都是汽车厂的工人及其家属。"},{"en":"She of all people should know the answer to that.","cn":"在所有的人中，她是最应知道那个问题的答案的。"}]},"performance":{"media":{"uk":"media/uk/performance__gb_1.mp3","us":"media/us/performance__us_1.mp3"},"oxford":{"phon":"pəˈfɔːməns","pos":"noun","senses":[{"en":"the act of performing a play, concert or some other form of entertainment","cn":"表演；演出","g":"[countable]","lab":"British English","ex":{"en":"The performance starts at seven.","cn":"演出七点开始。"}},{"en":"the way a person performs in a play, concert, etc.","cn":"艺术上的表现；演技","g":"[countable]","lab":"British English","ex":{"en":"She gave the greatest performance of her career.","cn":"她做了演艺生涯中最精彩的表演。"}},{"en":"how well or badly you do something; how well or badly something works","cn":"表现；性能；业绩；工作情况","g":"[uncountable, countable]","ex":{"en":"the country's strong economic performance over the last two years","cn":"过去两年该国强劲的经济表现"}},{"en":"the act or process of performing a task, an action, etc.","cn":"做；执行；履行","g":"[uncountable, singular]","lab":"formal","ex":{"en":"She has shown enthusiasm in the performance of her duties.","cn":"她在工作中表现出了热忱。"}},{"en":"an act that involves a lot of effort or trouble, sometimes when it is not necessary","cn":"（不必要的）麻烦，忙乱","g":"[singular]","lab":"informal, especially British English，，","ex":{"en":"It's such a performance getting the children off to school in the morning.","cn":"早上打发孩子上学可要忙乱一阵子呢。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"表演；演出","en":"A performance involves entertaining an audience by doing something such as singing, dancing, or acting.","ex":{"en":"Inside the theatre, they were giving a performance of Bizet's Carmen.","cn":"在剧院里，他们正在演出比才的作品《卡门》。"}},{"pos":"N-VAR 可变名词","cn":"表现；业绩；性能；运行情况","en":"Someone's or something's performance is how successful they are or how well they do something.","ex":{"en":"That study looked at the performance of 18 surgeons","cn":"那项研究调查了18名外科医生的工作表现。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（汽车的）性能","en":"A car's performance is its ability to go fast and to increase its speed quickly."},{"pos":"ADJ 形容词","cn":"性能卓越的；高性能的","en":"A performance car is one that can go very fast and can increase its speed very quickly."},{"pos":"N-SING 单数名词","cn":"执行；履行；做","en":"The performance of a task is the fact or action of doing it.","ex":{"en":"He devoted in excess of seventy hours a week to the performance of his duties","cn":"为了完成任务，他每周工作70多个小时。"}},{"pos":"N-SING 单数名词","cn":"复杂的事情；麻烦事","en":"You can describe something that is or looks complicated or difficult to do as a performance .","ex":{"en":"The whole process is quite a performance","cn":"整个过程相当复杂。"}},{"pos":"","cn":"","en":"a repeat performance→see: ;"}]},"examples":[{"en":"an Oscar-winning performance from Kate Winslet","cn":"凯特 · 温斯莱特荣获奥斯卡奖的演出"},{"en":"It's such a performance getting the children off to school in the morning.","cn":"早上打发孩子上学可要忙乱一阵子呢 。"}]},"pension":{"oxford":{"phon":"ˈpenʃn","pos":"noun","senses":[{"en":"an amount of money paid regularly by a government or company to somebody who has retired from work","cn":"养老金；退休金；抚恤金","lab":"often ironic) 102／23 （） 102／23 （）","ex":{"en":"to receive a retirement pension","cn":"领退休金"}},{"en":"a small, usually cheap, hotel in some European countries, especially France","cn":"（欧洲，尤指法国的）廉价小旅店"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"养老金；退休金；抚恤金","en":"Someone who has a pension receives a regular sum of money from the state or from a former employer because they have retired or because they are widowed or disabled.","ex":{"en":"...struggling by on a pension.","cn":"靠养老金苦苦支撑"}},{"pos":"","cn":"","en":"相关词组：pension off"}]},"media":{"uk":"media/uk/pension__gb_1.mp3","us":"media/us/pension__us_1.mp3"},"examples":[{"en":"He was pensioned off and his job given to a younger man.","cn":"他被迫退休，工作交给了一个比他年轻的人。"},{"en":"( informal, figurative ) That car of yours should have been pensioned off years ago.","cn":"你那辆汽车早就该报废了。"}]},"pest":{"oxford":{"phon":"pest","pos":"noun","senses":[{"en":"an insect or animal that destroys plants, food, etc.","cn":"害虫；害兽；害鸟","ex":{"en":"insect/plant/garden pests","cn":"害虫；作物／花园害虫"}},{"en":"an annoying person or thing","cn":"讨厌的人（或物）","lab":"informal","ex":{"en":"That child is being a real pest.","cn":"那个孩子真讨厌。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"害虫；害兽","en":"Pests are insects or small animals which damage crops or food supplies.","ex":{"en":"...crops which are resistant to some of the major insect pests and diseases","cn":"对一些主要病虫害有抵御能力的作物"}},{"pos":"N-COUNT 可数名词","cn":"讨厌鬼（尤指儿童）","en":"You can describe someone, especially a child, as a pest if they keep bothering you.","ex":{"en":"He climbed on the table, pulled my hair, and was generally a pest.","cn":"他爬桌子，拽我的头发，总之是个讨厌鬼。"}}]},"media":{"uk":"media/uk/pest__gb_1.mp3","us":"media/us/pest__us_1.mp3"},"examples":[{"en":"That child is being a real pest.","cn":"那个孩子真讨厌。"},{"en":"insect/plant/garden pests","cn":"害虫；作物/花园害虫"}]},"pets":{"lemma":"pet","media":{"uk":"media/uk/pet__gb_1.mp3","us":"media/us/pet__us_1.mp3"}},"perfect":{"media":{"uk":"media/uk/perfect__gb_1.mp3","us":"media/us/perfect__us_1.mp3"},"oxford":{"phon":"ˈpɜːfɪkt","pos":"adjective","senses":[{"en":"having everything that is necessary; complete and without faults or weaknesses","cn":"完备的；完美的；完全的","ex":{"en":"in perfect condition","cn":"状况极佳"}},{"en":"completely correct; exact and accurate","cn":"完全正确的；准确的；地道的","ex":{"en":"She speaks perfect English.","cn":"她讲一口地道的英语。"}},{"en":"the best of its kind","cn":"优秀的；最佳的","ex":{"en":"a perfect example of the painter’s early style","cn":"这位画家早期风格的典范"}},{"en":"excellent; very good","cn":"极好的；很好的","ex":{"en":"The weather was perfect.","cn":"天气好极了。"}},{"en":"exactly right for somebody/something","cn":"正合适的","ex":{"en":"Hawaii is the perfect place for a honeymoon.","cn":"夏威夷是度蜜月的最佳去处。"}},{"en":"total; complete","cn":"全部的；完全的；纯然的","g":"[only before noun]","ex":{"en":"I don't know him—he's a perfect stranger.","cn":"我不认识他，他是百分之百的陌生人。"}},{"en":"connected with the form of a verb that consists of part of the verb have with the past participle of the main verb, used to express actions completed by the present or a particular point in the past or future","cn":"（动词）完成时的，完成体的","lab":"grammar","ex":{"en":"‘I have eaten’ is the present perfect tense of the verb ‘to eat’, ‘I had eaten’ is the past perfect and ‘I will have eaten’ is the future perfect.","cn":"I have eaten 是动词 eat 的现在完成时；I had eaten 是过去完成时；I will have eaten 是将来完成时。"}},{"en":"to make something perfect or as good as you can","cn":"使完善；使完美；使完备","ex":{"en":"As a musician, she has spent years perfecting her technique.","cn":"身为音乐家，她多年来不断在技艺上精益求精。"},"pos":"verb"},{"en":"the form of a verb that expresses actions completed by the present or a particular point in the past or future, formed in English with part of the verb have and the past participle of the main verb","cn":"完成时；完成式","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"完美的；最佳的","en":"Something that is perfect is as good as it could possibly be. practice makes perfect→see: ;","ex":{"en":"He spoke perfect English","cn":"他英语说得棒极了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"绝配的；十分合适的","en":"If you say that something is perfect for a particular person, thing, or activity, you are emphasizing that it is very suitable for them or for that activity.","ex":{"en":"Carpet tiles are perfect for kitchens because they're easy to take up and wash","cn":"方块地毯非常适用于厨房，因为其便于揭起来清洗。"}},{"pos":"ADJ 形容词","cn":"无瑕的；完好的；完美无缺的","en":"If an object or surface is perfect, it does not have any marks on it, or does not have any lumps, hollows, or cracks in it.","ex":{"en":"Use only clean, Grade A, perfect eggs.","cn":"只用表面干净、无磕碰的A级鸡蛋。"}},{"pos":"ADJ 形容词","cn":"十足的；完全的","en":"You can use perfect to give emphasis to the noun following it.","ex":{"en":"She was a perfect fool","cn":"她愚蠢至极。"}},{"pos":"VERB 动词","cn":"使完美；完善","en":"If you perfect something, you improve it so that it becomes as good as it can possibly be.","ex":{"en":"We perfected a hand-signal system so that he could keep me informed of hazards","cn":"我们完善了一套手势信号，这样他就能随时告知我什么时候有危险了。"}},{"pos":"ADJ 形容词","cn":"（动词）完成时的","en":"The perfect tenses of a verb are the ones used to talk about things that happened or began before a particular time, as in 'He's already left' and 'They had always liked her'. The present perfect tense is sometimes called the perfect tense."}]},"examples":[{"en":"‘I have eaten’ is the present perfect tense of the verb ‘to eat’, ‘I had eaten’ is the past perfect and ‘I will have eaten’ is the future perfect. * I have eaten","cn":"是动词 eat 的现在完成时； I had eaten 是过去完成时； I will have eaten 是将来完成时。"},{"en":"As a musician, she has spent years perfecting her technique.","cn":"身为音乐家，她多年来不断在技艺上精益求精。"}]},"perpetrate":{"media":{"uk":"media/uk/perpetrate__gb_1.mp3","us":"media/us/perpetrate__us_1.mp3"},"oxford":{"phon":"ˈpɜːpətreɪt","pos":"verb","senses":[{"en":"to commit a crime or do something wrong or evil","cn":"犯（罪）；做（错事）；干（坏事）","ex":{"en":"to perpetrate a crime/fraud/massacre","cn":"犯罪；行骗；进行屠杀"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"犯（罪）；做（错事）；干（坏事）","en":"If someone perpetrates a crime or any other immoral or harmful act, they do it.","ex":{"en":"A high proportion of crime in any country is perpetrated by young males in their teens and twenties","cn":"在任何国家的犯罪者中，十几二十几岁的青年男性都占了很高的比例。"}}]},"examples":[{"en":"violence perpetrated against women and children","cn":"针对妇女和儿童的暴力行为"},{"en":"to perpetrate a crime/fraud/massacre","cn":"犯罪；行骗；进行屠杀"}]},"peas":{"lemma":"pea","media":{"img":["media/pic/peas_beans_comp.jpg","media/thumb/pea.jpg"],"uk":"media/uk/pea__gb_1.mp3","us":"media/us/pea__us_1.mp3"}},"perpetually":{"oxford":{"phon":"pəˈpetʃuəli","pos":"adverb","senses":[{"en":"in a way that continues for a long time without stopping","cn":"永久地：以持续很长时间而不连续停止","ex":{"en":"a perpetually changing environment","cn":"不断变化的环境"}},{"en":"repeatedly, in a way that is annoying","cn":"一再反复的；无尽无休的；没完没了的","ex":{"en":"a writer who is perpetually ignored by critics","cn":"一个永远被评论家忽视的作家"}},{"en":"in a way that lasts forever","cn":"永久地：永久地永久地成为","ex":{"en":"Water provides cost-free energy for generating electricity that is perpetually renewable.","cn":"水为发电提供了免费的能源，并且是永久可再生的。"}}]},"media":{"uk":"media/uk/perpetually__gb_1.mp3","us":"media/us/perpetually__us_1.mp3"},"examples":[{"en":"the perpetual noise of the machines","cn":""},{"en":"a little girl with a perpetual smile","cn":""}]},"perfectionism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"完美主义","en":"Perfectionism is the attitude or behaviour of a perfectionist."}]},"media":{"uk":"media/uk/perfectionism__gb_1.mp3","us":"media/us/perfectionism__us_1.mp3"},"examples":[{"en":"Many top athletes are perfectionists who drive themselves to excel.","cn":""}],"oxford":{"phon":"pəˈfekʃənɪzəm","pos":"noun","senses":[{"en":"the fact of liking to do things perfectly and not being satisfied with anything less","cn":"完美主义者；至善论者","ex":{"en":"Her perfectionism is evident at work and at home.","cn":"她的完美主义在工作和家庭中都很明显。"}}]}},"perfection":{"media":{"uk":"media/uk/perfection__gb_1.mp3","us":"media/us/perfection__us_1.mp3"},"oxford":{"phon":"pəˈfekʃn","pos":"noun","senses":[{"en":"the state of being perfect","cn":"完善；完美","ex":{"en":"physical perfection","cn":"体格健全"}},{"en":"the act of making something perfect by doing the final improvements","cn":"最后加工；完美；圆满","ex":{"en":"They have been working on the perfection of the new model.","cn":"他们一直在努力完善新型号。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"最佳；完美；十全十美","en":"Perfection is the quality of being as good as it is possible for something of a particular kind to be.","ex":{"en":"His quest for perfection is relentless","cn":"他不断追求完美。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"完美；极好","en":"If you say that something is perfection, you mean that you think it is as good as it could possibly be.","ex":{"en":"The house and garden were perfection.","cn":"房屋和花园都非常漂亮。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"完善；改善","en":"The perfection of something such as a skill, system, or product involves making it as good as it could possibly be.","ex":{"en":"Madame Clicquot is credited with the perfection of this technique.","cn":"这项技术的完善要归功于凯歌夫人。"}},{"pos":"PHRASE 短语","cn":"达到尽善尽美","en":"If something is done to perfection, it is done so well that it could not be done any better.","ex":{"en":"Like the old trouper he is, he timed his entry to perfection.","cn":"作为一名老戏骨，他上场的时间把握得恰到好处。"}}]},"examples":[{"en":"They have been working on the perfection of the new model.","cn":"他们一直在努力完善新型号。"},{"en":"His performance was perfection (= sth perfect).","cn":"他的演技真是炉火纯青。"}]},"pests":{"lemma":"pest"},"petroleum":{"media":{"uk":"media/uk/petroleum__gb_1.mp3","us":"media/us/petroleum__us_1.mp3"},"oxford":{"phon":"pəˈtrəʊliəm","pos":"noun","senses":[{"en":"mineral oil that is found under the ground or the sea and is used to produce petrol, paraffin, diesel oil, etc.","cn":"石油；原油","ex":{"en":"The government suspended its supplies of petroleum to the country as a result of the crisis.","cn":"受危机的影响，政府暂停了对那个国家的石油供应。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"石油；原油","en":"Petroleum is oil which is found under the surface of the earth or under the sea bed. Petrol and paraffin are obtained from petroleum."}]},"examples":[{"en":"petroleum-based products","cn":"石油产品"}]},"pence":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"media":{"uk":"media/uk/pence__gb_1.mp3","us":"media/us/pence__us_1.mp3"}},"percent":{"oxford":{"phon":"pə ˈsent","pos":"noun","senses":[{"en":"one part in every hundred","cn":"百分之 …"},{"en":"by, in or for every hundred","cn":"每一百中"}]},"media":{"uk":"media/ldoce/hwd/bre/e/percent_adj0205.mp3","us":"media/ldoce/hwd/ame/e/laadpercent1.mp3"},"examples":[{"en":"a 10% increase in house prices 10%","cn":"的房价上涨"},{"en":"a company with a 40 percent stake in the project","cn":"在那个项目中拥有40%股份的公司"}]},"personalities":{"lemma":"personality"},"permits":{"lemma":"permit"},"persuaded":{"lemma":"persuade"},"perspectives":{"lemma":"perspective"},"perceived":{"lemma":"perceive"},"performed":{"lemma":"perform"},"peers":{"lemma":"peer"},"periods":{"lemma":"period"},"peaches":{"oxford":{"phon":"piːtʃ","pos":"noun","senses":[{"en":"a round fruit with soft red and yellow skin, yellow flesh and a large rough seed inside","cn":"桃；桃子"},{"en":"( old-fashioned, informal ) a particularly good or attractive person or thing","cn":"极好的人（或物）；特别漂亮的东西（或人）"}]}},"pedestrians":{"oxford":{"phon":"pəˈdestriən","pos":"noun","senses":[{"en":"a person walking in the street and not travelling in a vehicle","cn":"行人；步行者"},{"en":"used by or for the use of pedestrians ; connected with pedestrians","cn":"行人使用的；行人的"}]}},"perceptions":{"lemma":"perception"},"peculiarities":{"lemma":"peculiarity"},"peasants":{"lemma":"peasant"},"peoples":{"lemma":"people"},"persons":{"lemma":"person"},"performing":{"lemma":"perform"},"permitted":{"lemma":"permit"},"pesticides":{"lemma":"pesticide"},"perfected":{"lemma":"perfect"},"peaks":{"lemma":"peak"},"peering":{"lemma":"peer"},"perimeters":{"lemma":"perimeter"},"peru":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a country on the west coast of South America, north of Bolivia and south of Ecuador. Population: 29,849,303 (2014). Capital: Lima. The high Andes Mountains cover a large part of the country. People connect Peru especially with the Incas, a Native American peop","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/p028-000009670.mp3","us":"media/ldoce/hwd/ame/d/p028-000009670.mp3"},"oxford":{"phon":"pəˈruː","pos":"noun","senses":[{"en":"a country in South America","cn":"秘鲁（南美洲国家）"}]}},"peal":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（钟等）鸣，响","en":"When bells peal, they ring one after another, making a musical sound.","ex":{"en":"Church bells pealed at the stroke of midnight.","cn":"教堂大钟在午夜敲响。"}},{"pos":"N-COUNT 可数名词","cn":"持久响亮的声音；轰轰的响声","en":"A peal of laughter or thunder consists of a long, loud series of sounds.","ex":{"en":"I heard a peal of merry laughter.","cn":"我听到一阵响亮的欢笑声。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sudden loud sound of laughter","cn":"爆笑声"},{"en":"a loud sound of thunder","cn":"隆隆的雷声"},{"en":"the loud ringing sound made by a bell","cn":"响亮的钟声[铃声]"}]},"collocations":{"phrases":["ADJ. loud","VERB + PEAL burst into, give, let out He burst into peals of laughter. She let out a peal of laughter. | hear","PEAL + VERB ring out","PREP. with a ~ The bishop was welcomed to the church with a peal of bells. | ~ of","PHRASES a peal of bells/laughter/thunder • Note at SOUND 2 loud ringing sound of a bell","ADJ. loud","VERB + PEAL ring (out) The bells of the cathedral rang out their loud peal.","PEAL + VERB ring out"]},"media":{"uk":"media/ldoce/hwd/bre/d/peal_n0205.mp3","us":"media/ldoce/hwd/ame/9/peal1.mp3"},"examples":[{"en":"She burst into peals of laughter.","cn":"她忽然哈哈大笑起来。"},{"en":"a peal of bells rang out","cn":"洪亮的钟声响了起来"}],"oxford":{"phon":"piːl","pos":"noun","senses":[{"en":"a loud sound or series of sounds","cn":"响亮的声音；轰轰的响声","ex":{"en":"She burst into peals of laughter.","cn":"她忽然哈哈大笑起来。"}},{"en":"the loud ringing sound of a bell","cn":"洪亮的钟声","ex":{"en":"a peal of bells rang out","cn":"洪亮的钟声响了起来"}},{"en":"a set of bells that all have different notes; a musical pattern that can be rung on a set of bells","cn":"编钟；编钟音乐"},{"en":"to ring loudly","cn":"大声作响","g":"[intransitive]","ex":{"en":"The bells of the city began to peal out.","cn":"都市的钟声齐鸣。"},"pos":"verb"},{"en":"to suddenly laugh loudly","cn":"突然大笑","g":"[intransitive]","ex":{"en":"Ellen pealed with laughter.","cn":"埃伦忽然大笑起来。"},"pos":"verb"}]}},"perpendicular":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"垂直的；笔直的","en":"A perpendicular line or surface points straight up, rather than being sloping or horizontal.","ex":{"en":"We made two slits for the eyes and a perpendicular line for the nose","cn":"我们划了两道缝儿做眼睛,另外划了一条竖线做鼻子。"}},{"pos":"ADJ 形容词","cn":"垂直（于）的；成90度角的","en":"If one thing is perpendicular to another, it is at an angle of 90 degrees to it.","ex":{"en":"The left wing dipped until it was perpendicular to the ground.","cn":"左翼下垂至与地面成90度角。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"in a vertical position","cn":""},{"en":"in a vertical direction, into or towards the sky","cn":""},{"en":"perfectly vertical in relation to the ground, or in relation to another line - used especially in technical contexts","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"Two lines that form a T are perpendicular to each other. They meet at a right angle. A person who is standing is perpendicular to the earth."}]},"collocations":{"phrases":["VERBS be","ADV. almost, nearly an almost perpendicular staircase 2 at an angle of 90&deg; to sth","VERBS be","ADV. exactly | almost | mutually two mutually perpendicular directions","PREP. to The axis of the moon will now be exactly perpendicular to that of the earth."]},"media":{"uk":"media/ldoce/hwd/bre/a/perpendicular_0205.mp3","us":"media/ldoce/hwd/ame/4/perpendicular1.mp3"},"examples":[{"en":"Are the lines perpendicular to each other?","cn":"这些直线相互垂直吗？"},{"en":"The staircase was almost perpendicular (= very steep).","cn":"楼梯几乎成垂直的了。"}],"oxford":{"phon":"ˌpɜːpənˈdɪkjələ(r)","pos":"adjective","senses":[{"en":"forming an angle of 90° with another line or surface; vertical and going straight up","cn":"垂直的；成直角的","ex":{"en":"Are the lines perpendicular to each other?","cn":"这些直线相互垂直吗？"}},{"en":"connected with a style of architecture common in England in the 14th and 15th centuries","cn":"垂直式的（英格兰 14、15 世纪盛行的建筑风格）","lab":"architecture"},{"en":"a line, position or direction that is exactly perpendicular","cn":"垂直线（或位置、方向）","ex":{"en":"The wall is a little out of the perpendicular.","cn":"墙壁有点倾斜。"},"pos":"noun"}]}},"perceptive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"观察敏锐的；有洞察力的；有悟性的","en":"If you describe a person or their remarks or thoughts as perceptive, you think that they are good at noticing or realizing things, especially things that are not obvious.","ex":{"en":"He was one of the most perceptive US political commentators.","cn":"他是美国最具洞察力的政治评论家之一。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"good at noticing things","cn":""},{"en":"good at noticing and understanding situations or people's feelings","cn":""},{"en":"if you do not miss much or do not miss a trick or a thing , you notice a lot about what is happening and what other people are doing or feeling","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If someone calls you perceptive , they mean you are good at understanding things or figuring things out. Perceptive people are insightful, intelligent, and able to see what others cannot."}]},"collocations":{"phrases":["VERBS be","ADV. extremely, highly, very a highly perceptive analysis of the problem | pretty, quite","PREP. about He's very perceptive about people."]},"media":{"uk":"media/ldoce/hwd/bre/0/perceptive0205.mp3","us":"media/ldoce/hwd/ame/5/perceptive.mp3"},"examples":[{"en":"It was very perceptive of you to notice that.","cn":"你能注意到此事，真够敏锐的。"},{"en":"our innate perceptive abilities","cn":"我们天生的五官感觉能力"}],"oxford":{"phon":"pəˈseptɪv","pos":"adjective","senses":[{"en":"having or showing the ability to see or understand things quickly, especially things that are not obvious","cn":"理解力强的；有洞察力的；思维敏捷的","lab":"approving","ex":{"en":"a highly perceptive comment","cn":"见地高明的评论"}},{"en":"connected with seeing, hearing and understanding","cn":"感知的；知觉的","lab":"specialist or formal","ex":{"en":"our innate perceptive abilities","cn":"我们天生的五官感觉能力"}}]}},"peril":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"重大危险","en":"Perils are great dangers.","ex":{"en":"...the perils of the sea","cn":"海洋的凶险"}},{"pos":"N-PLURAL 复数名词","cn":"（某活动或行为的）危险，问题","en":"The perils of a particular activity or course of action are the dangers or problems it may involve.","ex":{"en":"...the perils of starring in a television commercial.","cn":"拍电视广告的危险"}},{"pos":"PHRASE 短语","cn":"（用于警告）自冒风险","en":"If you say that someone does something at their peril, you are warning them that they will probably suffer as a result of doing it.","ex":{"en":"Ignore it at your peril","cn":"无视该问题要自担风险。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the possibility that someone or something will be harmed or killed","cn":""},{"en":"the possibility of serious harm if you do something dangerous - use this especially when you want to say how great the possibility is","cn":""},{"en":"something that may be dangerous, cause accidents etc","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If you realize mid-climb that your rock climbing rope is frayed, you might be in peril . The word peril means imminent danger to life and limb."}]},"collocations":{"phrases":["ADJ. deadly, dire, grave, great","VERB + PERIL be at/in | put sth in","PREP. ~ of All aboard were in grave peril of drowning.","PHRASES at your ~ Ignore these warnings at your peril. 2 sth dangerous","ADJ. great the great perils facing the environment | immediate | hidden","VERB + PERIL face We face the immediate peril of being bought out by another company. | avoid","PERIL + VERB face sth"]},"media":{"uk":"media/ldoce/hwd/bre/d/peril0205.mp3","us":"media/ldoce/hwd/ame/a/peril.mp3"},"examples":[{"en":"The country's economy is now in grave peril.","cn":"现在，这个国家的经济陷入了严重危机。"},{"en":"a warning about the perils of drug abuse","cn":"对吸毒之害的警告"}],"oxford":{"phon":"ˈperəl","pos":"noun","senses":[{"en":"serious danger","cn":"严重危险","g":"[uncountable]","ex":{"en":"The country's economy is now in grave peril.","cn":"现在，这个国家的经济陷入了严重危机。"}},{"en":"the fact of something being dangerous or harmful","cn":"祸害；险情","g":"[countable, usually plural]","ex":{"en":"She gave a warning about the perils of drug abuse.","cn":"她就吸毒的危害发出了警告。"}}]}},"pelvis":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"骨盆","en":"Your pelvis is the wide, curved group of bones at the level of your hips."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the set of large wide curved bones at the base of your spine , to which your legs are joined","cn":"骨盆"}]},"vocab":{"pos":"n","senses":[{"en":"Your pelvis is the series of bones at the base of the spine that support your legs. Remember that Elvis had a knack for moving his pelvis , and then you may more easily remember this body part!"}]},"collocations":{"phrases":["ADJ. narrow, wide | broken, fractured","VERB + PELVIS tilt, thrust"]},"media":{"img":["media/ldoce/img/skeleton.jpg"],"uk":"media/ldoce/hwd/bre/1/pelvis0205.mp3","us":"media/ldoce/hwd/ame/e/pelvis.mp3"},"examples":[{"en":"the pelvic bones","cn":"骨盆骨"}],"oxford":{"phon":"ˈpelvɪs","pos":"noun","senses":[{"en":"the wide curved set of bones at the bottom of the body that the legs and spine are connected to","cn":"骨盆"}]}},"permissible":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"容许的；许可的","en":"If something is permissible, it is considered to be acceptable because it does not break any laws or rules.","ex":{"en":"Religious practices are permissible under the Constitution","cn":"宪法允许进行宗教活动。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"allowed by law or by the rules 〔","cn":"法律或规定〕允许的﹐许可的﹐准许的"}]},"vocab":{"pos":"adj","senses":[{"en":"If something is permissible , then it is allowed. If it's not permissible then you probably shouldn't be doing it."}]},"collocations":{"phrases":["VERBS be | consider sth","ADV. perfectly This is perfectly permissible under the new regulations. | legally, morally"]},"media":{"uk":"media/ldoce/hwd/bre/a/permissible0205.mp3","us":"media/ldoce/hwd/ame/4/permissible.mp3"},"examples":[{"en":"It is not permissible for employers to discriminate on grounds of age.","cn":"资方不得以年龄为由歧视职工。"},{"en":"permissible levels of nitrates in water","cn":"水中硝酸盐含量的容许度"}],"oxford":{"phon":"pəˈmɪsəbl","pos":"adjective","senses":[{"en":"acceptable according to the law or a particular set of rules","cn":"容许的；许可的","ex":{"en":"permissible levels of nitrates in water","cn":"水中硝酸盐含量的容许度"}}]}},"persuasive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有说服力的；令人信服的","en":"Someone or something that is persuasive is likely to persuade a person to believe or do a particular thing.","ex":{"en":"What do you think were some of the more persuasive arguments on the other side?","cn":"你认为对方哪些观点更有说服力？"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"able to express your ideas and opinions in a strong, confident way so that you persuade people to agree with you","cn":""},{"en":"someone who is pushy annoys people by trying hard to make them do what they want, especially by repeatedly asking them or telling them to do something","cn":""},{"en":"a smooth-talking person is usually insincere or dishonest although they have a pleasant, confident way of talking which easily persuades people","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you are persuasive , then you have a knack for getting people to do things. Your most persuasive friend might be able to talk you into riding in a hot air balloon despite your fear of heights."}]},"collocations":{"phrases":["VERBS be | find sth","ADV. extremely, highly, very His analysis is in many ways highly persuasive. | fairly, quite | enough, sufficiently The evidence was not rea"]},"media":{"uk":"media/ldoce/hwd/bre/0/persuasive0205.mp3","us":"media/ldoce/hwd/ame/6/persuasive.mp3"},"examples":[{"en":"They argue persuasively in favour of a total ban on handguns.","cn":"他们以雄辩的论据支持全面禁用手枪。"},{"en":"He can be very persuasive.","cn":"他有时很会说服人。"}],"oxford":{"phon":"pəˈsweɪsɪv","pos":"adjective","senses":[{"en":"able to persuade somebody to do or believe something","cn":"有说服力的；令人信服的","ex":{"en":"There are several persuasive arguments in favour of the move.","cn":"有几个有说服力的论据支持此举。"}}]}},"perfume":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"香水","en":"Perfume is a pleasant-smelling liquid which women put on their skin to make themselves smell nice.","ex":{"en":"The hall smelled of her mother's perfume.","cn":"大厅里弥漫着她母亲身上的香水味。"}},{"pos":"N-MASS 物质名词","cn":"香精；香料","en":"Perfume is the ingredient that is added to some products to make them smell nice.","ex":{"en":"...a delicate white soap without perfume.","cn":"不含香料、味道淡雅的白色肥皂"}},{"pos":"N-COUNT 可数名词","cn":"芳香；香味；馨香","en":"The perfume of something is the pleasant smell it has.","ex":{"en":"...the perfume of roses","cn":"玫瑰花的芳香"}},{"pos":"VERB 动词","cn":"使香气弥漫","en":"If the smell of something perfumes a place or area, it makes it smell nice.","ex":{"en":"Flowers started to perfume the air","cn":"花儿的香气开始弥漫在空气中。"}},{"pos":"VERB 动词","cn":"为…增加香味","en":"If something is used to perfume a product, it is added to the product to make it smell nice.","ex":{"en":"The oil is used to flavour and perfume soaps, foam baths, and scents.","cn":"这种精油用来给肥皂、沐浴液和香水添加香味。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that you can recognize by breathing in through your nose","cn":""},{"en":"something that you smell for a short time","cn":""},{"en":"a smell – used especially about the pleasant smell from flowers, plants, or fruit. Also used about the smell left by an animal","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"That delicious mid-summer smell in the middle of a rose garden? You can call that its perfume ."}]},"collocations":{"phrases":["ADJ. expensive | cheap | strong | subtle | fragrant, sweet | exotic | musky | stale","QUANT. bottle","VERB + PERFUME use, wear | dab on, put on, spray on She dabbed some perfume on her wrists. | smell | reek of, smell of She reeked of cheap p","PERFUME + NOUN bottle | company, house","PHRASES a waft/whiff of perfume He caught a faint whiff of her expensive French perfume. 2 pleasant smell","ADJ. sweet | heady, strong | delicate, faint | exotic, strange","VERB + PERFUME smell | give off, release The lilies release their heady perfume in the evening.","PERFUME + VERB fill sth The perfume of the roses filled the room."]},"media":{"img":["media/ldoce/img/perfume.jpg"],"uk":"media/ldoce/hwd/bre/2/perfume_n0205.mp3","us":"media/ldoce/hwd/ame/8/l3perfume.mp3"},"examples":[{"en":"She perfumed her bath with fragrant oils.","cn":"她沐浴时在浴缸内洒了些芳香油。"},{"en":"We stock a wide range of perfumes.","cn":"我们备有各种各样的香水。"}],"oxford":{"phon":"ˈpɜːfjuːm","pos":"noun","senses":[{"en":"a liquid, often made from flowers, that you put on your skin to make yourself smell nice","cn":"香水","ex":{"en":"a bottle of expensive perfume","cn":"一瓶昂贵的香水"}},{"en":"a pleasant, often sweet, smell","cn":"芳香；香味；馨香","ex":{"en":"the heady perfume of the roses","cn":"玫瑰扑鼻的香味"}},{"en":"to make the air in a place smell pleasant","cn":"使香气弥漫","lab":"literary","ex":{"en":"The garden was perfumed with the smell of roses.","cn":"花园里弥漫着玫瑰的芳香。"},"pos":"verb"},{"en":"to put perfume in or on something","cn":"在…上洒香水；抹香水","ex":{"en":"She perfumed her bath with fragrant oils.","cn":"她沐浴时在浴缸内洒了些芳香油。"},"pos":"verb"}]}},"penance":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"补赎；悔罪；忏悔","en":"If you do penance for something wrong that you have done, you do something that you find unpleasant to show that you are sorry.","ex":{"en":"...a time of fasting, penance and pilgrimage","cn":"斋戒、补赎和朝圣的时代"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that you must do to show that you are sorry for something you have done wrong, especially in some religions 〔","cn":"尤见于某些宗教的〕苦修﹐补赎"},{"en":"something that you have to do but do not enjoy doing","cn":"被迫做的事﹐苦差"}]},"vocab":{"pos":"n","senses":[{"en":"Penance is the act of doing a good deed to make up for past wrongs. Shoveling your neighbor's sidewalk all winter could be your penance for not helping rake the leaves that dropped from your tree into his yard during the fall."}]},"collocations":{"phrases":["ADJ. public","VERB + PENANCE do, perform","PREP. as a ~ He devoted his life to helping the poor as a penance for his past crimes. | in ~ She knelt at her mother's feet in penance. | ~","PHRASES an act of penance"]},"media":{"uk":"media/ldoce/hwd/bre/2/penance0205.mp3","us":"media/ldoce/hwd/ame/a/penance.mp3"},"examples":[{"en":"She regards living in New York as a penance; she hates big cities.","cn":"她把住在纽约视为苦事，她讨厌大都市。"},{"en":"to do penance for your sins","cn":"为自己的罪过做补赎"}],"oxford":{"phon":"ˈpenəns","pos":"noun","senses":[{"en":"an act that you give yourself to do, or that a priest gives you to do, in order to show that you are sorry for something you have done wrong","cn":"补赎；悔罪；修和圣事","g":"[countable, usually singular, uncountable]","lab":"North American English","ex":{"en":"an act of penance","cn":"赎罪善功"}},{"en":"something that you have to do even though you do not like doing it","cn":"苦差事；被迫做的事","g":"[singular]","ex":{"en":"She regards living in New York as a penance; she hates big cities.","cn":"她把住在纽约视为苦事，她讨厌大都市。"}}]}},"perspiration":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"汗；汗珠","en":"Perspiration is the liquid which comes out on the surface of your skin when you are hot or frightened.","ex":{"en":"His hands were wet with perspiration.","cn":"他双手被汗水浸湿了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"sweat","cn":""},{"en":"liquid that appears on your skin when you are hot or nervous","cn":"汗﹐汗水"}]},"vocab":{"pos":"n","senses":[{"en":"Perspiration is a polite name for \"sweat.\" Perspiration is what makes you dread gym class and what keeps deodorant manufacturers in business."}]},"collocations":{"phrases":["QUANT. bead, drop Great beads of perspiration trickled down his forehead.","VERB + PERSPIRATION wipe He wiped the perspiration from his brow. | be bathed in, be drenched in, be soaked in My shirt was soaked in perspi","PERSPIRATION + VERB run down sth, trickle down sth Perspiration ran down his face. | break out Perspiration broke out on my skin. | glisten"]},"media":{"uk":"media/ldoce/hwd/bre/7/perspiration0205.mp3","us":"media/ldoce/hwd/ame/e/perspiration.mp3"},"examples":[{"en":"Perspiration cools the skin in hot weather.","cn":"热天出汗可使皮肤降温。"},{"en":"Beads of perspiration stood out on his forehead.","cn":"他的前额上挂着汗珠。"}],"oxford":{"phon":"ˌpɜːspəˈreɪʃn","pos":"noun","senses":[{"en":"drops of liquid that form on your skin when you are hot","cn":"汗；汗珠","ex":{"en":"Beads of perspiration stood out on his forehead.","cn":"他的前额上挂着汗珠。"}},{"en":"the act of perspiring","cn":"排汗；出汗","ex":{"en":"Perspiration cools the skin in hot weather.","cn":"热天出汗可使皮肤降温。"}}]}},"perishable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（食物)易腐烂的，易变质的","en":"Goods such as food that are perishable go bad after quite a short length of time.","ex":{"en":"...perishable food like fruit, vegetables and meat","cn":"水果、蔬菜、肉类等易变质的食品"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"food that is perishable is likely to decay quickly 〔","cn":"食品〕易腐烂的﹐易变质的"}]},"vocab":{"pos":"adj n","senses":[{"en":"Something perishable is likely to die or decay. A perishable is also a type of food with a limited shelf life if it's not refrigerated."}]},"collocations":{"phrases":["VERBS be","ADV. highly Many fresh foods are highly perishable."]},"media":{"uk":"media/ldoce/hwd/bre/3/perishable0205.mp3","us":"media/ldoce/hwd/ame/a/perishable.mp3"},"examples":[{"en":"perishable goods/foods","cn":"易腐烂变质的商品/食物"},{"en":"perishable goods such as butter, milk, fruit and fish","cn":"黄油﹑牛奶﹑水果和鱼等易变质的商品"}],"oxford":{"phon":"ˈperɪʃəbl","pos":"adjective","senses":[{"en":"likely to decay or go bad quickly","cn":"易腐烂的；易变质的","ex":{"en":"perishable goods/foods","cn":"易腐烂变质的商品／食物"}}]}},"perceptible":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"看得见的；察觉得到的","en":"Something that is perceptible can only just be seen or noticed.","ex":{"en":"Pasternak gave him a barely perceptible smile","cn":"帕斯特纳克给了他一个几乎无法察觉的微笑。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is obvious is very easy to notice or understand","cn":""},{"en":"if it is clear that something is true, it is easy to notice that it is true and you feel sure about it and have no doubts","cn":""},{"en":"use this to emphasize that it is easy to see that something is true","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something perceptible is noticeable, even if just slightly. A perceptible noise can be heard."}]},"collocations":{"phrases":["VERBS be | become","ADV. clearly, easily a clearly perceptible decline in public confidence | barely, hardly, scarcely His lips curved in a barely perceptible s","PREP. to The difference is scarcely perceptible to the average reader."]},"media":{"uk":"media/ldoce/hwd/bre/6/perceptible0205.mp3","us":"media/ldoce/hwd/ame/0/perceptible.mp3"},"examples":[{"en":"The price increase has had no perceptible effect on sales.","cn":"这次提价没有对销售产生明显的影响。"},{"en":"Her foreign accent was barely perceptible.","cn":"她的外国口音几乎听不出来。"}],"oxford":{"phon":"pəˈseptəbl","pos":"adjective","senses":[{"en":"great enough for you to notice it","cn":"可察觉到的；看得出的","lab":"formal","ex":{"en":"a perceptible change/increase/decline/impact","cn":"可以察觉的变化／增长／下降／影响"}},{"en":"that you can notice or feel with your senses","cn":"可感知的；可感觉的","lab":"specialist","ex":{"en":"the perceptible world","cn":"可感知的世界"}}]}},"perverse":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"任性的；故意作对的；无理取闹的","en":"Someone who is perverse deliberately does things that are unreasonable or that result in harm for themselves.","ex":{"en":"It would be perverse to stop this healthy trend","cn":"阻止这种健康发展的趋势是没有道理的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving in an unreasonable way, especially by deliberately doing the opposite of what people want you to do","cn":"任性的﹐一意孤行的﹐不合情理的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something that's perverse is deviant — it's not completely acceptable, and it may be even a little strange. Your perverse sense of humor probably makes some of your friends laugh while others just look uncomfortable."}]},"collocations":{"phrases":["VERBS be, seem","ADV. deeply, very This kind of reasoning is deeply perverse. | quite | almost | a little, rather, slightly, somewhat | deliberately Had you "]},"media":{"uk":"media/ldoce/hwd/bre/3/perverse0205.mp3","us":"media/ldoce/hwd/ame/9/perverse.mp3"},"examples":[{"en":"She finds a perverse pleasure in upsetting her parents.","cn":"她让父母担惊受怕，从中取得任性的快乐。"},{"en":"She seemed perversely proud of her criminal record.","cn":"她似乎不通人事，拿自己的前科当荣耀。"}],"oxford":{"phon":"pəˈvɜːs","pos":"adjective","senses":[{"en":"showing a deliberate and determined desire to behave in a way that most people think is wrong, unacceptable or unreasonable","cn":"执拗的；任性的；不通情理的","ex":{"en":"a perverse decision (= one that most people do not expect and think is wrong)","cn":"悖谬的决定"}}]}},"pennsylvania":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a state in the northeastern US, known for producing large amounts of steel and coal. It was one of the 13 original US states, and was an important centre in the fight to become independent from Britain during the American Revolutionary War.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/p028-000009624.mp3","us":"media/ldoce/hwd/ame/8/p028-000009624.mp3"},"oxford":{"phon":"ˌpenslˈveɪniə","pos":"","senses":[{"en":"a state in the north-eastern US, also called the Keystone State for its central position among the 13 original states. The largest city is Philadelphia, and the capital city is Harrisburg. The area was established for Quakers in 1681 by William Penn, who named it Pennsylvania ('Penn's small forest') for his father. The Battle of Gettysburg was fought there during the American Civil War. The state produces chemicals, medicines, electronic equipment and farm products. Tourist attractions include Valley Forge and the Pennsylvania Dutch region.","cn":"宾夕法尼亚（美国东北部的州，最大城市费城，首府哈里斯堡）"}]}},"permissive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"纵容的；放任的；姑息的","en":"A permissive person, society, or way of behaving allows or tolerates things which other people disapprove of.","ex":{"en":"...the permissive tolerance of the 1960s","cn":"20世纪60年代的“姑息纵容”"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not strict in the way that you punish people or control their behaviour","cn":""},{"en":"someone who is easy-going does not care about being strict, and is usually calm and relaxed","cn":""},{"en":"someone who is soft seems weak because they are not strict enough with other people","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Being permissive is the opposite of being strict. Permissive parents let their kids stay up later and have more sweets."}]},"collocations":{"phrases":["VERBS be | become","ADV. extremely, highly, very a highly permissive attitude | sexually a society that is sexually permissive"]},"media":{"uk":"media/ldoce/hwd/bre/c/permissive0205.mp3","us":"media/ldoce/hwd/ame/8/permissive.mp3"},"examples":[{"en":"permissive parents (= who allow their children a lot of freedom)","cn":"放任的父母"},{"en":"permissive attitudes","cn":"纵容的态度"}],"oxford":{"phon":"pəˈmɪsɪv","pos":"adjective","senses":[{"en":"allowing or showing a freedom of behaviour that many people do not approve of, especially in sexual matters","cn":"放任的；纵容的；姑息的；（尤指两性关系）放纵的","ex":{"en":"permissive attitudes","cn":"纵容的态度"}}]}},"peer":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（通常因难以看清而）盯着看，凝视，端详","en":"If you peer at something, you look at it very hard, usually because it is difficult to see clearly.","ex":{"en":"I had been peering at a computer print-out that made no sense at all","cn":"我一直盯着看一张毫无意义的计算机打印稿。"}},{"pos":"N-COUNT 可数名词","cn":"（英国有权或曾经有权在上议院投票的）贵族","en":"In Britain, a peer is a member of the nobility who has or had the right to vote in the House of Lords.","ex":{"en":"Lord Swan was made a life peer in 1981.","cn":"斯旺勋爵于1981年受封终身贵族。"}},{"pos":"N-COUNT 可数名词","cn":"同龄人；同辈；身份（或地位）相同的人","en":"Your peers are the people who are the same age as you or who have the same status as you.","ex":{"en":"...children who are much cleverer than their peers","cn":"比同龄人聪明许多的孩子"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"all the people in a society who are about the same age","cn":""},{"en":"all the people who are between two particular ages, considered as a group","cn":""},{"en":"a group of people, especially children or young people, who are all below a certain age - used especially in education or sport","cn":""}]},"vocab":{"pos":"1 v 2 n 3 n","senses":[{"en":"A peer is someone at your own level. If you are a 10th grader, other high school students are your peers ."}]},"collocations":{"phrases":["PEER + NOUN group She was rejected by her peer group. | pressure Children often take up smoking because of peer pressure.","PREP. among sb's ~s They adopt behaviour that is more socially acceptable among their peers. 2 person of noble rank","ADJ. Conservative, Labour, etc. | hereditary | life The Act made it possible for a woman to be created a life peer.","PHRASES a peer of the realm • Note at PEER"]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdepeer.mp3","us":"media/ldoce/hwd/ame/d/peer1.mp3"},"examples":[{"en":"Peer pressure is strong among young people (= they want to be like other people of the same age).","cn":"年轻人受到强大的同辈压力。"},{"en":"Children are worried about failing in front of their peers.","cn":"儿童都怕在同伴面前失败。"}],"oxford":{"phon":"pɪə(r)","pos":"noun","senses":[{"en":"a person who is the same age or who has the same social status as you","cn":"身份（或地位）相同的人；同龄人；同辈","g":"[usually plural]","ex":{"en":"She enjoys the respect of her peers.","cn":"她受到同侪的尊敬。"}},{"en":"(in the UK) a member of the nobility or the House of Lords","cn":"贵族成员；上议院议员","ex":{"en":"MPs and peers from all parties met to discuss the issue.","cn":"各党派的下议院和上议院议员们开会讨论了这个问题。"}},{"en":"to look closely or carefully at something, especially when you cannot see it clearly","cn":"仔细看；端详","ex":{"en":"We peered into the shadows.","cn":"我们往阴暗处仔细瞧。"},"pos":"verb"}]}},"pee":{"collins":{"senses":[{"pos":"VERB 动词","cn":"撒尿；小便","en":"When someone pees, they urinate.","ex":{"en":"He needed to pee.","cn":"他要小便。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to pass liquid waste from your body","cn":"撒尿"},{"en":"liquid waste passed from your body","cn":"尿"},{"en":"an act of passing liquid waste from your body","cn":"撒尿"}]},"vocab":{"pos":"v n","senses":[{"en":"Pee is an informal but common word that means \"to urinate.\" Of all the slang words for bodily functions, this is one of the least offensive."}]},"collocations":{"phrases":["VERB + PEE do, have, take I'm going to have a pee. | be bursting for, be desperate for, need, want I need a pee really badly. | go for"]},"media":{"uk":"media/ldoce/hwd/bre/3/pee_v0205.mp3","us":"media/ldoce/hwd/ame/2/l2pee.mp3"},"examples":[{"en":"I need to pee.","cn":"我要撒尿。"},{"en":"( BrE ) to go for a pee","cn":"去撒尿"}],"oxford":{"phon":"piː","pos":"verb","senses":[{"en":"to pass waste liquid from your body","cn":"撒尿","ex":{"en":"I need to pee.","cn":"我要撒尿。"}},{"en":"an act of passing liquid waste from your body","cn":"撒尿","g":"[singular]","lab":"British English","ex":{"en":"to go for a pee","cn":"去撒尿"},"pos":"noun"},{"en":"liquid waste passed from your body; urine","cn":"尿；小便","g":"[uncountable]","pos":"noun"}]}},"perseverance":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"毅力；韧性；不屈不挠的精神","en":"Perseverance is the quality of continuing with something even though it is difficult."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the quality of continuing to try to do something, even when it is difficult","cn":""},{"en":"the ability to control your mind and body in order to achieve something you have decided to do","cn":""},{"en":"the determination and energy to succeed, especially in business or work","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Perseverance is not giving up. It is persistence and tenacity, the effort required to do something and keep doing it till the end, even if it's hard."}]},"collocations":{"phrases":["ADJ. great, sheer | dogged, untiring","VERB + PERSEVERANCE have Does she have the perseverance to finish the work? | display, show He showed great perseverance by staying in the j","PERSEVERANCE + VERB pay off","PREP. with ~ Anyone can learn Japanese with perseverance. | ~ with His perseverance with the new technique paid off."]},"media":{"uk":"media/ldoce/hwd/bre/2/perseverance0205.mp3","us":"media/ldoce/hwd/ame/2/perseverance.mp3"},"examples":[{"en":"The only way to improve is through hard work and dogged perseverance.","cn":"要更上一层楼，唯一的途径就是艰苦奋斗，不屈不挠。"},{"en":"They showed great perseverance in the face of difficulty.","cn":"他们面对困难表现了坚强的毅力。"}],"oxford":{"phon":"ˌpɜːsəˈvɪərəns","pos":"noun","senses":[{"en":"the quality of continuing to try to achieve a particular aim despite difficulties","cn":"毅力；韧性；不屈不挠的精神","ex":{"en":"They showed great perseverance in the face of difficulty.","cn":"他们面对困难表现出了坚强的毅力。"}}]}},"pedal":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（自行车的）脚蹬，踏板","en":"The pedals on a bicycle are the two parts that you push with your feet in order to make the bicycle move."},{"pos":"VERB 动词","cn":"蹬，骑（自行车）","en":"When you pedal a bicycle, you push the pedals around with your feet to make it move.","ex":{"en":"She climbed on her bike with a feeling of pride and pedalled the five miles home","cn":"她自豪地骑上自行车，蹬了5英里路回家。"}},{"pos":"N-COUNT 可数名词","cn":"（汽车或机器的）踏板","en":"A pedal in a car or on a machine is a lever that you press with your foot in order to control the car or machine.","ex":{"en":"...the brake or accelerator pedals.","cn":"刹车或油门踏板"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the two parts of a bicycle that you push round with your feet to make the bicycle go forward 〔","cn":"自行车的〕踏板﹐脚蹬"},{"en":"a part in a car or on a machine that you press with your foot to control it 〔","cn":"汽车或机器的〕踏板"},{"en":"a part on a piano or organ that you press with your foot to change the quality of the sound 〔","cn":"钢琴或风琴的〕踏板"}]},"vocab":{"pos":"1 n v adj 2 n","senses":[{"en":"Anything you push with your feet to control a machine, vehicle, or instrument is a pedal . When you use a sewing machine, you push the pedal with your foot to make the needle move up and down."}]},"collocations":{"phrases":["ADV. fast, furiously, hard, like mad, madly He pedalled furiously up the hill. | slowly | away She pedalled away as fast as she could.","PREP. along, down, up He pedalled along the lane and up the hill."]},"media":{"uk":"media/ldoce/hwd/bre/b/pedal_n0205.mp3","us":"media/ldoce/hwd/ame/2/pedal1.mp3"},"examples":[{"en":"I saw her pedalling along the towpath.","cn":"我看见她在纤道上骑自行车。"},{"en":"I couldn't reach the pedals on her bike.","cn":"我骑她的车够不到脚蹬子。"}],"oxford":{"phon":"ˈpedl","pos":"noun","senses":[{"en":"a flat bar on a machine such as a bicycle, car, etc. that you push down with your foot in order to make parts of the machine move or work","cn":"（自行车、汽车等的）脚蹬子，踏板","ex":{"en":"I couldn't reach the pedals on her bike.","cn":"我骑她的车够不到脚蹬子。"}},{"en":"a bar on a musical instrument such as a piano or an organ that you push with your foot in order to control the sound","cn":"（钢琴、风琴等的）踏板，踏瓣，脚踏键","ex":{"en":"The soft pedal is placed leftmost in the row of pedals.","cn":"柔音踏板位于踏板排的最左侧。"}},{"en":"to ride a bicycle somewhere","cn":"骑自行车","g":"[intransitive, transitive]","ex":{"en":"I saw her pedalling along the towpath.","cn":"我看见她在纤道上骑自行车。"},"pos":"verb"},{"en":"to turn or press the pedals on a bicycle or other machine","cn":"踩踏板","g":"[intransitive, transitive]","ex":{"en":"You'll have to pedal hard up this hill.","cn":"走上坡时你必须用力蹬车。"},"pos":"verb"}]}},"perpetuate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使（尤指不好的情况、制度、信仰等）继续，延长","en":"If someone or something perpetuates a situation, system, or belief, especially a bad one, they cause it to continue.","ex":{"en":"We must not perpetuate the religious divisions of the past","cn":"我们绝对不能让过去的宗教分裂继续下去。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to continue something, often something that has been started by someone else","cn":""},{"en":"to make something continue in the same way or at the same high standard as before","cn":""},{"en":"to make something bad continue to exist, especially a situation that is not fair or involves false ideas","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Some things should last forever and others should not be perpetuated at all. Things that should NOT be perpetuated ? Ugly rumors, arms races, and your Aunt Martha's annual fruit cake."}]},"collocations":{"phrases":["ADV. merely, only, simply Giving these events a lot of media coverage merely perpetuates the problem.","VERB + PERPETUATE help (to) | serve to, tend to Schools tend to perpetuate the myth that boys are better at sport than girls. | seek to"]},"media":{"uk":"media/ldoce/hwd/bre/2/perpetuate0205.mp3","us":"media/ldoce/hwd/ame/8/perpetuate.mp3"},"examples":[{"en":"Comics tend to perpetuate the myth that ‘boys don't cry’.","cn":"连环画往往在延续着“男儿有泪不轻弹”的迷思。"},{"en":"This system perpetuated itself for several centuries.","cn":"这一制度维持了几个世纪。"}],"oxford":{"phon":"pəˈpetʃueɪt","pos":"verb","senses":[{"en":"to make something such as a bad situation, a belief, etc. continue for a long time","cn":"使永久化；使持久化；使持续","ex":{"en":"to perpetuate injustice","cn":"持续造成不公正"}}]}},"penalize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"惩罚；处罚","en":"If a person or group is penalized for something, they are made to suffer in some way because of it.","ex":{"en":"Some of the players may, on occasion, break the rules and be penalized","cn":"这些球员中有些偶尔可能会违规而受罚。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do something unpleasant to someone because they have done something wrong or broken the law","cn":""},{"en":"to make someone pay money as a punishment","cn":""},{"en":"if a judge sentences a criminal, he or she gives them an official punishment, usually sending them to prison for a period of time","cn":""}]},"collocations":{"phrases":["ADV. heavily | deliberately | unfairly, wrongly He claims he was unfairly penalized. | financially","PREP. for Students will be penalized for mistakes in spelling and grammar."]},"media":{"uk":"media/ldoce/hwd/bre/1/penalize0205.mp3","us":"media/ldoce/hwd/ame/5/penalize.mp3"},"examples":[{"en":"The new law appears to penalize the poorest members of society.","cn":"新法规似乎不利于社会中的最贫困者。"},{"en":"You will be penalized for poor spelling.","cn":"你拼写不好将会受到处罚。"}],"oxford":{"phon":"ˈpiːnəlaɪz","pos":"verb","senses":[{"en":"to punish somebody for breaking a rule or law by making them suffer a disadvantage","cn":"处罚；惩罚；处以刑罚","ex":{"en":"You will be penalized for poor spelling.","cn":"你拼写不好将会扣分。"}},{"en":"to punish somebody for breaking a rule in a sport or game by giving an advantage to their opponent","cn":"（体育运动中）判罚","ex":{"en":"He was penalized for time-wasting.","cn":"他因拖延时间而受罚。"}},{"en":"to put somebody at a disadvantage by treating them unfairly","cn":"置于不利地位；不公正地对待","ex":{"en":"The new law appears to penalize the poorest members of society.","cn":"新法规似乎不利于社会中的最贫困者。"}}]}},"perception":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"理解；看法；认识","en":"Your perception of something is the way that you think about it or the impression you have of it.","ex":{"en":"He is interested in how our perceptions of death affect the way we live.","cn":"他感兴趣的是我们对死亡的看法如何影响我们的生活。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"洞察力；认识能力；悟性","en":"Someone who has perception realizes or notices things that are not obvious.","ex":{"en":"It did not require a great deal of perception to realise the interview was over.","cn":"并不需要多少洞察力也能意识到面试已经结束了。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指视觉上的）感觉，感知","en":"Perception is the recognition of things using your senses, especially the sense of sight."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the way you think about something and your idea of what it is like","cn":"认识﹐观念﹔看法"},{"en":"the way that you notice things with your senses of sight, hearing etc","cn":"感觉﹐感知方式"},{"en":"the natural ability to understand or notice things quickly","cn":"洞察力﹔理解能力﹔感知能力"}]},"vocab":{"pos":"n","senses":[{"en":"Each generation has a different perception — view, idea or understanding — of what is cool. You wouldn't want to walk around in the paisley patterns of the 1960s or the big hair of the 1980s today!"}]},"collocations":{"phrases":["ADJ. clear | common, general, widely-held, widespread | growing | accurate | public | human | extrasensory, sensory, visual","VERB + PERCEPTION have I was shocked to learn of the perception people have of me. | gain We need to gain a clearer perception of how young "]},"media":{"uk":"media/ldoce/hwd/bre/d/perception0205.mp3","us":"media/ldoce/hwd/ame/7/perception.mp3"},"examples":[{"en":"She showed great perception in her assessment of the family situation.","cn":"她对家庭状况的分析显示出敏锐的洞察力。"},{"en":"There is a general public perception that standards in schools are falling.","cn":"公众普遍认为，学校的水平都在下降。"}],"oxford":{"phon":"pəˈsepʃn","pos":"noun","senses":[{"en":"an idea, a belief or an image you have as a result of how you see or understand something","cn":"看法；见解","g":"[uncountable, countable]","lab":"formal","ex":{"en":"a campaign to change public perception of the police","cn":"改变警察公众形象的运动"}},{"en":"the way you notice things, especially with the senses","cn":"知觉；感知","g":"[uncountable]","lab":"specialist or formal","ex":{"en":"Everyone's perception of reality is slightly different.","cn":"每个人对现实的感受都稍有不同。"}},{"en":"the ability to understand the true nature of something","cn":"洞察力；悟性","g":"[uncountable]","lab":"formal","ex":{"en":"She showed great perception in her assessment of the family situation.","cn":"她对家庭状况的分析显示出敏锐的洞察力。"}}]}},"perch":{"collins":{"senses":[{"pos":"VERB 动词","cn":"坐在…边缘；坐在…顶端","en":"If you perch on something, you sit down lightly on the very edge or tip of it.","ex":{"en":"He lit a cigarette and perched on the corner of the desk","cn":"他点了一根烟，坐在桌角上。"}},{"pos":"VERB 动词","cn":"在…顶部；在…边缘","en":"To perch somewhere means to be on the top or edge of something.","ex":{"en":"...the vast slums that perch precariously on top of the hills around which the city was built.","cn":"坐落在城市周围的山峰上、摇摇欲坠的贫民窟"}},{"pos":"VERB 动词","cn":"把…置于；使立稳于…的边缘（或顶部）","en":"If you perch something on something else, you put or balance it on the top or edge of that thing.","ex":{"en":"The builders have perched a light concrete dome on eight slender columns.","cn":"建筑工人在8根细柱上架起轻巧的混凝土穹顶。"}},{"pos":"VERB 动词","cn":"（鸟）栖息，停留","en":"When a bird perches on something such as a branch or a wall, it lands on it and stands there.","ex":{"en":"A blackbird flew down and perched on the parapet outside his window.","cn":"一只乌鸫飞下来，停在他窗外的矮墙上。"}},{"pos":"N-COUNT 可数名词","cn":"（鸟的）栖木，栖枝","en":"A perch is a short rod for a bird to stand on."},{"pos":"N-COUNT 可数名词","cn":"高位，高处","en":"You can refer to a high place where someone is sitting as their perch ."},{"pos":"PHRASE 短语","cn":"赶下神坛","en":"If someone is knocked off their perch, they are no longer admired or no longer thought of as important or clever.","ex":{"en":"There is a trend for knocking public-school headmasters and headmistresses off their perches.","cn":"现在有一种推翻公立学校校长权威性的趋势。"}},{"pos":"N-COUNT 可数名词","cn":"鲈鱼；河鲈","en":"A perch is an edible fish. There are several kinds of perch."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be resting your weight on your bottom somewhere, or to move into this position","cn":""},{"en":"to sit on a chair, bed, floor etc after you have been standing","cn":""},{"en":"to be sitting in a particular chair or place","cn":""}]},"vocab":{"pos":"1 n v 2 n 3 n","senses":[{"en":"A perch is a temporary resting place. In the middle of climbing a tree, you might find a good perch on a high branch. Bet some birds will be perching there too."}]},"collocations":{"phrases":["ADV. perilously, precariously The hotel was perched precariously on a steep hillside.","PREP. on The birds perched on nearby buildings.","PHRASES be perched high above/on sth The castle is perched high above the valley. | perch/be perched on the edge of sth I perched on the edg"]},"media":{"img":["media/ldoce/img/perch.jpg"],"uk":"media/ldoce/hwd/bre/2/perch_v0205.mp3","us":"media/ldoce/hwd/ame/8/perch1.mp3"},"examples":[{"en":"The hotel perched precariously on a steep hillside.","cn":"旅店立在陡峭的山坡上状似摇摇欲坠。"},{"en":"He watched the game from his precarious perch on top of the wall.","cn":"他无视安全，高坐在墙头上观看比赛。"}],"oxford":{"phon":"pɜːtʃ","pos":"verb","senses":[{"en":"to land and stay on a branch, etc.","cn":"栖息；停留","g":"[intransitive]","ex":{"en":"A robin was perching on the fence.","cn":"一只知更鸟落在篱笆上。"}},{"en":"to sit or to make somebody sit on something, especially on the edge of it","cn":"（使）坐，坐在…边沿","g":"[intransitive, transitive]","lab":"informal","ex":{"en":"We perched on a couple of high stools at the bar.","cn":"我们坐在酒吧的几张高脚凳上。"}},{"en":"to be placed on the top or the edge of something","cn":"置于（顶上或边上）","g":"[intransitive]","ex":{"en":"The hotel perched precariously on a steep hillside.","cn":"旅店立在陡峭的山坡上状似摇摇欲坠。"}},{"en":"a place where a bird rests, especially a branch or bar for this purpose, for example in a bird’s cage","cn":"（鸟的）栖息处，栖木","pos":"noun"},{"en":"a high seat or position","cn":"高座；高处","ex":{"en":"He watched the game from his precarious perch on top of the wall.","cn":"他无视安全，高坐在墙头上观看比赛。"},"pos":"noun"},{"en":"a freshwater fish that is sometimes used for food","cn":"鲈鱼；河鲈","pos":"noun"}]}},"peg":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"挂钩；挂钉","en":"A peg is a small hook or knob that is attached to a wall or door and is used for hanging things on.","ex":{"en":"His work jacket hung on the peg in the kitchen.","cn":"他的工作服挂在厨房里的挂钩上。"}},{"pos":"N-COUNT 可数名词","cn":"（晾衣用的）衣夹","en":"A peg is a small device which you use to fasten clothes to a washing line."},{"pos":"N-COUNT 可数名词","cn":"（金属或木制的）销钉，楔子，栓","en":"A peg is a small piece of wood or metal that is used for fastening something to something else.","ex":{"en":"He builds furniture using wooden pegs instead of nails.","cn":"他用木楔子取代钉子制作家具。"}},{"pos":"VERB 动词","cn":"用销钉（或楔子、木栓）固定","en":"If you peg something somewhere or peg it down, you fix it there with pegs.","ex":{"en":"...trying to peg a double sheet on a washing line on a blustery day","cn":"大风天试图用衣夹把双人床单固定在晾衣绳上"}},{"pos":"VERB 动词","cn":"限定（价格、数量等）；把…固定在一定水平；使与…挂钩","en":"If a price or amount of something is pegged at a particular level, it is fixed at that level.","ex":{"en":"Its currency is pegged to the dollar","cn":"其货币与美元挂钩。"}},{"pos":"PHRASE 短语","cn":"杀…的威风；挫…的锐气","en":"If you say that someone should be brought down a peg or be taken down a peg, you mean that they should be made to realize that they are not so important or wonderful as they think they are.","ex":{"en":"We thought it was time they were brought down a peg or two","cn":"我们认为是时候煞煞他们的嚣张气焰了。"}},{"pos":"PHRASE 短语","cn":"（衣服）非定制的，成品的","en":"Off-the-peg clothes are made in large numbers and sent to shops, not made specially for a particular person.","ex":{"en":"...an off-the-peg two-piece suit","cn":"两件套西服成衣"}},{"pos":"PHRASE 短语","cn":"方枘圆凿；格格不入","en":"If you describe someone as a square peg in a round hole, you mean that they are in a situation or doing something that does not suit them at all.","ex":{"en":"Taylor is clearly the wrong man for the job — a square peg in a round hole.","cn":"泰勒明显不适合做这项工作——简直就是方枘圆凿。"}},{"pos":"","cn":"","en":"相关词组：peg out"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short piece of wood, metal, or plastic that is attached to a wall or fits into a hole, used especially to hang things on or to fasten things together","cn":"短钉﹐挂钉〔尤用于挂物或固定〕"},{"en":"a small plastic or wooden object used to fasten wet clothes to a thin rope to dry 〔","cn":"晾衣服用的塑料或木制〕衣夹"},{"en":"a pointed piece of wood or metal that you push into the ground in order to keep a tent in the correct position 〔","cn":"用于固定帐篷的木制或金属〕桩"}]},"collocations":{"phrases":["ADJ. steel, wooden | tent","VERB + PEG drive in, hammer in She hammered in the steel tent pegs. | insert, put in The score is kept by inserting pegs into a board."]},"media":{"uk":"media/ldoce/hwd/bre/1/peg_v0205.mp3","us":"media/ldoce/hwd/ame/f/peg1.mp3","img":["media/pic/peg_comp.jpg","media/thumb/peg.jpg"]},"examples":[{"en":"Each time we scored we were pegged back minutes later.","cn":"每次我们得分，几分钟后便被追上。"},{"en":"All their wet clothes were pegged out on the line.","cn":"他们的湿衣服都夹在绳子上晾着。"}],"oxford":{"phon":"peɡ","pos":"noun","senses":[{"en":"a short piece of wood, metal or plastic used for holding things together, hanging things on, marking a position, etc.","cn":"（木、金属或塑料）钉子，楔子，橛子，短桩","ex":{"en":"There's a peg near the door to hang your coat on.","cn":"门边有个钩子可以挂衣服。"}},{"en":"a small pointed piece of wood or metal that you attach to the ropes of a tent and push into the ground in order to hold the tent in place","cn":"（木制或金属）帐篷地钉，橛子"},{"en":"a piece of wood or plastic used for attaching wet clothes to a clothes line","cn":"晾衣夹子","lab":"both British English"},{"en":"a short piece of wood, metal or plastic that you turn to make the strings of a musical instrument tighter or looser","cn":"弦钮；琴轴；弦轴"},{"en":"a small amount of a drink, especially a strong alcoholic one","cn":"少量饮料；（尤指）少量烈酒","lab":"Indian English","ex":{"en":"a peg of whisky","cn":"一点威士忌"}},{"en":"to fasten something with pegs","cn":"用夹子夹住；用楔子钉住","ex":{"en":"All their wet clothes were pegged out on the line.","cn":"他们的湿衣服都夹在绳子上晾着。"},"pos":"verb"},{"en":"to fix or keep prices, wages, etc. at a particular level","cn":"使（价格、工资等）限定于某水平（或与…挂钩）","g":"[usually passive]","ex":{"en":"Pay increases will be pegged at 5 per cent.","cn":"工资涨幅将固定在 5%。"},"pos":"verb"},{"en":"to think of somebody in a particular way","cn":"视为；看作","lab":"North American English, informal，，","ex":{"en":"She pegged him as a big spender.","cn":"她觉得他是个大手大脚的人。"},"pos":"verb"}]}},"penniless":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"一文不名的；身无分文的","en":"Someone who is penniless has hardly any money at all.","ex":{"en":"They'd soon be penniless and homeless if she couldn't find suitable work.","cn":"她要找不到合适的工作，他们很快就会身无分文，无家可归。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having very little money and not many possessions – used about people or places","cn":""},{"en":"having very little money, especially for a short period of time. Skint is more informal than the other words","cn":""},{"en":"a developing country is poor and has very little industry","cn":""}]},"collocations":{"phrases":["VERBS be, die He died penniless in Paris. | find yourself Laura found herself virtually penniless. | leave sb The legal dispute left them pe","ADV. totally | almost, practically, virtually"]},"media":{"uk":"media/ldoce/hwd/bre/0/penniless0205.mp3","us":"media/ldoce/hwd/ame/e/penniless.mp3"},"examples":[{"en":"Uncle Charlie was jobless and penniless.","cn":"查理叔叔没有工作﹐一贫如洗。"}],"oxford":{"phon":"ˈpeniləs","pos":"adjective","senses":[{"en":"having no money; very poor","cn":"一文不名的；穷困的","ex":{"en":"a penniless student","cn":"贫困学生"}}]}},"perjury":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"伪证；伪证罪","en":"If someone who is giving evidence in a court of law commits perjury, they lie.","ex":{"en":"This witness has committed perjury and no reliance can be placed on her evidence.","cn":"这名证人作了伪证，她的证词不可信。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to deliberately tell someone something that is not true","cn":""},{"en":"to deliberately tell someone something that is not true","cn":""},{"en":"if someone, especially a child, tells tales , they tell lies about someone else, in order to make you believe that the other person has behaved badly","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Perjury is the act of deliberately lying under oath. A defendant in a murder trial commits perjury when he swears he never met the murder victim before, even though he had a two-year relationship with her."}]},"media":{"uk":"media/ldoce/hwd/bre/8/perjury0205.mp3","us":"media/ldoce/hwd/ame/1/perjury.mp3"},"examples":[{"en":"Hall was found guilty of perjury.","cn":"霍尔被判犯有伪证罪。"}],"oxford":{"phon":"ˈpɜːdʒəri","pos":"noun","senses":[{"en":"the crime of telling a lie in court after you have sworn to tell the truth","cn":"伪证（罪）","ex":{"en":"to commit perjury","cn":"犯伪证罪"}}]}},"perspire":{"collins":{"senses":[{"pos":"VERB 动词","cn":"出汗；排汗；发汗","en":"When you perspire, a liquid comes out on the surface of your skin, because you are hot or frightened.","ex":{"en":"He began to perspire heavily.","cn":"他开始大量出汗。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"when you sweat your skin becomes wet, because you are hot, nervous, ill etc","cn":""},{"en":"to sweat","cn":""},{"en":"to start sweating, especially because you are nervous or afraid","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To perspire is to sweat: to excrete perspiration through the pores in your skin."}]},"collocations":{"phrases":["ADV. heavily, profusely He had been working hard and was perspiring profusely. | a little","PREP. with She was perspiring a little with the heat."]},"media":{"uk":"media/ldoce/hwd/bre/1/perspire0205.mp3","us":"media/ldoce/hwd/ame/3/perspire.mp3"},"examples":[{"en":"Willie was perspiring heavily .","cn":"威利大汗淋漓。"}],"oxford":{"phon":"pəˈspaɪə(r)","pos":"verb","senses":[{"en":"to produce sweat on your body","cn":"出汗；排汗；发汗","ex":{"en":"The game of squash left me perspiring profusely.","cn":"壁球比赛让我大汗淋漓。"}}]}},"perimeter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"外缘；边缘","en":"The perimeter of an area of land is the whole of its outer edge or boundary.","ex":{"en":"...the perimeter of the airport","cn":"机场四周"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of something that is furthest from its centre or nearest the place where it ends","cn":""},{"en":"the part of something that is near its left or right edge","cn":""},{"en":"the edge of something circular, especially the top of a cup or glass, or the outside edge of a pair of glasses","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The noun perimeter refers to the border of an enclosed space. The perimeter of a house is its property line. For a country, it would be that country’s borders."}]},"collocations":{"phrases":["ADJ. inner, outer | northern, southern, etc.","VERB + PERIMETER mark The river marks the eastern perimeter of our land.","PERIMETER + NOUN fence, wall | road, track","PREP. along the ~ I lugged my suitcase along the perimeter of the square. | around/round the ~ We walked round the perimeter of the prison. "]},"media":{"uk":"media/ldoce/hwd/bre/0/perimeter0205.mp3","us":"media/ldoce/hwd/ame/a/perimeter.mp3"},"examples":[{"en":"Guards patrol the perimeter of the estate.","cn":"保安人员在庄园四周巡逻。"},{"en":"a perimeter fence/track/wall","cn":"围绕四周的栅栏/小径/墙"}],"oxford":{"phon":"pəˈrɪmɪtə(r)","pos":"noun","senses":[{"en":"the outside edge of an area of land","cn":"（土地的）外缘，边缘","ex":{"en":"Guards patrol the perimeter of the estate.","cn":"保安人员在庄园四周巡逻。"}},{"en":"the total length of the outside edge of an area or a shape","cn":"周长","lab":"mathematics","ex":{"en":"Find the area and perimeter of the following shapes.","cn":"求下列形状的面积和周长。"}}]}},"perplexed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"困惑的；迷惑不解的","en":"If you are perplexed, you feel confused and slightly worried by something because you do not understand it.","ex":{"en":"She is perplexed about what to do for her daughter","cn":"她不知道该为女儿做些什么。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"completely unable to understand why or how something happened, especially because it is very different from what you expect","cn":""},{"en":"very confused and unable to understand something, even though you have tried hard for a long time","cn":""},{"en":"confused and worried by an event or situation that you do not understand","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective perplexed to describe someone who is utterly baffled or confused. If you've ever studied for the wrong test and been surprised and confused by the exam in front of you, you've been perplexed ."}]},"collocations":{"phrases":["VERBS be, feel, look, sound","ADV. deeply, genuinely, very | a little, rather, slightly, somewhat Gary looked rather perplexed."]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdeperplexed.mp3","us":"media/ldoce/hwd/ame/7/laadperplexed.mp3"},"examples":[{"en":"She looked perplexed.","cn":"她看来茫然若失。"},{"en":"a perplexed expression","cn":"困惑的表情"}],"oxford":{"phon":"pəˈplekst","pos":"adjective","senses":[{"en":"confused and anxious because you are unable to understand something; showing this","cn":"困惑的；迷惑不解的","ex":{"en":"a perplexed expression","cn":"困惑的表情"}}]}},"peculiarity":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"怪癖；古怪之处","en":"A peculiarity that someone or something has is a strange or unusual characteristic or habit.","ex":{"en":"Joe's other peculiarity was that he was constantly munching hard candy.","cn":"乔还有一个怪癖，就是喜欢不停地嚼硬糖。"}},{"pos":"N-COUNT 可数名词","cn":"独特之处；特性；个性","en":"A peculiarity is a characteristic or quality which belongs or relates only to one person or thing.","ex":{"en":"Each nation can have its own peculiarities when it comes to doing business.","cn":"每个民族做生意时都有自己的特色。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that is a feature of only one particular place, person, situation etc 〔","cn":"某地方﹑某人或某情况等的〕特点﹐独特性"},{"en":"a strange or unusual habit, quality etc","cn":"怪癖；奇异的性质"},{"en":"the quality of being strange or unfamiliar","cn":"奇特﹔怪异﹔古怪"}]},"collocations":{"phrases":["ADJ. physical | individual | local","VERB + PECULIARITY have The area has a few local peculiarities.","PREP. ~ about I noticed a certain peculiarity about his appearance."]},"media":{"uk":"media/ldoce/hwd/bre/f/peculiarity0205.mp3","us":"media/ldoce/hwd/ame/6/peculiarity.mp3"},"examples":[{"en":"the cultural peculiarities of the English","cn":"英国人的文化特点"},{"en":"a physical peculiarity","cn":"身体上的特征"}],"oxford":{"phon":"pɪˌkjuːliˈærəti","pos":"noun","senses":[{"en":"a strange or unusual feature or habit","cn":"怪异的性质（或习惯）；怪癖","g":"[countable]","ex":{"en":"a physical peculiarity","cn":"身体上的特征"}},{"en":"a feature that only belongs to one particular person, thing, place, etc.","cn":"（人、物、地等的）个性，特色，特点","g":"[countable]","ex":{"en":"the cultural peculiarities of the English","cn":"英格兰人的文化特点"}},{"en":"the fact of being strange or unusual","cn":"奇怪；怪异","g":"[uncountable]"}]}},"persecution":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指因宗教、政治信仰或种族而受到的）迫害","en":"Persecution is cruel and unfair treatment of a person or group, especially because of their religious or political beliefs, or their race.","ex":{"en":"...the persecution of minorities.","cn":"对少数派的迫害"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"cruel or unfair treatment of someone over a period of time, especially because of their religious or political beliefs 〔","cn":"尤指宗教或政治方面的〕迫害"}]},"vocab":{"pos":"n","senses":[{"en":"Persecution is unfair or abusive treatment toward a person or group of people, such as the persecution of someone who is different by calling him or her rude names and making threats."}]},"collocations":{"phrases":["ADJ. systematic | political, religious","VERB + PERSECUTION be subject/subjected to, face, suffer (from) Some students returning to the country may face political persecution. | esc","PERSECUTION + NOUN complex She started to have a persecution complex when she couldn't get a job.","PHRASES delusions/feelings of persecution, (a) fear of persecution, a victim of persecution"]},"media":{"uk":"media/ldoce/hwd/bre/c/ldoce6persecution.mp3","us":"media/ldoce/hwd/ame/f/laadpersecution.mp3"},"examples":[{"en":"the victims of religious persecution","cn":"宗教迫害的受难者"},{"en":"the persecution of writers who criticize the government","cn":"对批评政府的作家的迫害"}],"oxford":{"phon":"ˌpɜːsɪˈkjuːʃn","pos":"noun","senses":[{"en":"the act of treating somebody in a cruel and unfair way, especially because of their race, religion or political beliefs","cn":"（因种族、宗教或政治信仰）迫害，残害，压迫","ex":{"en":"the victims of religious persecution","cn":"宗教压迫的受害者"}},{"en":"the act of deliberately annoying somebody all the time and making their life unpleasant","cn":"骚扰；打扰；为…找麻烦"}]}},"pesticide":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"杀虫剂；农药","en":"Pesticides are chemicals which farmers put on their crops to kill harmful insects."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a chemical substance used to kill insects and small animals that destroy crops","cn":"杀虫剂﹐农药"}]},"vocab":{"pos":"n","senses":[{"en":"A pesticide is a bug-killing poison. You may have to resort to using a pesticide to battle the ants that have invaded your kitchen, even if you hate killing any creature."}]},"collocations":{"phrases":["ADJ. chemical | dangerous, hazardous | approved | banned, unapproved","QUANT. level It is claimed that current levels of pesticide do not pose a threat to health. | trace Traces of pesticide in the water were te","PESTICIDE + NOUN use | levels | residues | contamination, pollution tests for pesticide contamination in food | poisoning | spray","PHRASES the use of pesticide"]},"media":{"uk":"media/ldoce/hwd/bre/7/pesticide0205.mp3","us":"media/ldoce/hwd/ame/7/pesticide.mp3"},"examples":[{"en":"vegetables grown without the use of pesticides","cn":"未用杀虫剂种植的蔬菜"},{"en":"crops sprayed with pesticide","cn":"喷洒过杀虫剂的庄稼"}],"oxford":{"phon":"ˈpestɪsaɪd","pos":"noun","senses":[{"en":"a chemical used for killing pests, especially insects","cn":"杀虫剂；除害药物","ex":{"en":"vegetables grown without the use of pesticides","cn":"种植过程中未使用杀虫剂的蔬菜"}}]}},"petition":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"请愿书","en":"A petition is a document signed by a lot of people which asks a government or other official group to do a particular thing.","ex":{"en":"We recently presented the government with a petition signed by 4,500 people.","cn":"最近我们向政府递交了有4,500人签名的请愿书。"}},{"pos":"N-COUNT 可数名词","cn":"上诉；（对法庭的）请求","en":"A petition is a formal request made to a court of law for some legal action to be taken.","ex":{"en":"His lawyers filed a petition for all charges to be dropped","cn":"他的律师提请撤销所有指控。"}},{"pos":"VERB 动词","cn":"祈求；请求；请愿","en":"If you petition someone in authority, you make a formal request to them.","ex":{"en":"...couples petitioning for divorce","cn":"申请离婚的夫妇"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a statement, letter etc in which you ask for something politely or formally","cn":""},{"en":"a strong request saying very clearly what you want, especially when you are asking for something that someone does not want to give you","cn":""},{"en":"a request for something, especially money, that someone thinks they have a legal right to have","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If you're angry about the new rule that you have to wear bright pink shoes to work every day, why not write up a petition , get all your co-workers to sign it, and submit it to your boss."}]},"collocations":{"phrases":["ADJ. bankruptcy, divorce | protest","VERB + PETITION sign | deliver, file, present, send, submit | draw up, get up, launch, organize, raise | support | hear The petition will be","PETITION + VERB call for sth, demand sth, urge sth | oppose sth The petition opposes the closures. | support sth The petition supports the s","PREP. ~ against We're getting up a petition against the proposed building plans. | ~ by/from a petition by local residents | ~ for Local gov"]},"media":{"uk":"media/ldoce/hwd/bre/e/petition_n0205.mp3","us":"media/ldoce/hwd/ame/2/petition1.mp3"},"examples":[{"en":"Local residents have successfully petitioned against the siting of a prison in their area.","cn":"当地居民反对在区内兴建监狱的请愿成功了。"},{"en":"The workers are getting up (= starting) a petition for tighter safety standards.","cn":"工人正发起请愿，要求提高安全标准。"}],"oxford":{"phon":"pəˈtɪʃn","pos":"noun","senses":[{"en":"a written document signed by a large number of people that asks somebody in a position of authority to do or change something","cn":"请愿书","ex":{"en":"Would you like to sign our petition against experiments on animals?","cn":"你愿意在我们这份反对动物实验的请愿书上签字吗？"}},{"en":"an official document asking a court to take a particular course of action","cn":"申诉书；申请书","lab":"law","ex":{"en":"a bankruptcy petition","cn":"破产申请"}},{"en":"a formal prayer to God or request to somebody in authority","cn":"祈祷；祈求","lab":"formal"},{"en":"to make a formal request to somebody in authority, especially by sending them a petition","cn":"祈求；请求；请愿","g":"[intransitive, transitive]","ex":{"en":"Local residents have successfully petitioned against the siting of a prison in their area.","cn":"当地居民反对在区内兴建监狱的请愿成功了。"},"pos":"verb"},{"en":"to formally ask for something in court","cn":"（向法庭）请求，申请","g":"[intransitive, transitive]","ex":{"en":"His wife petitioned for divorce in 1997.","cn":"他的妻子在1997年提出了离婚申请。"},"pos":"verb"}]}},"penalty":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"刑罚；处罚；惩罚","en":"A penalty is a punishment that someone is given for doing something which is against a law or rule.","ex":{"en":"One of those arrested could face the death penalty","cn":"被捕的那些人中有一人可能被判死刑。"}},{"pos":"N-COUNT 可数名词","cn":"罚球；点球","en":"In sports such as football, rugby, and hockey, a penalty is an opportunity to score a goal, which is given to the attacking team if the defending team breaks a rule near their own goal.","ex":{"en":"Referee Michael Reed had no hesitation in awarding a penalty","cn":"裁判迈克尔·里德毫不犹豫地判了点球。"}},{"pos":"N-COUNT 可数名词","cn":"惩罚；报应；不利后果","en":"The penalty that you pay for something you have done is something unpleasant that you experience as a result.","ex":{"en":"Why should I pay the penalty for somebody else's mistake?","cn":"为什么我要代人受过？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that is done in order to punish someone, or the act of punishing them","cn":""},{"en":"a punishment given by a judge in a court","cn":""},{"en":"an amount of money that you must pay as a punishment","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A penalty is a punishment or consequence for doing something wrong, such as having to pay a fee for not bringing your library book back when it was due."}]},"collocations":{"phrases":["ADJ. harsh, heavy, severe, stiff, strict, tough | light | maximum, minimum | fixed, mandatory a new system of fixed penalties for most traff","VERB + PENALTY impose, introduce | threaten | increase | carry crimes which carry severe penalties | face, incur","PREP. on/under ~ of They made him promise, under penalty of death. | ~ for the penalty for murder | ~ on He threatened stiffer penalties on ","VERB + PENALTY pay, suffer He's now paying the penalty for his misspent youth. People who lose their jobs are suffering the penalties for lo","PREP. ~ for You must accept the penalty for your rash behaviour. | ~ of It's just one of the penalties of fame. 3 in football","ADJ. disputed | winning | first-half, second-half | early, late","VERB + PENALTY award (sb), give (sb) | give away They were leading until Cole gave away a penalty. | appeal for | be awarded/given, get, hav","PENALTY + NOUN area, box, spot | shoot-out"]},"media":{"uk":"media/ldoce/hwd/bre/f/penalty0205.mp3","us":"media/ldoce/hwd/ame/3/penalty.mp3"},"examples":[{"en":"Two minutes later Ford equalized with a penalty.","cn":"两分钟后，福特以一记点球将比分扳平。"},{"en":"We were awarded a penalty after a late tackle.","cn":"对方铲球犯规后，我们得到了一个点球。"}],"oxford":{"phon":"ˈpenəlti","pos":"noun","senses":[{"en":"a punishment for breaking a law, rule or contract","cn":"惩罚；处罚；刑罚","ex":{"en":"to impose a penalty","cn":"予以惩罚"}},{"en":"a disadvantage suffered as a result of something","cn":"害处；不利","ex":{"en":"One of the penalties of fame is loss of privacy.","cn":"成名的弊端之一是失掉了隐私。"}},{"en":"a disadvantage given to a player or a team when they break a rule","cn":"（对犯规者的）判罚，处罚","ex":{"en":"He incurred a ten-second penalty in the first round.","cn":"他在第一轮受到停赛十秒钟的处罚。"}},{"en":"a chance to score a goal or point without any defending players, except the goalkeeper, trying to stop it; the goal or point that is given if it is successful. This chance is given because the other team has broken the rules.","cn":"点球；罚点球得分","ex":{"en":"Two minutes later Ford equalized with a penalty.","cn":"两分钟后，福特以一记点球将比分扳平。"}}]}},"pedigree":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（狗、猫等动物的）血统记录，纯种谱系","en":"If a dog, cat, or other animal has a pedigree, its ancestors are known and recorded. An animal is considered to have a good pedigree when all its known ancestors are of the same type.","ex":{"en":"60 per cent of dogs and ten per cent of cats have pedigrees.","cn":"60%的狗和10%的猫有血统记录。"}},{"pos":"ADJ 形容词","cn":"有纯种谱系证明的；纯种的","en":"A pedigree animal is descended from animals which have all been of a particular type, and is therefore considered to be of good quality.","ex":{"en":"...a pedigree dog.","cn":"纯种狗"}},{"pos":"N-COUNT 可数名词","cn":"背景；出身；门第；世系","en":"Someone's pedigree is their background or their ancestors.","ex":{"en":"Hammer's business pedigree almost guaranteed him the acquaintance of U.S. presidents","cn":"哈默的商业背景几乎保证了他能够结识美国总统。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the parents and other past family members of an animal or person, or an official written record of this 〔","cn":"人的〕家谱﹔〔动物的〕（纯种）系谱"},{"en":"the history and achievements of something or someone, especially when they are good and should be admired 〔","cn":"优秀事物的〕历史﹐过去﹔〔受景仰之人的〕成就﹐成绩"},{"en":"a pedigree animal comes from a family that has been recorded for a long time and is considered to be of a very good breed 〔","cn":"动物〕良种的﹐纯种的"}]},"vocab":{"pos":"n adj","senses":[{"en":"The noun pedigree refers to the genetic background of an animal, although it is sometimes applied to people as well. A purebred dog, for example, comes with a verified pedigree , a list of all past parentage."}]},"collocations":{"phrases":["ADJ. long Hereford cattle have a long pedigree. | distinguished, illustrious, impeccable, impressive","VERB + PEDIGREE prove, show The champions really showed their pedigree today.","PEDIGREE + VERB stretch back These trees have pedigrees stretching back thousands of years.","PEDIGREE + NOUN cat, dog, etc. | breed"]},"media":{"uk":"media/ldoce/hwd/bre/0/pedigree_adj0205.mp3","us":"media/ldoce/hwd/ame/5/pedigree1.mp3"},"examples":[{"en":"The product has a pedigree going back to the last century.","cn":"这项产品的渊源可追溯到上个世纪。"},{"en":"She was proud of her long pedigree.","cn":"她为自己源远流长的家世而自豪。"}],"oxford":{"phon":"ˈpedɪɡriː","pos":"noun","senses":[{"en":"the parents, grandparents, etc. of an animal that are all of the same breed (= type); an official record showing this","cn":"（动物的）纯种谱系，血统记录","g":"[countable]","ex":{"en":"dogs with good pedigrees (= their ancestors are known and of the same breed)","cn":"纯种的狗"}},{"en":"a person’s family history or the background of something, especially when this is impressive","cn":"家谱；门第；世系；起源","g":"[countable, uncountable]","ex":{"en":"She was proud of her long pedigree.","cn":"她为自己源远流长的家世而自豪。"}},{"en":"coming from a family of the same breed that has been officially recorded for a long time and is thought to be of a good quality","cn":"优良品种的；纯种的","ex":{"en":"pedigree sheep","cn":"纯种绵羊"},"pos":"adjective"}]}},"peep":{"collins":{"senses":[{"pos":"VERB 动词","cn":"瞥；偷看；窥视","en":"If you peep, or peep at something, you have a quick look at it, often secretly and quietly.","ex":{"en":"Children came to peep at him round the doorway","cn":"孩子们围在门口偷看他。"}},{"pos":"VERB 动词","cn":"（从隐蔽处）隐现，微微露出","en":"If something peeps out from behind or under something, a small part of it is visible or becomes visible.","ex":{"en":"Purple and yellow flowers peeped up between rocks","cn":"岩石间隐约可见紫色和黄色的花儿。"}},{"pos":"PHRASE 短语","cn":"没听到任何话（或动静）","en":"If you say that you don't hear a peep from someone, you mean that they do not say anything or make any noise.","ex":{"en":"You don't hear a peep from her once she's gone to bed.","cn":"她一睡觉，就不会发出一点儿动静。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to turn your eyes towards someone or something, so that you can see them","cn":""},{"en":"to look at something quickly, especially in order to find or check something","cn":""},{"en":"to look at someone or something for a short time and then look quickly away","cn":""}]},"collocations":{"phrases":["ADV. cautiously | out He peeped out cautiously from behind the door.","PREP. at She was tempted to peep at the letter. | through The child peeped through a crack in the door."]},"media":{"uk":"media/ldoce/hwd/bre/5/peep_las3_br.mp3","us":"media/ldoce/hwd/ame/4/peep1.mp3"},"examples":[{"en":"We caught her peeping through the keyhole.","cn":"她从锁孔偷看时被我们撞着了。"},{"en":"Dave took a quick peep at the last page.","cn":"戴夫迅速地瞟了一下最后一页。"}],"oxford":{"phon":"piːp","pos":"verb","senses":[{"en":"to look quickly and secretly at something, especially through a small opening","cn":"（尤指通过小孔）窥视，偷看","g":"[intransitive]","ex":{"en":"We caught her peeping through the keyhole.","cn":"她从锁孔偷看时被我们撞着了。"}},{"en":"to be just able to be seen","cn":"稍微露出；部分现出","g":"[intransitive]","ex":{"en":"The tower peeped above the trees.","cn":"塔尖从树梢上露出来。"}},{"en":"to make a short high sound; to make something make this sound","cn":"（使）发出尖细的声音，发出吱吱声","g":"[intransitive, transitive]"},{"en":"a quick or secret look at something","cn":"偷偷一瞥","g":"[countable, usually singular]","ex":{"en":"Dave took a quick peep at the last page.","cn":"戴夫迅速地瞟了一下最后一页。"},"pos":"noun"},{"en":"something that somebody says or a sound that somebody makes","cn":"说话；出声音","g":"[singular]","lab":"informal","ex":{"en":"We did not hear a peep out of the baby all night.","cn":"我们整夜都没听到婴儿出声。"},"pos":"noun"},{"en":"a short high sound like the one made by a young bird or by a whistle (= a small metal or plastic tube that you blow to make a high sound)","cn":"啾啾声；短促尖厉声","g":"[countable]","pos":"noun"},{"en":"a word for the sound of a car’s horn, used especially by children","cn":"嘟嘟（指汽车喇叭声，尤为儿语）","g":"[countable]","lab":"British English","pos":"noun"}]}}});
